  private buildCanvasSelectionContextItems(canvasContext: ActiveCanvasContext) {
    return canvasContext.selectedNodes.map((node, index) => {
      const previewSource = node.text.trim() || node.id;
      const previewText = previewSource.replace(/\s+/g, " ").trim();
      const shortPreview = previewText.length > 80 ? `${previewText.slice(0, 80)}...` : previewText;
      const title = node.text.length > 140 ? `${node.text.slice(0, 140)}...` : node.text;

      return {
        label: this.getCanvasContextNodeLabel(node, canvasContext.anchorNode?.id, index),
        preview: `${shortPreview} (${node.text.length.toLocaleString()} ${t("characters")})`,
        title: title || node.id,
      };
    });
  }

  private getCanvasContextNodeLabel(node: CanvasNodeSummary, anchorNodeId?: string | null, index: number = 0): string {
    const firstMeaningfulLine = node.text
      .split("\n")
      .map((line) => line.replace(/^#+\s*/, "").trim())
      .find(Boolean);
    const shortTitle = firstMeaningfulLine && firstMeaningfulLine.length > 28
      ? `${firstMeaningfulLine.slice(0, 28)}...`
      : firstMeaningfulLine;
    const role = anchorNodeId && node.id === anchorNodeId ? t("Focused") : `${t("Selected")} ${index + 1}`;

    return shortTitle
      ? `${role} · ${shortTitle}`
      : `${role} · ${node.type}`;
  }

  private async generateCanvasDerivedMarkdown(
    canvasContext: ActiveCanvasContext,
    instruction: string,
    mode: "article" | "slides",
    additionalContext?: string,
  ): Promise<boolean> {
    try {
      const source = await buildCanvasDocumentSource(this.plugin, canvasContext);
      new Notice(mode === "article"
        ? t("Canvas AI is drafting an article...")
        : t("Canvas AI is drafting slides..."));

      let response = "";
      for await (const chunk of this.aiService.rewrite({
        selectedText: source.text,
        instruction: "custom",
        customPrompt: mode === "article"
          ? this.buildCanvasArticlePrompt(instruction, source.scope)
          : this.buildCanvasSlidesPrompt(instruction, source.scope),
        context: this.mergeAIContext(canvasContext.contextText, additionalContext),
      })) {
        response += chunk;
      }

      const normalizedMarkdown = this.normalizeCanvasGeneratedMarkdown(response);
      if (!normalizedMarkdown) {
        throw new Error(t("Canvas AI did not return any usable Markdown."));
      }

      const createdFile = await this.createCanvasMarkdownFile(canvasContext, mode, normalizedMarkdown);
      const targetLeaf = this.plugin.app.workspace.getLeaf(true);
      await targetLeaf.openFile(createdFile);
      new Notice(`${t("Created AI file:")} ${createdFile.path}`);
      return true;
    } catch (error) {
      const message = getAIErrorMessage(error);
      new Notice(message);
      console.error("[Canvas AI] Failed to generate derived markdown:", error);
      return false;
    }
  }

  private async withCanvasToolbarBusyState<T>(view: ActiveCanvasContext["view"], task: () => Promise<T>): Promise<T> {
    const container = (view as ActiveCanvasContext["view"] & { containerEl?: HTMLElement }).containerEl;
    if (!container) {
      return task();
    }

    const ownerDocument = container.ownerDocument;
    const busyScope = ownerDocument?.body ?? ownerDocument?.documentElement ?? null;

    if (busyScope) {
      const currentToolbarBusyCount = Number.parseInt(busyScope.getAttribute(TOOLBAR_AI_BUSY_COUNT_ATTR) ?? "0", 10);
      const nextToolbarBusyCount = Number.isFinite(currentToolbarBusyCount) ? currentToolbarBusyCount + 1 : 1;
      busyScope.setAttribute(TOOLBAR_AI_BUSY_COUNT_ATTR, String(nextToolbarBusyCount));
      busyScope.setAttribute(TOOLBAR_AI_BUSY_ATTR, "true");
    }

    try {
      return await task();
    } finally {
      if (busyScope) {
        const activeToolbarBusyCount = Number.parseInt(busyScope.getAttribute(TOOLBAR_AI_BUSY_COUNT_ATTR) ?? "1", 10);
        const remainingToolbarBusyCount = Number.isFinite(activeToolbarBusyCount) ? Math.max(activeToolbarBusyCount - 1, 0) : 0;

        if (remainingToolbarBusyCount > 0) {
          busyScope.setAttribute(TOOLBAR_AI_BUSY_COUNT_ATTR, String(remainingToolbarBusyCount));
        } else {
          busyScope.removeAttribute(TOOLBAR_AI_BUSY_COUNT_ATTR);
          busyScope.removeAttribute(TOOLBAR_AI_BUSY_ATTR);
        }
      }
    }
  }

  private normalizeCanvasGeneratedMarkdown(content: string): string {
    const trimmed = content.trim();
    if (!trimmed) {
      return "";
    }

    return trimmed
      .replace(/^```(?:markdown|md)?\s*/i, "")
      .replace(/\s*```$/i, "")
      .trim()
      .concat("\n");
  }

  private async createCanvasMarkdownFile(
    canvasContext: ActiveCanvasContext,
    mode: "article" | "slides",
    content: string,
  ) {
    const parentPath = canvasContext.file.parent?.path && canvasContext.file.parent.path !== "/"
      ? canvasContext.file.parent.path
      : "";
    const suffix = mode === "article" ? t("AI Article Draft") : t("AI Slides");
    const filePath = await this.getAvailableArtifactPath(parentPath, `${canvasContext.file.basename} ${suffix}`, "md");
    return this.plugin.app.vault.create(filePath, content);
  }

  private resolveTextInputInstruction(
    rawInstruction: string | undefined,
    meta?: ITextInputSubmitMeta,
    fieldKey: string = "instruction",
  ): string {
    const rawValue = rawInstruction?.trim() || "";
    const cleanedValue = meta?.cleanedResult?.[fieldKey]?.trim() || "";
    const referencedItems = meta?.linkedContextByField?.[fieldKey] ?? [];

    if (referencedItems.length === 0) {
      return rawValue;
    }

    const nonReferenceText = rawValue.replace(/\[\[[^\]]+\]\]/g, "").trim();
    if (!nonReferenceText) {
      return cleanedValue || rawValue;
    }

    return nonReferenceText;
  }

  private buildLinkedNotesAdditionalContext(
    meta?: ITextInputSubmitMeta,
    fieldKey: string = "instruction",
  ): string | undefined {
    const referencedItems = meta?.linkedContextByField?.[fieldKey] ?? [];
    if (referencedItems.length === 0) {
      return undefined;
    }

    return referencedItems
      .map((item) => `<context source="Referenced note ${item.reference}">\n${item.content}\n</context>`)
      .join("\n\n");
  }

  private buildLinkedNotesPrimarySource(
    meta?: ITextInputSubmitMeta,
    fieldKey: string = "instruction",
  ): string | undefined {
    const referencedItems = meta?.linkedContextByField?.[fieldKey] ?? [];
    if (referencedItems.length === 0) {
      return undefined;
    }

    return referencedItems
      .map((item, index) => [
        `source_index: ${index + 1}`,
        `source_reference: ${item.reference}`,
        `source_path: ${item.filePath}`,
        "source_content:",
        item.content,
      ].join("\n"))
      .join("\n\n");
  }

  private mergeAIContext(baseContext: string, additionalContext?: string): string {
    const extraContext = additionalContext?.trim();
    if (!extraContext) {
      return baseContext;
    }

    const normalizedBaseContext = baseContext.trim();
    if (!normalizedBaseContext) {
      return extraContext;
    }

    return `${normalizedBaseContext}\n\n${extraContext}`;
  }

  private async startFrontmatterGeneration(editor: Editor | null | undefined, prompt: string): Promise<boolean> {
    if (!this.plugin.settings.ai.enabled) {
      new Notice(t("AI features are disabled in settings."));
      return false;
    }

    const resolvedEditor = this.resolveEditor(editor);
    const view = this.getEditorView(resolvedEditor);
    if (!resolvedEditor || !view) {
      new Notice(t("Current editor does not support AI rewrite."));
      return false;
    }

    const fullText = (resolvedEditor as any).getValue?.() ?? "";
    const frontmatterRange = this.findFrontmatterRange(fullText);
    const noteBody = frontmatterRange
      ? `${fullText.slice(0, frontmatterRange.from)}${fullText.slice(frontmatterRange.to)}`.trim()
      : fullText.trim();

    const contextParts = [
      "current_note_scope: whole_note",
      frontmatterRange ? "current_note_has_frontmatter: true" : "current_note_has_frontmatter: false",
    ];

    const currentFrontmatter = frontmatterRange ? fullText.slice(frontmatterRange.from, frontmatterRange.to).trim() : "";
    if (currentFrontmatter) {
      contextParts.push("current_note_frontmatter:", currentFrontmatter);
    }

    const frontmatterStyleSummary = this.buildFrontmatterStyleSummary();
    if (frontmatterStyleSummary.context) {
      contextParts.push(frontmatterStyleSummary.context);
    }

    const frontmatterPrompt = this.buildFrontmatterGenerationPrompt(prompt, noteBody);
    if (frontmatterPrompt.usesCustomSettings) {
      contextParts.push("requested_frontmatter_properties:", frontmatterPrompt.properties);
      contextParts.push(`frontmatter_output_language: ${frontmatterPrompt.language}`);
    }

    view.dispatch({
      effects: startRewriteEffect.of({
        from: frontmatterRange?.from ?? 0,
        to: frontmatterRange?.to ?? 0,
        originalText: frontmatterPrompt.includeNoteAsTarget ? noteBody : "",
        instruction: "custom",
        customPrompt: frontmatterPrompt.prompt,
        context: contextParts.join("\n\n"),
        artifactKind: "frontmatter",
        preferredFrontmatterKeys: frontmatterStyleSummary.preferredAliases,
      }),
    });
    return true;
  }

  private buildFrontmatterGenerationPrompt(
    fallbackPrompt: string,
    noteBody: string,
  ): { prompt: string; includeNoteAsTarget: boolean; properties: string; language: string; usesCustomSettings: boolean } {
    const settings = this.plugin.settings.ai.frontmatterPrompt;
    if (settings?.mode !== "custom") {
      return {
        prompt: fallbackPrompt,
        includeNoteAsTarget: true,
        properties: "",
        language: "auto",
        usesCustomSettings: false,
      };
    }

    const properties = settings.properties?.trim() || "Infer the most useful YAML properties from the note.";
    const language = settings.language?.trim() || "auto";
    const template = settings.prompt?.trim() || fallbackPrompt;
    const includesNotePlaceholder = /\{note\}/.test(template);
    const prompt = template
      .replace(/\{note\}/g, noteBody)
      .replace(/\{properties\}/g, properties)
      .replace(/\{language\}/g, language);

    return {
      prompt,
      includeNoteAsTarget: !includesNotePlaceholder,
      properties,
      language,
      usesCustomSettings: true,
    };
  }

  private findFrontmatterRange(text: string): { from: number; to: number } | null {
    const match = text.match(/^---\r?\n[\s\S]*?\r?\n---\r?\n?/);
    if (!match || match.index !== 0) {
      return null;
    }

    return {
      from: 0,
      to: match[0].length,
    };
  }

  private buildFrontmatterStyleSummary(): { context: string; preferredAliases: Record<string, string> } {
    const activeFile = this.plugin.app.workspace.getActiveFile();
    const allMarkdownFiles = ((this.plugin.app.vault as any).getMarkdownFiles?.() ?? []) as Array<any>;
    if (!activeFile || allMarkdownFiles.length === 0) {
      return { context: "", preferredAliases: {} };
    }

    const siblingFiles = allMarkdownFiles
      .filter((file) => file?.path !== activeFile.path && file?.parent?.path === activeFile.parent?.path)
      .slice(0, 48);

    const siblingStats = this.collectFrontmatterStats(siblingFiles, 6);
    const shouldFallbackToVault = this.shouldFallbackToVaultFrontmatterStats(siblingStats);
    const vaultStats = shouldFallbackToVault
      ? this.getVaultFrontmatterStats(allMarkdownFiles)
      : this.createEmptyFrontmatterStats();
    const preferredAliases = this.buildPreferredFrontmatterAliases(siblingStats.keyCounts, vaultStats.keyCounts);

    const contextParts: string[] = [];

    if (siblingStats.examples.length > 0) {
      const commonKeys = [...siblingStats.keyCounts.entries()]
        .sort((left, right) => right[1] - left[1])
        .slice(0, 10)
        .map(([key, count]) => `- ${key} (${count})`)
        .join("\n");

      contextParts.push(
        [
          `same_folder_path: ${activeFile.parent?.path || ""}`,
          "same_folder_frontmatter_common_keys:",
          commonKeys,
          "same_folder_frontmatter_examples:",
          ...siblingStats.examples,
        ].join("\n"),
      );
    }

    const vaultCommonKeys = shouldFallbackToVault
      ? [...vaultStats.keyCounts.entries()]
        .sort((left, right) => right[1] - left[1])
        .slice(0, 14)
        .map(([key, count]) => `- ${key} (${count})`)
        .join("\n")
      : "";

    if (shouldFallbackToVault && vaultCommonKeys) {
      contextParts.push([
        "vault_frontmatter_high_frequency_keys:",
        vaultCommonKeys,
      ].join("\n"));
    }

    const aliasPreferenceLines = Object.entries(preferredAliases)
      .map(([fromKey, toKey]) => `- prefer ${toKey} over ${fromKey}`);

    if (aliasPreferenceLines.length > 0) {
      contextParts.push([
        "preferred_frontmatter_key_aliases:",
        ...aliasPreferenceLines,
      ].join("\n"));
    }

    return {
      context: contextParts.join("\n\n"),
      preferredAliases,
    };
  }

  private collectFrontmatterStats(files: Array<any>, exampleLimit: number): FrontmatterStats {
    const keyCounts = new Map<string, number>();
    const examples: string[] = [];
    let fileCount = 0;

    for (const file of files) {
      const cache = (this.plugin.app.metadataCache as any)?.getFileCache?.(file);
      const frontmatter = cache?.frontmatter;
      if (!frontmatter || typeof frontmatter !== "object") {
        continue;
      }

      const entries = Object.entries(frontmatter)
        .filter(([key]) => key !== "position")
        .slice(0, 8);

      if (entries.length === 0) {
        continue;
      }

      fileCount += 1;

      entries.forEach(([key]) => {
        keyCounts.set(key, (keyCounts.get(key) ?? 0) + 1);
      });

      if (exampleLimit > 0 && examples.length < exampleLimit) {
        const formatted = entries
          .map(([key, value]) => `  ${key}: ${this.serializeFrontmatterValue(value)}`)
          .join("\n");
        examples.push(`${file.basename}:\n${formatted}`);
      }

      if (exampleLimit > 0 && examples.length >= exampleLimit) {
        continue;
      }
    }

    return {
      keyCounts,
      examples,
      fileCount,
    };
  }

  private createEmptyFrontmatterStats(): {
    keyCounts: Map<string, number>;
    examples: string[];
    fileCount: number;
  } {
    return {
      keyCounts: new Map<string, number>(),
      examples: [],
      fileCount: 0,
    };
  }

  private getVaultFrontmatterStats(allMarkdownFiles: Array<any>): FrontmatterStats {
    const now = Date.now();
    const cached = this.vaultFrontmatterStatsCache;
    if (
      cached &&
      cached.expiresAt > now &&
      cached.sourceFileCount === allMarkdownFiles.length
    ) {
      return cached.stats;
    }

    const stats = this.collectFrontmatterStats(allMarkdownFiles, 0);
    this.vaultFrontmatterStatsCache = {
      expiresAt: now + VAULT_FRONTMATTER_STATS_CACHE_TTL,
      sourceFileCount: allMarkdownFiles.length,
      stats,
    };
    return stats;
  }

  private invalidateFrontmatterStatsCache(): void {
    this.vaultFrontmatterStatsCache = null;
  }

  private shouldFallbackToVaultFrontmatterStats(stats: {
    keyCounts: Map<string, number>;
    examples: string[];
    fileCount: number;
  }): boolean {
    const distinctKeyCount = stats.keyCounts.size;
    const strongSiblingSample = stats.fileCount >= 6;
    const mediumSiblingSample = stats.fileCount >= 3 && distinctKeyCount >= 6;
    const aliasSignal = this.hasStrongSiblingAliasSignal(stats.keyCounts);

    return !(strongSiblingSample || mediumSiblingSample || aliasSignal);
  }

  private hasStrongSiblingAliasSignal(keyCounts: Map<string, number>): boolean {
    const aliasGroups = [
      ["tags", "tag"],
      ["aliases", "alias"],
      ["status", "state"],
      ["cssclasses", "cssclass"],
    ];

    return aliasGroups.some((group) => group.some((key) => (keyCounts.get(key) ?? 0) >= 2));
  }

  private buildPreferredFrontmatterAliases(
    siblingCounts: Map<string, number>,
    vaultCounts: Map<string, number>,
  ): Record<string, string> {
    const aliasGroups = [
      ["tags", "tag"],
      ["aliases", "alias"],
      ["status", "state"],
      ["cssclasses", "cssclass"],
    ];
    const preferredAliases: Record<string, string> = {};

    for (const group of aliasGroups) {
      const ranked = group
        .map((key) => ({
          key,
          siblingCount: siblingCounts.get(key) ?? 0,
          vaultCount: vaultCounts.get(key) ?? 0,
        }))
        .sort((left, right) => {
          if (right.siblingCount !== left.siblingCount) {
            return right.siblingCount - left.siblingCount;
          }
          return right.vaultCount - left.vaultCount;
        });

      const preferred = ranked[0];
      if (!preferred || (preferred.siblingCount === 0 && preferred.vaultCount === 0)) {
        continue;
      }

      ranked.slice(1).forEach((entry) => {
        if (entry.siblingCount > 0 || entry.vaultCount > 0) {
          preferredAliases[entry.key] = preferred.key;
        }
      });
    }

    return preferredAliases;
  }

  private serializeFrontmatterValue(value: unknown): string {
    if (Array.isArray(value)) {
      return `[${value.map((item) => this.serializeFrontmatterValue(item)).join(", ")}]`;
    }

    if (value && typeof value === "object") {
      return JSON.stringify(value);
    }

    if (typeof value === "string") {
      return value;
    }

    return String(value);
  }

  private async createGeneratedArtifact(request: RewriteArtifactRequest): Promise<RewriteArtifactResult> {
    const activeFile = this.plugin.app.workspace.getActiveFile();
    const parentPath = activeFile?.parent?.path && activeFile.parent.path !== "/" ? activeFile.parent.path : "";
    const sourceBaseName = (activeFile?.basename || t("Untitled")).trim();
    const sanitizedBaseName = sourceBaseName.replace(/[\\/:*?"<>|]/g, " ").replace(/\s+/g, " ").trim() || t("Untitled");
    const extension = request.kind === "canvas" ? "canvas" : "base";
    const suffix = request.kind === "canvas" ? t("AI Canvas File") : t("AI Base File");
    const filePath = await this.getAvailableArtifactPath(parentPath, `${sanitizedBaseName} ${suffix}`, extension);
    const content = normalizeGeneratedArtifactContent(request);

    await this.plugin.app.vault.create(filePath, content);
    new Notice(`${t("Created AI file:")} ${filePath}`);

    return {
      path: filePath,
      embedSyntax: `![[${filePath}]]`,
    };
  }

  private async getAvailableArtifactPath(parentPath: string, baseName: string, extension: string): Promise<string> {
    let counter = 0;
    while (counter < 200) {
      const suffix = counter === 0 ? "" : ` ${counter + 1}`;
      const filename = `${baseName}${suffix}.${extension}`;
      const path = parentPath ? `${parentPath}/${filename}` : filename;
      if (!this.plugin.app.vault.getAbstractFileByPath(path)) {
        return path;
      }
      counter += 1;
    }

    throw new Error(t("Unable to allocate a file name for the generated artifact."));
  }

  openCustomRewrite(editor?: Editor | null): boolean {
    const resolvedEditor = this.resolveEditor(editor);
    const view = this.getEditorView(resolvedEditor);
    if (!resolvedEditor || !view) {
      new Notice(t("Current editor does not support AI rewrite."));
      return false;
    }

    const selectedText = resolvedEditor.getSelection();
    this.inlineCustomPromptEditor = resolvedEditor;
    this.renderInlineCustomPrompt(resolvedEditor, view, selectedText);
    return true;
  }

  closeInlineCustomPrompt(): void {
    this.inlineCustomPromptCleanup.forEach((cleanup) => cleanup());
    this.inlineCustomPromptCleanup = [];
    this.inlineCustomPromptTextarea = null;
    this.inlineCustomPromptEditor = null;

    if (this.inlineCustomPromptEl) {
      this.inlineCustomPromptEl.remove();
      this.inlineCustomPromptEl = null;
    }
  }

  private renderInlineCustomPrompt(editor: Editor, view: EditorView, initialSelection?: string): void {
    const doc = view.dom.ownerDocument;
    if (!this.inlineCustomPromptEl) {
      const promptEl = doc.createDiv();
      promptEl.className = "editing-toolbar-ai-inline-prompt";
      const header = doc.createDiv();
      header.className = "editing-toolbar-ai-inline-prompt-header";
      const dragHandle = doc.createDiv();
      dragHandle.className = "editing-toolbar-ai-inline-prompt-drag-handle";
      dragHandle.setCssStyles({ cursor: "grab" });
      const titleEl = doc.createDiv();
      titleEl.className = "editing-toolbar-ai-inline-prompt-title";
      titleEl.textContent = t("AI Custom Rewrite");
      const closeBtn = doc.createEl("button");
      closeBtn.type = "button";
      closeBtn.className = "editing-toolbar-ai-inline-prompt-close";
      closeBtn.title = t("Close");
      safeSetInnerHTML(closeBtn, `<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M18 6L6 18M6 6l12 12"/></svg>`);
      header.append(dragHandle, titleEl, closeBtn);
      const settingsBtn = doc.createEl("button");
      settingsBtn.type = "button";
      settingsBtn.className = "editing-toolbar-ai-inline-prompt-settings";
      settingsBtn.title = t("Manage Templates");
      safeSetInnerHTML(settingsBtn, `<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="3"/><path d="M12 1v6m0 6v6M4.22 4.22l4.24 4.24m5.08 5.08l4.24 4.24M1 12h6m6 0h6M4.22 19.78l4.24-4.24m5.08-5.08l4.24-4.24"/></svg>`);

      const inputWrapper = doc.createDiv();
      inputWrapper.className = "editing-toolbar-ai-inline-prompt-input-wrapper";

      const textarea = doc.createEl("textarea");
      textarea.className = "editing-toolbar-ai-inline-prompt-input";
      textarea.placeholder = t("Describe what you want AI to do...");
      textarea.rows = 3;
      textarea.wrap = "soft";

      const historyBtn = doc.createEl("button");
      historyBtn.type = "button";
      historyBtn.className = "editing-toolbar-ai-inline-prompt-history-btn";
      historyBtn.title = t("History");
      safeSetInnerHTML(historyBtn, `<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M3 12a9 9 0 1 0 9-9 9.75 9.75 0 0 0-6.74 2.74L3 8"/><path d="M3 3v5h5"/><path d="M12 7v5l4 2"/></svg>`);

      const historyDropdown = doc.createDiv();
      historyDropdown.className = "editing-toolbar-ai-inline-prompt-history-dropdown";
      historyDropdown.setCssStyles({ display: "none" });

      const mentionDropdown = doc.createDiv();
      mentionDropdown.className = "editing-toolbar-ai-inline-prompt-mention-dropdown";
      mentionDropdown.setCssStyles({ display: "none" });
   const sendBtn = doc.createEl("button");
      sendBtn.type = "button";
      sendBtn.className = "editing-toolbar-ai-inline-prompt-send-btn";
      safeSetInnerHTML(sendBtn, `<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M22 2L11 13M22 2l-7 20-4-9-9-4 20-7z"/></svg>`);
      sendBtn.title = t("Send");

      inputWrapper.append(textarea, historyBtn, historyDropdown, mentionDropdown,sendBtn);

      const templatesContainer = doc.createDiv();
      templatesContainer.className = "editing-toolbar-ai-inline-prompt-templates";

      const templates = this.plugin.settings.ai.customPromptTemplates || [];

      const replaceTemplateVariables = (template: string): string => {
        const currentFile = this.plugin.app.workspace.getActiveFile();
        const currentEditor = this.resolveEditor();
        const now = new Date();

        const currentSelection = currentEditor?.getSelection() || "";
        const currentContent = currentEditor?.getValue() || "";

        if (template.includes("{{selection}}") && currentSelection) {
          if (!contextList.some(c => c.type === "selection")) {
            contextList.push({
              type: "selection",
              content: currentSelection,
              label: this.getSelectedTextContextLabel(),
            });
          } else {
            const selectionCtx = contextList.find(c => c.type === "selection");
            if (selectionCtx) {
              selectionCtx.content = currentSelection;
            }
          }
        }

        if (template.includes("{{file:content}}")) {
          const compactedContent = compactContent(currentContent);
          if (!contextList.some(c => c.type === "doc")) {
            contextList.push({
              type: "doc",
              content: compactedContent,
              label: this.getCurrentDocumentContextLabel(currentFile?.basename),
            });
          } else {
            const docCtx = contextList.find(c => c.type === "doc");
            if (docCtx) {
              docCtx.content = compactedContent;
              docCtx.label = this.getCurrentDocumentContextLabel(currentFile?.basename);
            }
          }
        }

        return template
          .replace(/\{\{selection\}\}/g, currentSelection ? this.getSelectedTextPlaceholder() : "")
          .replace(/\{\{file:path\}\}/g, currentFile?.path || "")
          .replace(/\{\{file:content\}\}/g, currentFile?.basename ? `[[${currentFile.basename}]]` : "")
          .replace(/\{\{date\}\}/g, now.toLocaleDateString())
          .replace(/\{\{time\}\}/g, now.toLocaleTimeString())
          .replace(/\{\{datetime\}\}/g, now.toLocaleString())
          .replace(/\{\{vault:name\}\}/g, this.plugin.app.vault.getName());
      };

      templates.slice(0, 9).forEach((template) => {
        const templateBtn = doc.createEl("button");
        templateBtn.type = "button";
        templateBtn.className = "editing-toolbar-ai-inline-prompt-template-btn";
        templateBtn.textContent = template.name;
        templateBtn.title = template.prompt;
        templateBtn.addEventListener("click", async () => {
          textarea.value = replaceTemplateVariables(template.prompt);
          renderContextItems();
          resizeTextarea();
          updateSendButtonState();
          textarea.focus();
          // 等待双链内容加载完成
          await syncLinkedNotesContext();
        });
        templatesContainer.appendChild(templateBtn);
      });

      const contextContainer = doc.createDiv();
      contextContainer.className = "editing-toolbar-ai-inline-prompt-context";
      contextContainer.setCssStyles({ display: "none" });

      const contextList: Array<{type: string, content: string, label: string}> = [];

      if (initialSelection) {
        contextList.push({
          type: "selection",
          content: initialSelection,
          label: this.getSelectedTextContextLabel(),
        });
      }

      const renderContextItems = () => {
        contextContainer.empty();
        if (contextList.length === 0) {
          contextContainer.setCssStyles({ display: "none" });
          return;
        }
        contextContainer.setCssStyles({ display: "block" });
        contextList.forEach((ctx, index) => {
          const item = doc.createDiv();
          item.className = "editing-toolbar-ai-inline-prompt-context-item";

          const label = doc.createSpan();
          label.className = "editing-toolbar-ai-inline-prompt-context-label";
          label.textContent = ctx.label;

          const preview = doc.createSpan();
          preview.className = "editing-toolbar-ai-inline-prompt-context-preview";
          const previewText = ctx.content.substring(0, 50).replace(/\n/g, " ");
          const suffix = ctx.content.length > 50 ? "..." : "";
          const charCount = `(${ctx.content.length.toLocaleString()} ${t("characters")})`;
          preview.textContent = `${previewText}${suffix} ${charCount}`;
          preview.title = ctx.content.length > 100 ? ctx.content.substring(0, 100) + "..." : ctx.content;

          const removeBtn = doc.createEl("button");
          removeBtn.type = "button";
          removeBtn.className = "editing-toolbar-ai-inline-prompt-context-remove";
          safeSetInnerHTML(removeBtn, `<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M18 6L6 18M6 6l12 12"/></svg>`);
          removeBtn.addEventListener("click", () => {
            // 从上下文列表移除
            contextList.splice(index, 1);

            // 同步删除输入框中的占位符
            if (ctx.type === "selection") {
              this.getSelectedTextPlaceholderVariants().forEach((placeholder) => {
                textarea.value = textarea.value.replace(placeholder, "");
              });
            } else if (ctx.type === "note" || ctx.type === "doc") {
              // 提取文件名并删除对应的双链
              const fileName = ctx.label.replace(/^📄 |^📋 /, "");
              textarea.value = textarea.value.replace(`[[${fileName}]]`, "");
            }

            renderContextItems();
          });

          item.append(label, preview, removeBtn);
          contextContainer.appendChild(item);
        });
      };

      renderContextItems();

      const footer = doc.createDiv();
      footer.className = "editing-toolbar-ai-inline-prompt-footer";
      const hint = doc.createDiv();
      hint.className = "editing-toolbar-ai-inline-prompt-hint";
      const promptHint = Platform.isMobileApp
        ? t("Enter inserts a newline. Tap Send to submit.")
        : t("Press Enter to send, Shift+Enter for newline, Esc to close.");
      hint.textContent = promptHint  ;


      footer.appendChild(hint);

      promptEl.append(header, inputWrapper, templatesContainer, contextContainer, footer);
      doc.body.appendChild(promptEl);

      let isDragging = false;
      let offsetX = 0;
      let offsetY = 0;

      const onDragStart = (e: MouseEvent | TouchEvent) => {
        if (e.target !== dragHandle && e.target !== titleEl) return;

        isDragging = true;
        const clientX = 'touches' in e ? e.touches[0].clientX : e.clientX;
        const clientY = 'touches' in e ? e.touches[0].clientY : e.clientY;

        const rect = promptEl.getBoundingClientRect();
        offsetX = clientX - rect.left;
        offsetY = clientY - rect.top;

        promptEl.setCssStyles({ cursor: 'grabbing' });
        dragHandle.setCssStyles({ cursor: 'grabbing' });

        if ('touches' in e) {
          e.preventDefault();
        }
      };

      const onDrag = (e: MouseEvent | TouchEvent) => {
        if (!isDragging) return;

        e.preventDefault();
        const clientX = 'touches' in e ? e.touches[0].clientX : e.clientX;
        const clientY = 'touches' in e ? e.touches[0].clientY : e.clientY;

        const newLeft = clientX - offsetX;
        const newTop = clientY - offsetY;

        promptEl.style.left = `${newLeft}px`;
        promptEl.style.top = `${newTop}px`;
      };

      const onDragEnd = () => {
        isDragging = false;
        promptEl.setCssStyles({ cursor: '' });
        dragHandle.setCssStyles({ cursor: 'grab' });
      };

      dragHandle.addEventListener('mousedown', onDragStart);
      titleEl.addEventListener('mousedown', onDragStart);
      dragHandle.addEventListener('touchstart', onDragStart, { passive: false });
      titleEl.addEventListener('touchstart', onDragStart, { passive: false });

      doc.addEventListener('mousemove', onDrag);
      doc.addEventListener('touchmove', onDrag, { passive: false });

      doc.addEventListener('mouseup', onDragEnd);
      doc.addEventListener('touchend', onDragEnd);

      const resizeTextarea = () => {
        textarea.setCssStyles({ height: "auto" });
        const newHeight = Math.min(Math.max(textarea.scrollHeight, 56), 240);
        textarea.style.height = `${newHeight}px`;

        // 如果内容超过最大高度，显示滚动条
        if (textarea.scrollHeight > 240) {
          textarea.setCssStyles({ overflowY: "auto" });
        } else {
          textarea.setCssStyles({ overflowY: "hidden" });
        }
      };

      const closePrompt = () => {
        this.closeInlineCustomPrompt();
        editor.focus();
      };

      const submitPrompt = async () => {
        const prompt = textarea.value.trim();
        if (!prompt) {
          return;
        }

        if ((await this.getToolbarRouteState()) === "unavailable") {
          new Notice(await this.getProviderRouteStatusText());
          return;
        }

        const activePromptEditor = this.inlineCustomPromptEditor ?? editor;
        const hasSelectedText = activePromptEditor.getSelection().trim().length > 0;
        const hasReferencedNotes = /\[\[[^\]]+\]\]/.test(prompt);
        const shouldPreferBlockFallback = !hasSelectedText && !hasReferencedNotes;

        // 移除占位符，保留用户指令语义
        let cleanPrompt = prompt.replace(/\[\[([^\]]+)\]\]/g, "$1");
        this.getSelectedTextPlaceholderVariants().forEach((placeholder) => {
          const selectedTextPlaceholderPattern = new RegExp(this.escapeRegExp(placeholder), "g");
          cleanPrompt = cleanPrompt.replace(selectedTextPlaceholderPattern, t("Selected text"));
        });
        cleanPrompt = cleanPrompt.trim();

        // 历史记录保留用户输入原貌，避免丢失双链等语义标记
        if (prompt) {
          this.addToHistory(prompt);
        }

        const effectiveContextList = contextList.filter((ctx) => {
          if (!ctx.content.trim()) {
            return false;
          }

          if (hasSelectedText && ctx.type === "selection") {
            return false;
          }

          return true;
        });

        // contextList 已经包含所有上下文（通过 syncLinkedNotesContext 和模板变量添加）
        const contextText = effectiveContextList.length > 0
          ? effectiveContextList.map(ctx => `<context source="${ctx.label}">\n${ctx.content}\n</context>`).join("\n\n")
          : "";

        const result = await this.startRewrite(
          activePromptEditor,
          "custom",
          cleanPrompt,
          {
            additionalContext: contextText,
            preferBlockWhenCollapsed: shouldPreferBlockFallback,
          }
        );
        if (result) {
          this.closeInlineCustomPrompt();
        }
      };

      const updateHistoryDropdown = () => {
        const history = this.plugin.settings.ai.customPromptHistory || [];
        historyDropdown.empty();

        if (history.length === 0) {
          const emptyItem = doc.createDiv();
          emptyItem.className = "editing-toolbar-ai-inline-prompt-history-empty";
          emptyItem.textContent = t("No history");
          historyDropdown.appendChild(emptyItem);
        } else {
          history.forEach((item, index) => {
            const historyItem = doc.createDiv();
            historyItem.className = "editing-toolbar-ai-inline-prompt-history-item";
            historyItem.textContent = item.length > 50 ? item.substring(0, 50) + "..." : item;
            historyItem.title = item;
            historyItem.addEventListener("click", async () => {
              textarea.value = item;
              historyDropdown.setCssStyles({ display: "none" });
              resizeTextarea();
              updateSendButtonState();
              textarea.focus();
              // 重新加载双链内容
              await syncLinkedNotesContext();
            });
            historyDropdown.appendChild(historyItem);
          });
        }
      };

      historyBtn.addEventListener("click", (e) => {
        e.stopPropagation();
        const isVisible = historyDropdown.style.display !== "none";
        historyDropdown.style.display = isVisible ? "none" : "block";
        if (!isVisible) {
          updateHistoryDropdown();
        }
      });

      doc.addEventListener("click", (e) => {
        if (!historyDropdown.contains(e.target as Node) && e.target !== historyBtn) {
          historyDropdown.setCssStyles({ display: "none" });
        }
      });

      const reposition = () => this.positionInlineCustomPrompt(editor, view);
      const updateSendButtonState = () => {
        sendBtn.disabled = textarea.value.trim().length === 0;
      };

      closeBtn.addEventListener("click", closePrompt);
      settingsBtn.addEventListener("click", () => {
        this.plugin.app.setting.open();
        this.plugin.app.setting.openTabById("editing-toolbar");
        window.setTimeout(() => {
          const tabsContainer = this.plugin.app.setting.activeTab?.containerEl?.querySelector(".editing-toolbar-tabs");
          if (tabsContainer) {
            const aiTab = Array.from(tabsContainer.children).find((el: HTMLElement) =>
              el.textContent?.includes("AI") || el.getAttribute("data-tab") === "ai"
            ) as HTMLElement;
            aiTab?.click();
          }
        }, 100);
        closePrompt();
      });
      sendBtn.addEventListener("click", () => {
        void submitPrompt();
      });
      let linkStartPos = -1;
      let selectedSuggestionIndex = 0;
      let suggestionFiles: any[] = [];

      const syncLinkedNotesContext = async () => {
        const text = textarea.value;
        const linkMatches = Array.from(text.matchAll(/\[\[([^\]]+)\]\]/g));
        const linkedFileNames = new Set(linkMatches.map(m => m[1]));

        // 移除不再存在的双链对应的上下文
        const existingLinkedNotes = contextList.filter(c => c.type === "note");
        for (const ctx of existingLinkedNotes) {
          const fileName = ctx.label.replace("📄 ", "");
          if (!linkedFileNames.has(fileName)) {
            const index = contextList.indexOf(ctx);
            if (index > -1) {
              contextList.splice(index, 1);
            }
          }
        }

        // 添加新的双链对应的上下文
        for (const linkText of linkedFileNames) {
          // 检查是否已存在(包括 type="note" 和 type="doc")
          const alreadyExists = contextList.some(c =>
            (c.type === "note" || c.type === "doc") &&
            (c.label.includes(linkText) || c.label.replace(/^📄 |^📋 /, "") === linkText)
          );

          if (alreadyExists) {
            continue;
          }

          const file = this.plugin.app.metadataCache.getFirstLinkpathDest(linkText, "");
          if (file) {
            try {
              const rawContent = await this.plugin.app.vault.cachedRead(file);
              const content = compactContent(rawContent);
              contextList.push({
                type: "note",
                content: content,
                label: `📄 ${file.basename}`
              });
            } catch (e) {
              console.error(`Failed to read linked file: ${linkText}`, e);
            }
          }
        }

        renderContextItems();
      };

      const selectSuggestion = async (file: any) => {
        const cursorPos = textarea.selectionStart;
        const beforeLink = textarea.value.substring(0, linkStartPos);
        const afterCursor = textarea.value.substring(cursorPos);
        textarea.value = beforeLink + `[[${file.basename}]] ` + afterCursor;
        mentionDropdown.setCssStyles({ display: "none" });

        textarea.focus();
        const newCursorPos = linkStartPos + file.basename.length + 5;
        textarea.setSelectionRange(newCursorPos, newCursorPos);
        resizeTextarea();
        updateSendButtonState();

        await syncLinkedNotesContext();
      };

      const updateLinkSuggestions = () => {
        const cursorPos = textarea.selectionStart;
        const textBeforeCursor = textarea.value.substring(0, cursorPos);
        const linkMatch = textBeforeCursor.match(/\[\[([^\]]*?)$/);

        if (linkMatch) {
          linkStartPos = textBeforeCursor.lastIndexOf("[[");
          const query = linkMatch[1].toLowerCase();

          const currentFile = this.plugin.app.workspace.getActiveFile();
          const files = this.plugin.app.vault.getMarkdownFiles();

          const filtered = files.filter(f =>
            f.basename.toLowerCase().includes(query) ||
            f.path.toLowerCase().includes(query)
          );

          filtered.sort((a, b) => {
            if (currentFile && a.path === currentFile.path) return -1;
            if (currentFile && b.path === currentFile.path) return 1;
            return 0;
          });

          suggestionFiles = filtered.slice(0, 10);
          selectedSuggestionIndex = 0;

          if (filtered.length > 0) {
            mentionDropdown.empty();
            filtered.forEach((file, index) => {
              const item = doc.createDiv();
              item.className = "editing-toolbar-ai-inline-prompt-mention-item";
              if (index === 0) item.classList.add("selected");
              item.createSpan({ cls: "editing-toolbar-ai-inline-prompt-mention-icon", text: "📄" });
              item.appendText(file.basename);
              const pathSpan = item.createSpan({ text: file.path });
              pathSpan.setCssStyles({ color: "var(--text-faint)" });
              pathSpan.setCssStyles({ fontSize: "10px" });
              item.addEventListener("click", () => {
                void selectSuggestion(file);
              });
              mentionDropdown.appendChild(item);
            });
            mentionDropdown.setCssStyles({ display: "block" });
          } else {
            mentionDropdown.setCssStyles({ display: "none" });
          }
        } else {
          mentionDropdown.setCssStyles({ display: "none" });
          linkStartPos = -1;
          suggestionFiles = [];
        }
      };

      const syncPlaceholdersWithContext = () => {
        const text = textarea.value;

        // 检查选中文本占位符
        const hasSelectionPlaceholder = this.getSelectedTextPlaceholderVariants().some((placeholder) => text.includes(placeholder));
        const hasSelectionContext = contextList.some(c => c.type === "selection");

        if (!hasSelectionPlaceholder && hasSelectionContext) {
          // 占位符被删除,移除上下文
          const index = contextList.findIndex(c => c.type === "selection");
          if (index > -1) {
            contextList.splice(index, 1);
            renderContextItems();
          }
        }
      };

      const normalizeLinkTriggerInput = (value: string, cursorPos: number): { value: string; cursorPos: number } => {
        let normalizedValue = value;
        let normalizedCursorPos = cursorPos;

        if (normalizedValue.includes("【【")) {
          const beforeCursor = normalizedValue.substring(0, normalizedCursorPos);
          const afterCursor = normalizedValue.substring(normalizedCursorPos);
          const newBeforeCursor = beforeCursor.replace(/【【/g, "[[");
          const newAfterCursor = afterCursor.replace(/【【/g, "[[");
          const lengthDiff = beforeCursor.length - newBeforeCursor.length;

          normalizedValue = newBeforeCursor + newAfterCursor;
          normalizedCursorPos -= lengthDiff;
        }

        const openingBracketRun = normalizedValue.substring(0, normalizedCursorPos).match(/(?:\[|【){2,}$/);
        if (openingBracketRun && openingBracketRun[0].includes("【")) {
          const runStart = normalizedCursorPos - openingBracketRun[0].length;
          normalizedValue = `${normalizedValue.substring(0, runStart)}[[${normalizedValue.substring(normalizedCursorPos)}`;
          normalizedCursorPos = runStart + 2;
        }

        return { value: normalizedValue, cursorPos: normalizedCursorPos };
      };

      textarea.addEventListener("input", (e) => {
        const normalized = normalizeLinkTriggerInput(textarea.value, textarea.selectionStart);

        if (normalized.value !== textarea.value || normalized.cursorPos !== textarea.selectionStart) {
          textarea.value = normalized.value;
          textarea.setSelectionRange(normalized.cursorPos, normalized.cursorPos);
        }

        resizeTextarea();
        updateSendButtonState();
        updateLinkSuggestions();
        void syncLinkedNotesContext();
        syncPlaceholdersWithContext();
      });
      textarea.addEventListener("keydown", (event) => {
        const isSuggestionVisible = mentionDropdown.style.display !== "none" && suggestionFiles.length > 0;

        if (isSuggestionVisible) {
          if (event.key === "ArrowDown") {
            event.preventDefault();
            selectedSuggestionIndex = (selectedSuggestionIndex + 1) % suggestionFiles.length;
            const items = mentionDropdown.querySelectorAll(".editing-toolbar-ai-inline-prompt-mention-item");
            items.forEach((item, index) => {
              item.classList.toggle("selected", index === selectedSuggestionIndex);
            });
            items[selectedSuggestionIndex]?.scrollIntoView({ block: "nearest" });
            return;
          }

          if (event.key === "ArrowUp") {
            event.preventDefault();
            selectedSuggestionIndex = (selectedSuggestionIndex - 1 + suggestionFiles.length) % suggestionFiles.length;
            const items = mentionDropdown.querySelectorAll(".editing-toolbar-ai-inline-prompt-mention-item");
            items.forEach((item, index) => {
              item.classList.toggle("selected", index === selectedSuggestionIndex);
            });
            items[selectedSuggestionIndex]?.scrollIntoView({ block: "nearest" });
            return;
          }

          if (event.key === "Tab") {
            event.preventDefault();
            if (suggestionFiles[selectedSuggestionIndex]) {
              void selectSuggestion(suggestionFiles[selectedSuggestionIndex]);
            }
            return;
          }

          if (event.key === "Enter" && !event.shiftKey && !event.metaKey && !event.ctrlKey) {
            event.preventDefault();
            if (suggestionFiles[selectedSuggestionIndex]) {
              void selectSuggestion(suggestionFiles[selectedSuggestionIndex]);
            }
            return;
          }
        }

        if (event.key === "Escape") {
          event.preventDefault();
          if (isSuggestionVisible) {
            mentionDropdown.setCssStyles({ display: "none" });
          } else {
            closePrompt();
          }
          return;
        }

        if (event.key === "Enter" && (event.metaKey || event.ctrlKey)) {
          event.preventDefault();
          void submitPrompt();
          return;
        }

        if (!Platform.isMobileApp && event.key === "Enter" && !event.shiftKey) {
          event.preventDefault();
          void submitPrompt();
        }
      });

      const win = doc.defaultView ?? window;
      win.addEventListener("resize", reposition);
      doc.addEventListener("scroll", reposition, true);

      this.inlineCustomPromptCleanup = [
        () => win.removeEventListener("resize", reposition),
        () => doc.removeEventListener("scroll", reposition, true),
        () => dragHandle.removeEventListener('mousedown', onDragStart),
        () => titleEl.removeEventListener('mousedown', onDragStart),
        () => dragHandle.removeEventListener('touchstart', onDragStart),
        () => titleEl.removeEventListener('touchstart', onDragStart),
        () => doc.removeEventListener('mousemove', onDrag),
        () => doc.removeEventListener('touchmove', onDrag),
        () => doc.removeEventListener('mouseup', onDragEnd),
        () => doc.removeEventListener('touchend', onDragEnd),
      ];

      this.inlineCustomPromptEl = promptEl;
      this.inlineCustomPromptTextarea = textarea;
      resizeTextarea();
      updateSendButtonState();
    }

    this.positionInlineCustomPrompt(editor, view);
    this.inlineCustomPromptTextarea?.focus();
  }

  private positionInlineCustomPrompt(editor: Editor, view: EditorView): void {
    if (!this.inlineCustomPromptEl) {
      return;
    }

    const doc = view.dom.ownerDocument;
    const win = doc.defaultView ?? window;
    const cursor = editor.getCursor("to");
    const offset = editor.posToOffset(cursor);
    const coords = view.coordsAtPos(offset);
    if (!coords) {
      return;
    }

    const promptWidth = this.inlineCustomPromptEl.offsetWidth || 320;
    const promptHeight = this.inlineCustomPromptEl.offsetHeight || 150;
    const margin = 12;
    const left = Math.max(
      margin,
      Math.min(coords.left, win.innerWidth - promptWidth - margin),
    );
    const top = Math.max(
      margin,
      Math.min(coords.bottom + 10, win.innerHeight - promptHeight - margin),
    );

    this.inlineCustomPromptEl.style.left = `${left}px`;
    this.inlineCustomPromptEl.style.top = `${top}px`;
  }

  private resolveEditor(editor?: Editor | null): Editor | null {
    if (editor) {
      return editor;
    }
    try {
      return this.plugin.commandsManager?.getActiveEditor() ?? ((this.plugin.app.workspace.getActiveViewOfType(MarkdownView))?.editor ?? null);
    } catch {
      return null;
    }
  }

  private getEditorView(editor?: Editor | null): EditorView | null {
    const resolvedEditor = this.resolveEditor(editor);
    const view = (resolvedEditor as any)?.cm;
    if (view && view.state && typeof view.dispatch === "function") {
      return view as EditorView;
    }
    return null;
  }

  private async isPKMerAvailable(): Promise<boolean> {
    const verified = await this.authService.verify();
    return verified && !!this.authService.aiToken;
  }

  private addToHistory(prompt: string): void {
    const history = this.plugin.settings.ai.customPromptHistory || [];
    const existingIndex = history.indexOf(prompt);

    if (existingIndex !== -1) {
      history.splice(existingIndex, 1);
    }

    history.unshift(prompt);

    if (history.length > 10) {
      history.splice(10);
    }

    this.plugin.settings.ai.customPromptHistory = history;
    void this.plugin.saveSettings();
  }
}

import { requestUrl, type RequestUrlResponse } from "obsidian";
import type EditingToolbarPlugin from "src/plugin/main";
import { t } from "src/translations/helper";
import { AIUserNoticeError, getAIErrorMessage, getRequestErrorStatus } from "./errorHandling";
import { resolvePKMerModelForScene } from "./types";
import type { CompletionParams, IAIService, PKMerModelScene, RewriteArtifactKind, RewriteInstruction, RewriteParams } from "./types";
import type { CustomModelApiFormat } from "./types";
import { PKMerAuthService } from "./PKMerAuthService";
import { AIUrlHelper } from "./urlValidation";

interface ResolvedProvider {
  kind: "pkmer" | "custom";
  apiFormat: CustomModelApiFormat;
  baseUrl: string;
  apiKey: string;
  model: string;
  temperature: number;
}

interface CustomProviderValidationResult {
  provider: ResolvedProvider | null;
  missing: string[];
}

interface ChatCompletionOptions {
  maxTokens?: number;
  pkmerScene?: PKMerModelScene;
}

interface ChatCompletionResult {
  text: string;
  finishReason?: string;
}

export class ToolbarAIService implements IAIService {
  private plugin: EditingToolbarPlugin;
  private authService: PKMerAuthService;
  private customChatCompletionsUrlCache = new Map<string, string>();

  constructor(plugin: EditingToolbarPlugin, authService: PKMerAuthService) {
    this.plugin = plugin;
    this.authService = authService;
  }

  async *complete(params: CompletionParams, signal?: AbortSignal): AsyncIterable<string> {
    const text = await this.requestCompletion(params, signal);
    yield* this.streamText(text, signal);
  }

  async *rewrite(params: RewriteParams, signal?: AbortSignal): AsyncIterable<string> {
    const text = await this.requestRewrite(params, signal);
    yield* this.streamText(text, signal);
  }

  hasCustomProviderConfigured(): boolean {
    return !!this.getCustomProviderValidation().provider;
  }

  async testCustomProviderConnection(): Promise<void> {
    const validation = this.getCustomProviderValidation();
    if (!validation.provider) {
      throw new Error(`Missing custom model settings: ${validation.missing.join(", ")}`);
    }

    AIUrlHelper.validateBaseUrl(validation.provider.baseUrl, validation.provider.apiFormat);

    const result = await this.requestChatCompletionResult(
      [
        {
          role: "system",
          content: "Reply with OK only.",
        },
        {
          role: "user",
          content: "ping",
        },
      ],
      undefined,
      {},
      validation.provider,
    );

    if (!result.text || !result.text.trim()) {
      throw new Error(
        t("Custom model connection test returned an empty response. Check that your API base URL and model name are correct."),
      );
    }
  }

  async listCustomOllamaModels(): Promise<string[]> {
    const provider = this.getCustomProviderForModelListing("ollama");
    if (!provider) {
      throw new Error("Ollama custom model settings are not enabled.");
    }

    const candidateUrls = this.buildOllamaTagsCandidateUrls(provider.baseUrl);
    let lastError: unknown = null;

    for (let index = 0; index < candidateUrls.length; index += 1) {
      const requestUrlValue = candidateUrls[index];
      try {
        const response = await requestUrl({
          url: requestUrlValue,
          method: "GET",
          headers: this.buildRequestHeaders(provider.apiKey),
          throw: false,
        });

        if (response.status >= 200 && response.status < 300) {
          return this.extractOllamaModelNames(response.json);
        }

        throw this.createRequestResponseError(response, requestUrlValue);
      } catch (error) {
        lastError = error;
        const canRetryWithNextUrl = index < candidateUrls.length - 1 && this.isRetryableEndpointError(error);
        if (canRetryWithNextUrl) {
          continue;
        }

        await this.rethrowUserFacingRequestError(error, requestUrlValue);
      }
    }

    await this.rethrowUserFacingRequestError(lastError, candidateUrls[0] ?? provider.baseUrl);
  }

  async listCustomOpenAIModels(): Promise<string[]> {
    const provider = this.getCustomProviderForModelListing("openai-compatible");
    if (!provider) {
      throw new Error("OpenAI-compatible custom model settings are not enabled.");
    }

    const modelsUrl = this.buildModelsUrl(provider.baseUrl);

    try {
      const response = await requestUrl({
        url: modelsUrl,
        method: "GET",
        headers: this.buildRequestHeaders(provider.apiKey),
        throw: false,
      });

      if (response.status >= 200 && response.status < 300) {
        return this.extractOpenAIModelNames(response.json);
      }

      throw this.createRequestResponseError(response, modelsUrl);
    } catch (error) {
      await this.rethrowUserFacingRequestError(error, modelsUrl);
    }
  }

  async listCustomGeminiModels(): Promise<string[]> {
    const provider = this.getCustomProviderForModelListing("gemini");
    if (!provider) {
      throw new Error("Gemini custom model settings are not enabled.");
    }

    const modelsUrl = this.buildGeminiModelsUrl(provider.baseUrl);
    try {
      const response = await requestUrl({
        url: modelsUrl,
        method: "GET",
        headers: this.buildRequestHeaders(provider.apiKey, provider.apiFormat),
        throw: false,
      });

      if (response.status >= 200 && response.status < 300) {
        return this.extractGeminiModelNames(response.json);
      }

      throw this.createRequestResponseError(response, modelsUrl);
    } catch (error) {
      await this.rethrowUserFacingRequestError(error, modelsUrl);
    }
  }

  private async requestCompletion(params: CompletionParams, signal?: AbortSignal): Promise<string> {
    const localPrefix = params.prefix.slice(-2000);
    const localSuffix = params.suffix.slice(0, 800);
    const contextBlock = params.context ? `\n\nLocal cursor metadata:\n${params.context}` : "";
    const provider = await this.resolveProvider("completion");
    let accumulated = "";

    for (let round = 0; round < 3; round++) {
      const response = await this.requestChatCompletionResult(
        this.buildCompletionMessages(localPrefix, localSuffix, contextBlock, accumulated),
        signal,
        {
          maxTokens: this.getCompletionTokenBudget(localPrefix, localSuffix, accumulated, round),
          pkmerScene: "completion",
        },
        provider,
      );

      const nextSegment = this.removeRepeatedPrefix(accumulated, response.text);
      if (!nextSegment) {
        break;
      }

      accumulated += nextSegment;

      if (response.finishReason !== "length") {
        return accumulated.trimEnd();
      }

      if (this.looksSemanticallyComplete(accumulated)) {
        return this.trimCompletionToBoundary(accumulated);
      }
    }

    return this.trimCompletionToBoundary(accumulated) || accumulated.trimEnd();
  }

  private async requestRewrite(params: RewriteParams, signal?: AbortSignal): Promise<string> {
    return this.requestChatCompletion(
      this.buildRewriteMessages(params),
      signal,
      {
        pkmerScene: this.resolveRewriteScene(params),
      },
    );
  }

  private async requestChatCompletion(
    messages: Array<{ role: string; content: string }>,
    signal?: AbortSignal,
    options: ChatCompletionOptions = {},
  ): Promise<string> {
    const response = await this.requestChatCompletionResult(messages, signal, options);
    return response.text;
  }

  private async requestChatCompletionResult(
    messages: Array<{ role: string; content: string }>,
    signal?: AbortSignal,
    options: ChatCompletionOptions = {},
    provider?: ResolvedProvider,
  ): Promise<ChatCompletionResult> {
    if (signal?.aborted) {
      throw new DOMException("Aborted", "AbortError");
    }

    const resolvedProvider = provider ?? (await this.resolveProvider(options.pkmerScene));
    const { response } = await this.requestChatCompletionsWithFallback(resolvedProvider, messages, signal, options);

    if (signal?.aborted) {
      throw new DOMException("Aborted", "AbortError");
    }

    const payload = response.json;
    const text = this.extractText(payload);
    return {
      text,
      finishReason: this.normalizeFinishReason(
        payload?.choices?.[0]?.finish_reason
          ?? payload?.candidates?.[0]?.finishReason
          ?? payload?.done_reason
          ?? (payload?.done ? "stop" : undefined),
      ),
    };
  }

  private async requestChatCompletionsWithFallback(
    provider: ResolvedProvider,
    messages: Array<{ role: string; content: string }>,
    signal?: AbortSignal,
    options: ChatCompletionOptions = {},
  ): Promise<{ response: RequestUrlResponse; requestUrlValue: string }> {
    const candidateUrls = this.getChatCompletionsCandidateUrls(provider);
    let lastError: unknown = null;
    let retried401 = false;

    for (let index = 0; index < candidateUrls.length; index += 1) {
      const requestUrlValue = candidateUrls[index];
      try {
        const response = await this.executeChatCompletionsRequest(requestUrlValue, provider, messages, signal, options);
        if (provider.kind === "custom") {
          this.rememberCustomChatCompletionsUrl(provider.baseUrl, provider.apiFormat, requestUrlValue);
        }
        return { response, requestUrlValue };
      } catch (error) {
        lastError = error;

        // PKMer 401: token may have expired mid-session — try refresh + retry once
        if (
          !retried401
          && provider.kind === "pkmer"
          && getRequestErrorStatus(error) === 401
        ) {
          retried401 = true;
          const refreshed = await this.authService.refreshFor401();
          if (refreshed) {
            provider = { ...provider, apiKey: this.authService.aiToken };
            index -= 1; // retry same URL
            continue;
          }
        }

        const canRetryWithNextUrl = provider.kind === "custom"
          && index < candidateUrls.length - 1
          && this.isRetryableEndpointError(error);
        if (canRetryWithNextUrl) {
          continue;
        }

        await this.rethrowUserFacingRequestError(error, requestUrlValue);
      }
    }

    await this.rethrowUserFacingRequestError(lastError, candidateUrls[0] ?? provider.baseUrl);
  }

  private async executeChatCompletionsRequest(
    requestUrlValue: string,
    provider: ResolvedProvider,
    messages: Array<{ role: string; content: string }>,
    signal?: AbortSignal,
    options: ChatCompletionOptions = {},
  ): Promise<RequestUrlResponse> {
    const response = await requestUrl({
      url: requestUrlValue,
      method: "POST",
      headers: this.buildRequestHeaders(provider.apiKey, provider.apiFormat),
      body: JSON.stringify(this.buildRequestBody(requestUrlValue, provider, messages, options)),
      throw: false,
    });

    if (response.status >= 200 && response.status < 300) {
      return response;
    }

    throw this.createRequestResponseError(response, requestUrlValue);
  }

  private buildRequestBody(
    requestUrlValue: string,
    provider: ResolvedProvider,
    messages: Array<{ role: string; content: string }>,
    options: ChatCompletionOptions = {},
  ): Record<string, unknown> {
    if (provider.kind === "custom" && provider.apiFormat === "ollama") {
      return this.buildOllamaRequestBody(requestUrlValue, provider, messages, options);
    }

    if (provider.kind === "custom" && provider.apiFormat === "gemini") {
      return this.buildGeminiRequestBody(provider, messages, options);
    }

    return {
      model: provider.model,
      temperature: provider.temperature,
      max_tokens: options.maxTokens,
      stream: false,
      messages,
    };
  }

  private buildOllamaRequestBody(
    requestUrlValue: string,
    provider: ResolvedProvider,
    messages: Array<{ role: string; content: string }>,
    options: ChatCompletionOptions = {},
  ): Record<string, unknown> {
    const ollamaOptions: Record<string, unknown> = {};

    if (Number.isFinite(provider.temperature)) {
      ollamaOptions.temperature = provider.temperature;
    }

    if (typeof options.maxTokens === "number") {
      ollamaOptions.num_predict = options.maxTokens;
    }

    if (/\/api\/generate$/i.test(requestUrlValue)) {
      return {
        model: provider.model,
        prompt: this.buildOllamaGeneratePrompt(messages),
        stream: false,
        options: Object.keys(ollamaOptions).length > 0 ? ollamaOptions : undefined,
      };
    }

    return {
      model: provider.model,
      stream: false,
      messages,
      options: Object.keys(ollamaOptions).length > 0 ? ollamaOptions : undefined,
    };
  }

  private buildOllamaGeneratePrompt(messages: Array<{ role: string; content: string }>): string {
    const prompt = messages
      .filter((message) => typeof message.content === "string" && message.content.trim().length > 0)
      .map((message) => `${message.role.toUpperCase()}:\n${message.content.trim()}`)
      .join("\n\n");

    return prompt ? `${prompt}\n\nASSISTANT:\n` : "ASSISTANT:\n";
  }

  private buildGeminiRequestBody(
    provider: ResolvedProvider,
    messages: Array<{ role: string; content: string }>,
    options: ChatCompletionOptions = {},
  ): Record<string, unknown> {
    const systemText = messages
      .filter((message) => message.role === "system")
      .map((message) => message.content.trim())
      .filter(Boolean)
      .join("\n\n");
    const contents = messages
      .filter((message) => message.role !== "system" && message.content.trim())
      .map((message) => ({
        role: message.role === "assistant" ? "model" : "user",
        parts: [{ text: message.content }],
      }));
    const generationConfig: Record<string, unknown> = {};
    if (Number.isFinite(provider.temperature)) generationConfig.temperature = provider.temperature;
    if (typeof options.maxTokens === "number") generationConfig.maxOutputTokens = options.maxTokens;

    return {
      systemInstruction: systemText ? { parts: [{ text: systemText }] } : undefined,
      contents,
      generationConfig: Object.keys(generationConfig).length > 0 ? generationConfig : undefined,
    };
  }

  private async resolveProvider(scene: PKMerModelScene = "rewrite"): Promise<ResolvedProvider> {
    const pkmerProvider = await this.getPKMerProvider(scene);
    if (pkmerProvider) {
      return pkmerProvider;
    }

    const customProvider = this.getCustomProviderValidation().provider;
    if (customProvider) {
      return customProvider;
    }

    throw new Error("No AI provider is configured. Please log in to PKMer or fill in custom model settings.");
  }

  private async getPKMerProvider(scene: PKMerModelScene): Promise<ResolvedProvider | null> {
    const settings = this.plugin.settings.ai;
    const verified = await this.authService.verify();
    if (!verified || !this.authService.aiToken) {
      return null;
    }

    return {
      kind: "pkmer",
      apiFormat: "openai-compatible",
      baseUrl: settings.pkmerApiBaseUrl,
      apiKey: this.authService.aiToken,
      model: resolvePKMerModelForScene(settings, scene),
      temperature: settings.customModel.temperature,
    };
  }

  private getCustomProviderValidation(): CustomProviderValidationResult {
    if (!this.plugin.settings.ai.enableCustomModel) {
      return { provider: null, missing: ["disabled"] };
    }

    const custom = this.plugin.settings.ai.customModel;
    const customApiKey = this.authService.customModelApiKey.trim();
    const customApiFormat = custom.apiFormat ?? "openai-compatible";
    const missing: string[] = [];

    if (!custom.baseUrl.trim()) {
      missing.push("baseUrl");
    }
    if (!custom.model.trim()) {
      missing.push("model");
    }
    if (customApiFormat === "gemini" && !customApiKey) {
      missing.push("apiKey");
    }

    if (missing.length > 0) {
      return { provider: null, missing };
    }

    return {
      provider: {
        kind: "custom",
        apiFormat: customApiFormat,
        baseUrl: custom.baseUrl.trim(),
        apiKey: customApiKey,
        model: custom.model.trim(),
        temperature: custom.temperature,
      },
      missing: [],
    };
  }

  private getCustomProviderForModelListing(apiFormat: CustomModelApiFormat): ResolvedProvider | null {
    if (!this.plugin.settings.ai.enableCustomModel) return null;
    const custom = this.plugin.settings.ai.customModel;
    const configuredFormat = custom.apiFormat ?? "openai-compatible";
    const apiKey = this.authService.customModelApiKey.trim();
    if (configuredFormat !== apiFormat || !custom.baseUrl.trim()) return null;
    if (apiFormat === "gemini" && !apiKey) {
      throw new Error(t("Gemini API key is required."));
    }

    return {
      kind: "custom",
      apiFormat,
      baseUrl: custom.baseUrl.trim(),
      apiKey,
      model: custom.model.trim(),
      temperature: custom.temperature,
    };
  }

  private buildChatCompletionsUrl(baseUrl: string): string {
    return this.buildChatCompletionsCandidateUrls(baseUrl)[0] ?? baseUrl.trim().replace(/\/+$/, "");
  }

  private getChatCompletionsCandidateUrls(provider: ResolvedProvider): string[] {
    if (provider.kind !== "custom") {
      return [this.buildChatCompletionsUrl(provider.baseUrl)];
    }

    const cacheKey = this.getCustomProviderCacheKey(provider.baseUrl, provider.apiFormat);
    const cachedUrl = this.customChatCompletionsUrlCache.get(cacheKey);
    const urls = provider.apiFormat === "ollama"
      ? this.buildOllamaCandidateUrls(provider.baseUrl)
      : provider.apiFormat === "gemini"
        ? this.buildGeminiCandidateUrls(provider.baseUrl, provider.model)
        : this.buildChatCompletionsCandidateUrls(provider.baseUrl);
    if (!cachedUrl) {
      return urls;
    }

    return [cachedUrl, ...urls.filter((url) => url !== cachedUrl)];
  }

  private buildChatCompletionsCandidateUrls(baseUrl: string): string[] {
    const normalized = this.normalizeProviderBaseUrl(baseUrl);
    if (!normalized) {
      return [];
    }

    if (/\/chat\/completions$/i.test(normalized)) {
      return [normalized];
    }

    if (/\/v\d+$/i.test(normalized)) {
      return [`${normalized}/chat/completions`];
    }

    const directUrl = `${normalized}/chat/completions`;
    const v1Url = `${normalized}/v1/chat/completions`;
    const v3Url = `${normalized}/v3/chat/completions`;

    if (this.hasPathSegment(normalized)) {
      return [directUrl, v1Url, v3Url];
    }

    return [v1Url, directUrl, v3Url];
  }

  private buildOllamaCandidateUrls(baseUrl: string): string[] {
    const normalized = this.normalizeProviderBaseUrl(baseUrl);
    if (!normalized) {
      return [];
    }

    if (/\/api\/(chat|generate)$/i.test(normalized)) {
      return [normalized];
    }

    if (/\/api$/i.test(normalized)) {
      return [`${normalized}/chat`, `${normalized}/generate`];
    }

    return [`${normalized}/api/chat`, `${normalized}/api/generate`];
  }

  private buildOllamaTagsCandidateUrls(baseUrl: string): string[] {
    const normalized = this.normalizeProviderBaseUrl(baseUrl);
    if (!normalized) {
      return [];
    }

    if (/\/api\/tags$/i.test(normalized)) {
      return [normalized];
    }

    if (/\/api\/(chat|generate)$/i.test(normalized)) {
      return [normalized.replace(/\/(chat|generate)$/i, "/tags")];
    }

    if (/\/api$/i.test(normalized)) {
      return [`${normalized}/tags`];
    }

    return [`${normalized}/api/tags`];
  }

  private buildGeminiCandidateUrls(baseUrl: string, model: string): string[] {
    const normalized = this.normalizeGeminiBaseUrl(baseUrl);
    if (!normalized) return [];
    if (/\/models\/[^/]+:generateContent$/i.test(normalized)) return [normalized];

    const normalizedModel = model.trim().replace(/^models\//i, "");
    const modelsBaseUrl = /\/models$/i.test(normalized) ? normalized : `${normalized}/models`;
    return [`${modelsBaseUrl}/${encodeURIComponent(normalizedModel)}:generateContent`];
  }

  private buildGeminiModelsUrl(baseUrl: string): string {
    const normalized = this.normalizeGeminiBaseUrl(baseUrl);
    if (!normalized) return "";
    if (/\/models$/i.test(normalized)) return normalized;
    if (/\/models\/[^/]+:generateContent$/i.test(normalized)) {
      return normalized.replace(/\/models\/[^/]+:generateContent$/i, "/models");
    }
    return `${normalized}/models`;
  }

  private normalizeGeminiBaseUrl(baseUrl: string): string {
    const normalized = this.normalizeProviderBaseUrl(baseUrl);
    if (!normalized) return "";
    if (/\/models(?:\/[^/]+:generateContent)?$/i.test(normalized)) return normalized;
    if (/\/v1(?:beta)?$/i.test(normalized)) return normalized;
    return `${normalized}/v1beta`;
  }

  private buildModelsUrl(baseUrl: string): string {
    const normalized = this.normalizeProviderBaseUrl(baseUrl);
    if (!normalized) return "";

    if (/\/models$/i.test(normalized)) {
      return normalized;
    }

    if (/\/chat\/completions$/i.test(normalized)) {
      return normalized.replace(/\/chat\/completions$/i, "/models");
    }

    if (/\/v\d+$/i.test(normalized)) {
      return `${normalized}/models`;
    }

    return `${normalized}/v1/models`;
  }

  private buildRequestHeaders(apiKey: string, apiFormat: CustomModelApiFormat = "openai-compatible"): Record<string, string> {
    const headers: Record<string, string> = {
      "Content-Type": "application/json",
    };

    if (apiKey.trim()) {
      if (apiFormat === "gemini") {
        headers["x-goog-api-key"] = apiKey.trim();
      } else {
        headers.Authorization = `Bearer ${apiKey}`;
      }
    }

    return headers;
  }

  private normalizeProviderBaseUrl(baseUrl: string): string {
    return baseUrl.trim().replace(/\/+$/, "");
  }

  private hasPathSegment(baseUrl: string): boolean {
    try {
      const { pathname } = new URL(baseUrl);
      const normalizedPath = pathname.replace(/\/+$/, "");
      return normalizedPath.length > 0 && normalizedPath !== "/";
    } catch {
      return false;
    }
  }

  private getCustomProviderCacheKey(baseUrl: string, apiFormat: CustomModelApiFormat): string {
    return `${apiFormat}:${this.normalizeProviderBaseUrl(baseUrl)}`;
  }

  private rememberCustomChatCompletionsUrl(baseUrl: string, apiFormat: CustomModelApiFormat, requestUrlValue: string): void {
    this.customChatCompletionsUrlCache.set(this.getCustomProviderCacheKey(baseUrl, apiFormat), requestUrlValue);
  }

  private isRetryableEndpointError(error: unknown): boolean {
    const status = getRequestErrorStatus(error);
    if (status === 404 || status === 405 || status === 410) {
      return true;
    }

    if (status === 400 || status === 422) {
      const message = getAIErrorMessage(error).toLowerCase();
      return /not found|no route|unknown path|unknown endpoint|invalid url|invalid path|unsupported path|unsupported endpoint/.test(message);
    }

    return false;
  }

  private createRequestResponseError(response: RequestUrlResponse, requestUrlValue: string): Error & {
    status: number;
    response: RequestUrlResponse;
  } {
    // response.json is a getter that calls JSON.parse(this.text); when the
    // body is not valid JSON (e.g. a 401 "Authentication required" plain-text
    // response), accessing it throws SyntaxError. Parse defensively so the
    // error path itself never crashes.
    let parsedJson: any;
    try {
      parsedJson = response.json;
    } catch {
      parsedJson = null;
    }

    const errorMessage = parsedJson?.error?.message
      || parsedJson?.message
      || response.text
      || `Request failed with status ${response.status} (${requestUrlValue})`;
    const error = new Error(typeof errorMessage === "string" ? errorMessage.trim() : String(errorMessage)) as Error & {
      status: number;
      response: RequestUrlResponse;
    };
    error.status = response.status;
    error.response = response;
    return error;
  }

  private extractOllamaModelNames(payload: any): string[] {
    const models = Array.isArray(payload?.models) ? payload.models : [];
    const names: string[] = models
      .map((item: any): string => {
        if (typeof item?.name === "string" && item.name.trim()) {
          return item.name.trim();
        }
        if (typeof item?.model === "string" && item.model.trim()) {
          return item.model.trim();
        }
        return "";
      })
      .filter((name: string): boolean => !!name);

    return Array.from(new Set(names)).sort((left, right) => left.localeCompare(right));
  }

  private extractOpenAIModelNames(payload: any): string[] {
    const models = Array.isArray(payload?.data) ? payload.data : [];
    const names: string[] = models
      .map((item: any): string => {
        if (typeof item?.id === "string" && item.id.trim()) {
          return item.id.trim();
        }
        return "";
      })
      .filter((name: string): boolean => !!name);

    return Array.from(new Set(names)).sort((left, right) => left.localeCompare(right));
  }

  private extractGeminiModelNames(payload: any): string[] {
    const models = Array.isArray(payload?.models) ? payload.models : [];
    const names: string[] = models
      .filter((item: any) => !Array.isArray(item?.supportedGenerationMethods)
        || item.supportedGenerationMethods.includes("generateContent"))
      .map((item: any) => typeof item?.name === "string" ? item.name.replace(/^models\//, "").trim() : "")
      .filter((name: string): boolean => !!name);
    return Array.from(new Set(names)).sort((left, right) => left.localeCompare(right));
  }

  private async rethrowUserFacingRequestError(error: unknown, requestUrlValue: string): Promise<never> {
    if (await this.isPKMerQuotaError(error, requestUrlValue)) {
      throw new AIUserNoticeError(
        t("PKMer AI request failed because your quota is insufficient. Please get more quota in PKMer and try again."),
      );
    }

    if (this.isPKMerAuthError(error, requestUrlValue)) {
      throw new AIUserNoticeError(
        t("PKMer login has expired or is invalid. Please log in to PKMer again in Settings → AI."),
      );
    }

    const status = getRequestErrorStatus(error);
    if (status === 401) {
      throw new AIUserNoticeError(
        t("AI request failed with status 401 (Unauthorized). Your API key is missing or invalid. Please check your API key in Settings → AI → Custom Model."),
      );
    }
    if (status === 403) {
      throw new AIUserNoticeError(
        t("AI request failed with status 403 (Forbidden). The server refused the request. Please check your API key and account permissions."),
      );
    }
    if (status === 404) {
      throw new AIUserNoticeError(
        t("AI request failed with status 404 (Not Found). The API endpoint URL may be incorrect. Please check the Base URL in Settings → AI → Custom Model."),
      );
    }
    if (status === 429) {
      throw new AIUserNoticeError(
        t("AI request failed with status 429 (Too Many Requests). You are sending requests too quickly or have hit a rate limit. Please wait a moment and try again."),
      );
    }
    if (status && status >= 500) {
      throw new AIUserNoticeError(
        t("AI request failed with status {{status}} (Server Error). The AI server is experiencing issues. Please try again later.").replace(/\{\{status\}\}/g, String(status)),
        10000,
      );
    }

    // Network errors (no status code) — connection refused, timeout, DNS, etc.
    if (status === null) {
      throw new AIUserNoticeError(
        t("AI request failed: could not connect to the server. Please check your network connection and the API Base URL in Settings → AI → Custom Model."),
      );
    }

    throw error;
  }

  private isPKMerAuthError(error: unknown, requestUrlValue: string): boolean {
    if (!/pkmer\.cn/i.test(requestUrlValue)) {
      return false;
    }
    return getRequestErrorStatus(error) === 401;
  }

  private async isPKMerQuotaError(error: unknown, requestUrlValue: string): Promise<boolean> {
    if (!/pkmer\.cn/i.test(requestUrlValue)) {
      return false;
    }

    if (getRequestErrorStatus(error) !== 403) {
      return false;
    }

    const quota = await this.authService.refreshQuota().catch(() => null);
    const rawQuota = quota?.quota ?? quota?.remainingQuota;
    if (typeof rawQuota === "number") {
      const normalizedQuota = Number((rawQuota / 500000).toFixed(2));
      if (normalizedQuota <= 1) {
        return true;
      }
    }

    const message = getAIErrorMessage(error).toLowerCase();
    return /quota|credit|balance|insufficient|额度|点数|余量不足|余额不足/.test(message);
  }

  private buildCompletionMessages(
    localPrefix: string,
    localSuffix: string,
    contextBlock: string,
    accumulated: string,
  ): Array<{ role: string; content: string }> {
    const effectivePrefix = `${localPrefix}${accumulated}`;
    const continuationNote = accumulated
      ? "\n\nA draft continuation has already been generated. Continue exactly from where that draft ends. Do not repeat or paraphrase any previously generated text."
      : "";

    return [
      {
        role: "system",
        content:
          "You are an inline writing assistant inside Obsidian. Continue the text exactly at the cursor using only the local context around the cursor. Return only the continuation text, with no explanations, no markdown fences, and no quotes. Produce one complete semantic unit that fits the local structure, such as one full sentence, one complete bullet item, one heading continuation, or one short paragraph. Never stop mid-word, mid-sentence, or mid-list-item.",
      },
      {
        role: "user",
        content: `Continue the text at <CURSOR>. Use the local cursor context below, not the whole document.${continuationNote}\n\nText before cursor:\n${effectivePrefix}\n\n<CURSOR>\n\nText after cursor:\n${localSuffix}${contextBlock}`,
      },
    ];
  }

  private resolveRewriteScene(params: RewriteParams): PKMerModelScene {
    if (params.artifactKind) {
      return "artifact";
    }

    if (
      params.instruction === "explain" ||
      params.instruction === "summarize" ||
      params.instruction === "custom"
    ) {
      return "reasoning";
    }

    return "rewrite";
  }

  private buildRewriteMessages(params: RewriteParams): Array<{ role: string; content: string }> {
    const instruction = this.buildRewriteInstruction(params.instruction, params.customPrompt);
    const hasTargetText = params.selectedText.trim().length > 0;
    const contextBlock = params.context ? `\n\nLocal document context:\n${params.context}` : "";
    const systemPrompt = this.buildRewriteSystemPrompt(params.artifactKind);
    const outputRequirement = this.buildRewriteOutputRequirement(params.artifactKind);

    return [
      {
        role: "system",
        content: systemPrompt,
      },
      {
        role: "user",
        content: hasTargetText
          ? `Instruction:\n${instruction}\n\nTarget text:\n${params.selectedText}${contextBlock}\n\nRequirements:\n- Use the local context only to keep terminology, links, and structure consistent.\n- ${outputRequirement}`
          : `Instruction:\n${instruction}\n\nTarget text:\n(none - use the local cursor context)${contextBlock}\n\nRequirements:\n- There is no explicit selection, so generate text that fits naturally at the cursor location.\n- ${outputRequirement}`,
      },
    ];
  }

  private buildRewriteSystemPrompt(artifactKind?: RewriteArtifactKind): string {
    if (artifactKind === "canvas") {
      return "You are an expert Obsidian Canvas generator. Generate production-ready JSON Canvas files that obey the JSON Canvas structure exactly. Return only valid JSON, never explanations, never markdown fences, and never partial structures. The output must be directly saveable as a .canvas file and open cleanly in Obsidian. Ensure nodes and edges are coherent, spatially organized, and semantically useful rather than generic placeholders.";
    }

    if (artifactKind === "base") {
      return "You are an expert Obsidian Bases generator. Generate production-ready .base YAML files that obey Obsidian Bases conventions. Return only valid YAML, never explanations, never markdown fences, and never partial structures. The output must be directly saveable as a .base file and open cleanly in Obsidian. Prefer practical fields, formulas, and views over placeholder content.";
    }

    if (artifactKind === "frontmatter") {
      return "You are an expert Obsidian note metadata assistant. Generate concise, practical YAML frontmatter for the current note. Return only one complete YAML frontmatter block wrapped by --- lines, never explanations, never markdown fences, and never partial YAML. Prefer real-world note properties that help filtering, browsing, and vault consistency. Follow existing folder conventions when they are provided in context.";
    }

    return "You are an editor assistant inside Obsidian. Rewrite, transform, or generate text according to the instruction. Preserve valid Obsidian Flavored Markdown whenever possible, including wikilinks, embeds, callouts, task lists, tables, properties, and inline formatting unless the instruction explicitly changes the format. Return only the final text, with no explanations, no markdown fences, and no surrounding quotes. Never stop mid-list-item, mid-table-row, mid-YAML block, or mid-JSON structure.";
  }

  private buildRewriteOutputRequirement(artifactKind?: RewriteArtifactKind): string {
    if (artifactKind === "canvas") {
      return "Return one complete JSON Canvas document with top-level nodes and edges arrays only. Make it visually useful, not minimal.";
    }

    if (artifactKind === "base") {
      return "Return one complete .base YAML document only. Make it practical and directly usable in Obsidian.";
    }

    if (artifactKind === "frontmatter") {
      return "Return one complete YAML frontmatter block only, wrapped in --- delimiters, ready to insert at the top of the note.";
    }

    return "Return only the final text ready to paste into the note.";
  }

  private getCompletionTokenBudget(prefix: string, suffix: string, accumulated: string, round: number): number {
    if (round > 0) {
      return 96;
    }

    const trimmedPrefix = prefix.trimEnd();
    const trimmedSuffix = suffix.trimStart();
    const currentLine = trimmedPrefix.split("\n").pop() ?? "";

    if (/^\s*#{1,6}\s*$/.test(currentLine)) {
      return 48;
    }

    if (/^\s*(?:[-*+] |\d+\. |> )?$/.test(currentLine)) {
      return 96;
    }

    if (!trimmedSuffix || accumulated.includes("\n")) {
      return 192;
    }

    return 160;
  }

  private removeRepeatedPrefix(existing: string, next: string): string {
    const normalizedNext = next;
    if (!existing) {
      return next;
    }

    if (!normalizedNext.trim()) {
      return "";
    }

    const maxOverlap = Math.min(existing.length, normalizedNext.length, 120);
    for (let size = maxOverlap; size > 0; size--) {
      if (existing.slice(-size) === normalizedNext.slice(0, size)) {
        return normalizedNext.slice(size);
      }
    }

    return normalizedNext;
  }

  private looksSemanticallyComplete(text: string): boolean {
    const normalized = text.trimEnd();
    if (!normalized) {
      return false;
    }

    if (/[。！？.!?…'"）】》]$/.test(normalized)) {
      return true;
    }

    const lastLine = normalized.split("\n").pop() ?? "";
    if (/^\s*(?:[-*+] |\d+\. |> )/.test(lastLine) && lastLine.trim().length >= 8) {
      return true;
    }

    return false;
  }

  private extractText(payload: any): string {
    const content = payload?.choices?.[0]?.message?.content
      ?? payload?.choices?.[0]?.text
      ?? payload?.candidates?.[0]?.content?.parts
      ?? payload?.message?.content
      ?? payload?.response
      ?? "";
    if (typeof content === "string") {
      return content.trim();
    }
    if (Array.isArray(content)) {
      return content
        .map((item) => {
          if (typeof item === "string") return item;
          if (item?.thought === true) return "";
          return item?.text || item?.content || "";
        })
        .join("")
        .trim();
    }
    return "";
  }

  private normalizeFinishReason(finishReason: unknown): string | undefined {
    if (typeof finishReason !== "string" || !finishReason.trim()) return undefined;
    const normalized = finishReason.trim().toLowerCase();
    return normalized === "max_tokens" ? "length" : normalized;
  }

  private trimCompletionToBoundary(text: string): string {
    const normalized = text.trim();
    if (!normalized) {
      return normalized;
    }

    const boundaryMatches = Array.from(normalized.matchAll(/[。！？.!?；;:\n]/g));
    if (boundaryMatches.length > 0) {
      const lastBoundary = boundaryMatches[boundaryMatches.length - 1];
      const index = (lastBoundary.index ?? -1) + lastBoundary[0].length;
      if (index >= Math.max(12, Math.floor(normalized.length * 0.45))) {
        return normalized.slice(0, index).trimEnd();
      }
    }

    const lastWhitespace = normalized.lastIndexOf(" ");
    if (lastWhitespace >= Math.max(12, Math.floor(normalized.length * 0.6))) {
      return normalized.slice(0, lastWhitespace).trimEnd();
    }

    return normalized;
  }

  private async *streamText(text: string, signal?: AbortSignal): AsyncIterable<string> {
    const chunks = text.split(/(\s+)/).filter((item) => item.length > 0);
    for (const chunk of chunks) {
      if (signal?.aborted) {
        throw new DOMException("Aborted", "AbortError");
      }
      yield chunk;
      await this.delay(18, signal);
    }
  }

  private delay(ms: number, signal?: AbortSignal): Promise<void> {
    return new Promise((resolve, reject) => {
      if (signal?.aborted) {
        reject(new DOMException("Aborted", "AbortError"));
        return;
      }
      const timer = window.setTimeout(resolve, ms);
      const onAbort = () => {
        window.clearTimeout(timer);
        reject(new DOMException("Aborted", "AbortError"));
      };
      signal?.addEventListener("abort", onAbort, { once: true });
    });
  }

  private buildRewriteInstruction(instruction: RewriteInstruction, customPrompt?: string): string {
    switch (instruction) {
      case "improve":
        return "Improve clarity, fluency, and structure while keeping the original meaning.";
      case "fix-grammar":
        return "Fix spelling, grammar, and punctuation issues.";
      case "make-shorter":
        return "Make the text shorter and more concise.";
      case "make-longer":
        return "Expand the text with useful supporting detail.";
      case "simplify":
        return "Rewrite the text in simpler language.";
      case "professional":
        return "Rewrite the text in a professional tone.";
      case "casual":
        return "Rewrite the text in a casual tone.";
      case "translate-en":
        return "Translate the text into English.";
      case "translate-zh":
        return "Translate the text into Simplified Chinese.";
      case "translate-ja":
        return "Translate the text into Japanese.";
      case "translate-de":
        return "Translate the text into German.";
      case "translate-fr":
        return "Translate the text into French.";
      case "translate-es":
        return "Translate the text into Spanish.";
      case "explain":
        return "Explain the text in a clear, structured way.";
      case "summarize":
        return "Summarize the text while preserving the key points.";
      case "continue":
        return "Continue writing in a consistent tone and style.";
      case "custom":
        return customPrompt?.trim() || "Rewrite the selected text.";
      default:
        return "Rewrite the selected text.";
    }
  }
}

import { Notice, Platform, requestUrl } from "obsidian";
import type EditingToolbarPlugin from "src/plugin/main";
import { t } from "src/translations/helper";
import { getPKMerAuthorizationEntryUrl } from "./pkmerWeb";
import { PKMER_OAUTH_CONFIG, PKMER_SECRET_KEYS, type PKMerUserInfo } from "./types";

function base64url(buffer: ArrayBuffer): string {
  const bytes = new Uint8Array(buffer);
  let binary = "";
  for (let index = 0; index < bytes.length; index++) {
    binary += String.fromCharCode(bytes[index]);
  }
  return btoa(binary).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

export class PKMerAuthService {
  private plugin: EditingToolbarPlugin;
  private cachedVerified: boolean | null = null;
  private refreshPromise: Promise<boolean> | null = null;
  private callbackServer: any = null;
  private callbackCodeResolve: ((code: string | null) => void) | null = null;
  private pendingCodeVerifier: string | null = null;
  private pendingState: string | null = null;
  private pendingAuthorizationUrl: string | null = null;
  private memAccessToken: string | null = null;
  private memRefreshToken: string | null = null;
  private memAiToken: string | null = null;
  private memCustomModelApiKey: string | null = null;

  constructor(plugin: EditingToolbarPlugin) {
    this.plugin = plugin;
  }

  private get secrets() {
    return (this.plugin.app as any).secretStorage;
  }

  private get supportsSecretStorage(): boolean {
    return !!this.secrets && typeof this.secrets.getSecret === "function" && typeof this.secrets.setSecret === "function";
  }

  loadSecrets(): void {
    if (!this.supportsSecretStorage) return;
    this.memAccessToken = this.secrets.getSecret(PKMER_SECRET_KEYS.accessToken) ?? null;
    this.memRefreshToken = this.secrets.getSecret(PKMER_SECRET_KEYS.refreshToken) ?? null;
    this.memAiToken = this.secrets.getSecret(PKMER_SECRET_KEYS.aiToken) ?? null;
    this.memCustomModelApiKey = this.secrets.getSecret(PKMER_SECRET_KEYS.customModelApiKey) ?? null;
  }

  async syncLoginState(): Promise<void> {
    // token 存在但 userInfo 为空（如重装插件后），自动补全登录状态
    if (this.memAccessToken && !this.plugin.settings.ai.pkmer.userInfo) {
      const valid = await this.verify();
      if (valid) {
        await this.fetchUserInfo();
        this.cachedVerified = true;
      } else {
        // token 已失效，清理残留
        this.clearSecrets();
      }
    }
  }

  private setAccessToken(token: string): void {
    this.memAccessToken = token;
    if (this.supportsSecretStorage) this.secrets.setSecret(PKMER_SECRET_KEYS.accessToken, token);
  }

  private setRefreshToken(token: string): void {
    this.memRefreshToken = token;
    if (this.supportsSecretStorage) this.secrets.setSecret(PKMER_SECRET_KEYS.refreshToken, token);
  }

  private setAiToken(token: string): void {
    this.memAiToken = token;
    if (this.supportsSecretStorage) this.secrets.setSecret(PKMER_SECRET_KEYS.aiToken, token);
  }

  private clearSecrets(): void {
    this.memAccessToken = null;
    this.memRefreshToken = null;
    this.memAiToken = null;
    this.memCustomModelApiKey = null;
    if (this.supportsSecretStorage) {
      this.secrets.setSecret(PKMER_SECRET_KEYS.accessToken, "");
      this.secrets.setSecret(PKMER_SECRET_KEYS.refreshToken, "");
      this.secrets.setSecret(PKMER_SECRET_KEYS.aiToken, "");
      this.secrets.setSecret(PKMER_SECRET_KEYS.customModelApiKey, "");
    }
  }

  get accessToken(): string {
    return this.memAccessToken ?? "";
  }

  get aiToken(): string {
    return this.memAiToken ?? "";
  }

  get customModelApiKey(): string {
    return this.memCustomModelApiKey ?? "";
  }

  get hasSecureStorage(): boolean {
    return this.supportsSecretStorage;
  }

  async migrateCustomModelApiKeyFromSettings(): Promise<void> {
    const legacyApiKey = this.plugin.settings.ai.customModel.apiKey?.trim();
    if (!legacyApiKey || !this.supportsSecretStorage) {
      return;
    }

    this.setCustomModelApiKey(legacyApiKey);
    this.plugin.settings.ai.customModel.apiKey = "";
    await this.plugin.saveSettings();
  }

  setCustomModelApiKey(apiKey: string): void {
    const normalized = apiKey.trim();
    this.memCustomModelApiKey = normalized || null;
    if (this.supportsSecretStorage) {
      this.secrets.setSecret(PKMER_SECRET_KEYS.customModelApiKey, normalized);
    }
  }

  clearCustomModelApiKey(): void {
    this.memCustomModelApiKey = null;
    if (this.supportsSecretStorage) {
      this.secrets.setSecret(PKMER_SECRET_KEYS.customModelApiKey, "");
    }
  }

  async verify(): Promise<boolean> {
    const pkmer = this.plugin.settings.ai.pkmer;
    if (!this.memAccessToken) {
      this.cachedVerified = false;
      return false;
    }
    if (pkmer.tokenExpiresAt && Date.now() < pkmer.tokenExpiresAt) {
      this.cachedVerified = true;
      return true;
    }
    if (this.memRefreshToken) {
      const refreshed = await this.refreshTokens();
      this.cachedVerified = refreshed;
      return refreshed;
    }
    this.cachedVerified = false;
    return false;
  }

  async verifyWithResult(): Promise<{ verified: boolean; userInfo: PKMerUserInfo | null; expiresAt: number }> {
    const verified = await this.verify();
    return {
      verified,
      userInfo: this.plugin.settings.ai.pkmer.userInfo ?? null,
      expiresAt: this.plugin.settings.ai.pkmer.tokenExpiresAt ?? 0,
    };
  }

  async login(): Promise<void> {
    if (!this.supportsSecretStorage) {
      new Notice(t("Current Obsidian version does not support secure token storage."));
      return;
    }

    if (this.hasPendingOAuthRequest()) {
      if (this.pendingAuthorizationUrl) {
        window.open(this.pendingAuthorizationUrl);
        new Notice(t("PKMer login is already in progress. Please continue in the opened browser window."));
        return;
      }
      // Pending state exists but no URL — a previous login attempt failed
      // before opening the browser (e.g. port conflict). Clear the stale
      // state and fall through to start a fresh login.
      this.clearPendingOAuthRequest();
    }

    this.closeCallbackServer();

    const state = this.generateRandom();
    const codeVerifier = this.generateRandom();
    this.pendingCodeVerifier = codeVerifier;
    this.pendingState = state;
    const codeChallenge = await this.computeCodeChallenge(codeVerifier);

    if (Platform.isMobile) {
      const authorizationParams = new URLSearchParams({
        response_type: "code",
        client_id: PKMER_OAUTH_CONFIG.clientId,
        redirect_uri: PKMER_OAUTH_CONFIG.mobileRedirectUri,
        scope: PKMER_OAUTH_CONFIG.scopes,
        state,
        code_challenge: codeChallenge,
        code_challenge_method: "S256",
      });
      const authorizationUrl = `${PKMER_OAUTH_CONFIG.authorizationUrl}?${authorizationParams.toString()}`;
      const loginEntryUrl = getPKMerAuthorizationEntryUrl(authorizationUrl);
      this.pendingAuthorizationUrl = loginEntryUrl;
      window.open(loginEntryUrl);
      window.setTimeout(() => {
        if (this.isPendingStateMatch(state)) {
          this.clearPendingOAuthRequest();
        }
      }, 5 * 60 * 1000);
      return;
    }

    // Desktop: start the callback server on the fixed PKMer port (10891)
    // before opening the browser, so we can detect port conflicts early
    // and show a targeted notice instead of a silent failure.
    const codePromise = new Promise<string | null>((resolve) => {
      this.callbackCodeResolve = resolve;
    });

    const serverStatus = await this.startCallbackServerAndWait();
    if (serverStatus !== "ok") {
      this.callbackCodeResolve = null;
      this.clearPendingOAuthRequest();
      this.showCallbackServerErrorNotice(serverStatus);
      return;
    }

    const desktopRedirectUri = PKMER_OAUTH_CONFIG.desktopRedirectUri;
    const authorizationParams = new URLSearchParams({
      response_type: "code",
      client_id: PKMER_OAUTH_CONFIG.clientId,
      redirect_uri: desktopRedirectUri,
      scope: PKMER_OAUTH_CONFIG.scopes,
      state,
      code_challenge: codeChallenge,
      code_challenge_method: "S256",
    });
    const authorizationUrl = `${PKMER_OAUTH_CONFIG.authorizationUrl}?${authorizationParams.toString()}`;
    const loginEntryUrl = getPKMerAuthorizationEntryUrl(authorizationUrl);
    this.pendingAuthorizationUrl = loginEntryUrl;

    window.open(loginEntryUrl);

    try {
      const code = await codePromise;
      if (!code) {
        new Notice(t("Login cancelled or timed out."));
        return;
      }

      const success = await this.exchangeCodeForTokens(code, desktopRedirectUri);
      if (success) {
        await this.fetchUserInfo();
        new Notice(t("Successfully logged in to PKMer!"));
      } else {
        new Notice(t("Failed to complete login. Please try again."));
      }
    } catch (error) {
      console.error("PKMer OAuth login error:", error);
      new Notice(t("Login failed. Please try again."));
    } finally {
      this.callbackCodeResolve = null;
      this.clearPendingOAuthRequest({ closeServer: true });
    }
  }

  /**
   * Show a user-friendly notice explaining why the login callback server
   * could not start, with actionable steps tailored to the error type.
   */
  private showCallbackServerErrorNotice(status: "EACCES" | "EADDRINUSE" | "EUNKNOWN" | "NO_HTTP"): void {
    const port = PKMER_OAUTH_CONFIG.callbackPort;
    let message: string;

    if (status === "EACCES") {
      message = t("Login failed: local port {{port}} is occupied or reserved by the system. Please release port {{port}} (e.g. restart your computer or close the program using it), then try again.").replace(/\{\{port\}\}/g, String(port));
    } else if (status === "EADDRINUSE") {
      message = t("Login failed: local port {{port}} is already in use. Please close other Obsidian windows or the program using port {{port}}, then try again.").replace(/\{\{port\}\}/g, String(port));
    } else if (status === "NO_HTTP") {
      message = t("Login failed: the local HTTP server module is not available. This usually happens on Obsidian mobile. Please use the mobile login flow instead.");
    } else {
      message = t("Login failed: could not start the local callback server on port {{port}}. Please check your network settings and try again.").replace(/\{\{port\}\}/g, String(port));
    }

    new Notice(message, 15000);
  }

  async handleOAuthCallback(code: string, state: string): Promise<boolean> {
    if (!this.isPendingStateMatch(state)) {
      new Notice(t("OAuth state mismatch. Please try logging in again."));
      this.clearPendingOAuthRequest();
      return false;
    }

    try {
      const success = await this.exchangeCodeForTokens(code, PKMER_OAUTH_CONFIG.mobileRedirectUri);
      if (success) {
        await this.fetchUserInfo();
        new Notice(t("Successfully logged in to PKMer!"));
        return true;
      }
      new Notice(t("Failed to complete login. Please try again."));
      return false;
    } catch (error) {
      console.error("PKMer OAuth callback error:", error);
      new Notice(t("Login failed. Please try again."));
      return false;
    } finally {
      this.clearPendingOAuthRequest();
    }
  }

  async logout(): Promise<void> {
    this.clearSecrets();
    this.plugin.settings.ai.pkmer = {
      ...this.plugin.settings.ai.pkmer,
      tokenExpiresAt: 0,
      userInfo: null,
    };
    this.cachedVerified = false;
    await this.plugin.saveSettings();
    new Notice(t("Logged out from PKMer."));
  }

  async refreshQuota(): Promise<{ quota: number; remainingQuota: number } | null> {
    const valid = await this.verify();
    if (!valid) return null;
    await this.fetchUserInfo();
    return (this.plugin.settings.ai.pkmer.userInfo?.ai_quota as { quota: number; remainingQuota: number } | undefined) ?? null;
  }

  /**
   * Called when an AI request returns 401. Attempts to refresh the
   * access token and re-fetch the AI token. Returns true if a new
   * valid aiToken is available, false if the user must re-login.
   */
  async refreshFor401(): Promise<boolean> {
    if (!this.memRefreshToken) {
      this.clearSecrets();
      return false;
    }

    const refreshed = await this.refreshTokens();
    if (!refreshed) {
      return false;
    }

    await this.fetchUserInfo();
    return !!this.memAiToken;
  }

  onunload(): void {
    this.closeCallbackServer();
  }

  private async computeCodeChallenge(codeVerifier: string): Promise<string> {
    const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(codeVerifier));
    return base64url(digest);
  }

  /**
   * Start the callback server on the fixed PKMer port (10891) and wait
   * until it is actually listening (or fails) before resolving.
   *
   * Returns "ok" on success, or an error code string describing the
   * failure so the caller can show a targeted, user-friendly notice.
   *
   * Common failures on Windows:
   * - "EACCES": port 10891 is inside a Hyper-V/WSL reserved port range.
   * - "EADDRINUSE": another process (or another Obsidian window) is
   *   already listening on port 10891.
   */
  private startCallbackServerAndWait(): Promise<"ok" | "EACCES" | "EADDRINUSE" | "EUNKNOWN" | "NO_HTTP"> {
    return new Promise((resolve) => {
      try {
        const http = (window as any).require("node:http");
        if (!http) {
          resolve("NO_HTTP");
          return;
        }

        const port = PKMER_OAUTH_CONFIG.callbackPort;
        const server = http.createServer((req: any, res: any) => {
          const url = new URL(req.url, `http://localhost:${port}`);

          if (url.pathname !== PKMER_OAUTH_CONFIG.callbackPath) {
            res.writeHead(404);
            res.end();
            return;
          }

          const code = url.searchParams.get("code");
          const state = url.searchParams.get("state");

          if (!this.isPendingStateMatch(state)) {
            res.writeHead(400, { "Content-Type": "text/html; charset=utf-8" });
            res.end("<html><body><h2>State mismatch.</h2><p>Another Obsidian window may have intercepted this callback.</p><p>Please close other Obsidian and try again.</p></body></html>");
            this.callbackCodeResolve?.(null);
          } else if (code) {
            res.writeHead(200, { "Content-Type": "text/html; charset=utf-8" });
            res.end("<html><body><h2>Login successful!</h2><p>You can close this window and return to Obsidian.</p><script>window.close()</script></body></html>");
            this.callbackCodeResolve?.(code);
          } else {
            const error = url.searchParams.get("error") || "unknown error";
            res.writeHead(400, { "Content-Type": "text/html; charset=utf-8" });
            res.end(`<html><body><h2>Login failed: ${error}</h2></body></html>`);
            this.callbackCodeResolve?.(null);
          }

          window.setTimeout(() => this.closeCallbackServer(), 500);
        });

        server.once("error", (error: any) => {
          const code = error?.code ?? "";
          console.error(`Callback server error on port ${port}:`, error);
          this.callbackServer = null;
          if (code === "EACCES") { resolve("EACCES"); return; }
          if (code === "EADDRINUSE") { resolve("EADDRINUSE"); return; }
          resolve("EUNKNOWN");
        });

        server.once("listening", () => {
          this.callbackServer = server;
          resolve("ok");
        });

        server.listen(port, "127.0.0.1");

        window.setTimeout(() => {
          if (this.callbackServer === server) {
            this.closeCallbackServer();
            this.callbackCodeResolve?.(null);
          }
        }, 5 * 60 * 1000);
      } catch (error) {
        console.error("Failed to start callback server:", error);
        resolve("EUNKNOWN");
      }
    });
  }

  private closeCallbackServer(): void {
    if (!this.callbackServer) return;
    try {
      this.callbackServer.close();
    } catch {
      // ignore
    }
    this.callbackServer = null;
  }

  private hasPendingOAuthRequest(): boolean {
    return !!this.pendingState && !!this.pendingCodeVerifier;
  }

  private isPendingStateMatch(state: string | null): boolean {
    return !!state && !!this.pendingState && state === this.pendingState;
  }

  private clearPendingOAuthRequest(options?: { closeServer?: boolean }): void {
    this.pendingState = null;
    this.pendingCodeVerifier = null;
    this.pendingAuthorizationUrl = null;
    if (options?.closeServer) {
      this.closeCallbackServer();
    }
  }

  private async exchangeCodeForTokens(code: string, redirectUri: string): Promise<boolean> {
    try {
      const body: Record<string, string> = {
        grant_type: "authorization_code",
        code,
        redirect_uri: redirectUri,
        client_id: PKMER_OAUTH_CONFIG.clientId,
      };

      if (this.pendingCodeVerifier) {
        body.code_verifier = this.pendingCodeVerifier;
      }

      const response = await requestUrl({
        url: PKMER_OAUTH_CONFIG.tokenUrl,
        method: "POST",
        headers: { "Content-Type": "application/x-www-form-urlencoded" },
        body: new URLSearchParams(body).toString(),
      });

      const data = response.json;
      if (!data.access_token) return false;

      this.setAccessToken(data.access_token);
      this.setRefreshToken(data.refresh_token || "");
      this.plugin.settings.ai.pkmer = {
        ...this.plugin.settings.ai.pkmer,
        tokenExpiresAt: Date.now() + (data.expires_in ?? 3600) * 1000,
      };
      await this.plugin.saveSettings();
      this.cachedVerified = true;
      return true;
    } catch (error) {
      console.error("Token exchange failed:", error);
      return false;
    }
  }

  private async refreshTokens(): Promise<boolean> {
    if (this.refreshPromise) return this.refreshPromise;

    this.refreshPromise = (async () => {
      try {
        const response = await requestUrl({
          url: PKMER_OAUTH_CONFIG.tokenUrl,
          method: "POST",
          headers: { "Content-Type": "application/x-www-form-urlencoded" },
          body: new URLSearchParams({
            grant_type: "refresh_token",
            refresh_token: this.memRefreshToken || "",
            client_id: PKMER_OAUTH_CONFIG.clientId,
          }).toString(),
        });

        const data = response.json;
        if (!data.access_token) return false;

        this.setAccessToken(data.access_token);
        if (data.refresh_token) {
          this.setRefreshToken(data.refresh_token);
        }

        this.plugin.settings.ai.pkmer = {
          ...this.plugin.settings.ai.pkmer,
          tokenExpiresAt: Date.now() + (data.expires_in ?? 3600) * 1000,
        };
        await this.plugin.saveSettings();
        return true;
      } catch (error) {
        console.error("Token refresh failed:", error);
        this.clearSecrets();
        this.plugin.settings.ai.pkmer = {
          ...this.plugin.settings.ai.pkmer,
          tokenExpiresAt: 0,
          userInfo: null,
        };
        await this.plugin.saveSettings();
        return false;
      }
    })();

    try {
      return await this.refreshPromise;
    } finally {
      this.refreshPromise = null;
    }
  }

  private async fetchUserInfo(): Promise<void> {
    try {
      const response = await requestUrl({
        url: PKMER_OAUTH_CONFIG.userinfoUrl,
        method: "GET",
        headers: {
          Authorization: `Bearer ${this.memAccessToken}`,
        },
      });

      const data = response.json;
      if (data.ai_token) {
        this.setAiToken(data.ai_token);
      }

      this.plugin.settings.ai.pkmer = {
        ...this.plugin.settings.ai.pkmer,
        userInfo: {
          sub: data.sub || data.id || "",
          name: data.name || data.preferred_username || data.username || undefined,
          email: data.email || undefined,
          avatar: data.picture || data.avatar || undefined,
          ai_quota: data.ai_quota || undefined,
          device_count: data.device_count ?? undefined,
          thino: data.thino ?? undefined,
          thinoWebExpir: data.thinoWebExpir ?? undefined,
          supporter: data.supporter ?? undefined,
        },
      };
      await this.plugin.saveSettings();
    } catch (error) {
      console.error("Failed to fetch user info:", error);
    }
  }

  private generateRandom(): string {
    const array = new Uint8Array(32);
    crypto.getRandomValues(array);
    return Array.from(array, (value) => value.toString(16).padStart(2, "0")).join("");
  }
}

import { t } from "src/translations/helper";
import type { RewriteArtifactKind } from "./types";

interface NormalizeArtifactRequest {
  kind: RewriteArtifactKind;
  content: string;
  sourceText: string;
}

type CanvasNodeType = "text" | "file" | "link" | "group";

interface CanvasNodeRecord {
  id: string;
  type: CanvasNodeType;
  x: number;
  y: number;
  width: number;
  height: number;
  text?: string;
  file?: string;
  url?: string;
  label?: string;
  color?: string;
  background?: string;
  backgroundStyle?: string;
}

interface CanvasEdgeRecord {
  id: string;
  fromNode: string;
  toNode: string;
  fromSide?: string;
  toSide?: string;
  fromEnd?: string;
  toEnd?: string;
  color?: string;
  label?: string;
}

interface CanvasDocumentRecord {
  nodes: CanvasNodeRecord[];
  edges: CanvasEdgeRecord[];
}

const CANVAS_NODE_TYPES = new Set<CanvasNodeType>(["text", "file", "link", "group"]);
const CANVAS_SIDES = new Set(["top", "right", "bottom", "left"]);
const CANVAS_ENDS = new Set(["none", "arrow"]);

export function normalizeGeneratedArtifactContent(request: NormalizeArtifactRequest): string {
  const stripped = stripCodeFence(stripAIReasoningBlocks(request.content));
  if (!stripped) {
    throw new Error(t("AI generated content is empty."));
  }

  if (request.kind === "canvas") {
    return normalizeCanvasContent(stripped, request.sourceText);
  }

  return normalizeBaseContent(stripped, request.sourceText);
}

export function normalizeGeneratedFrontmatter(content: string, preferredKeyMap: Record<string, string> = {}): string {
  const cleaned = stripAIReasoningBlocks(content);
  const frontmatterBlock = extractFrontmatterBlock(cleaned);
  const yamlCodeBlock = frontmatterBlock ? null : extractYamlCodeBlock(cleaned);
  const stripped = stripCodeFence(frontmatterBlock ?? yamlCodeBlock ?? cleaned);
  if (!stripped) {
    throw new Error(t("AI generated content is empty."));
  }

  const inner = stripped
    .replace(/^---\s*\n?/i, "")
    .replace(/\n?---\s*$/i, "")
    .trim();

  if (!inner) {
    throw new Error(t("AI generated content is empty."));
  }

  const normalizedInner = applyPreferredFrontmatterKeys(inner, preferredKeyMap);
  return `---\n${normalizedInner}\n---\n\n`;
}

function stripAIReasoningBlocks(content: string): string {
  let cleaned = content.replace(/\r\n?/g, "\n");
  const reasoningTag = "(?:think|thinking|reasoning)";

  cleaned = cleaned.replace(new RegExp(`<${reasoningTag}\\b[^>]*>[\\s\\S]*?<\\/${reasoningTag}>`, "gi"), "");
  cleaned = cleaned.replace(new RegExp(`^\\s*<${reasoningTag}\\b[^>]*>[\\s\\S]*?(?=(?:\\n)?---[ \\t]*(?:\\n|$))`, "i"), "");

  if (new RegExp(`^\\s*<${reasoningTag}\\b[^>]*>`, "i").test(cleaned)) {
    const yamlStart = cleaned.search(/\n[A-Za-z0-9_-]+:(?:\s|$)/);
    cleaned = yamlStart >= 0 ? cleaned.slice(yamlStart + 1) : "";
  }

  cleaned = cleaned.replace(new RegExp(`<\\/?${reasoningTag}\\b[^>]*>`, "gi"), "");

  return cleaned.trim();
}

function extractYamlCodeBlock(content: string): string | null {
  const normalized = content.replace(/\r\n?/g, "\n").trim();
  const match = normalized.match(/```(?:yaml|yml)?[ \t]*\n([\s\S]*?)\n```/i);
  return match ? match[1].trim() : null;
}
function extractFrontmatterBlock(content: string): string | null {
  const normalized = content.replace(/\r\n?/g, "\n").trim();
  const match = normalized.match(/(?:^|\n)---[ \t]*\n[\s\S]*?\n---[ \t]*(?=\n|$)/);
  return match ? match[0].replace(/^\n/, "").trim() : null;
}
function applyPreferredFrontmatterKeys(content: string, preferredKeyMap: Record<string, string>): string {
  if (!preferredKeyMap || Object.keys(preferredKeyMap).length === 0) {
    return content;
  }

  const lines = content.replace(/\r\n?/g, "\n").split("\n");
  const existingTopLevelKeys = new Set(
    lines
      .map((line) => line.match(/^([A-Za-z0-9_-]+):(?:\s|$)/)?.[1])
      .filter((key): key is string => !!key),
  );

  return lines
    .map((line) => {
      const match = line.match(/^([A-Za-z0-9_-]+):(.*)$/);
      if (!match) {
        return line;
      }

      const [, key, rest] = match;
      const preferredKey = preferredKeyMap[key];
      if (!preferredKey || preferredKey === key) {
        return line;
      }

      if (existingTopLevelKeys.has(preferredKey)) {
        return line;
      }

      return `${preferredKey}:${rest}`;
    })
    .join("\n")
    .trim();
}

function stripCodeFence(content: string): string {
  return content
    .trim()
    .replace(/^```(?:json|yaml|yml)?\s*/i, "")
    .replace(/\s*```\s*$/i, "")
    .trim();
}

function normalizeBaseContent(content: string, sourceText: string): string {
  const normalized = content.replace(/\r\n?/g, "\n").replace(/\t/g, "  ").trim();
  const hasKnownTopLevelKey = /^(filters|formulas|properties|summaries|views):/m.test(normalized);

  if (!hasKnownTopLevelKey) {
    return `${buildFallbackBaseContent(sourceText)}\n`;
  }

  let output = normalized;

  if (!/^views:/m.test(output)) {
    output = `${output}\n\n${buildDefaultBaseViewBlock()}`;
  } else if (!/^\s*-\s+type:/m.test(output)) {
    output = output.replace(/^views:\s*$/m, `views:\n${indentBlock(buildDefaultBaseViewItem(), 2)}`);
  }

  if (!/^\s+order:\s*$/m.test(output)) {
    output = output.replace(
      /(^\s*-\s+type:\s+[\w-]+\s*\n\s+name:\s+.+$)/m,
      `$1\n  order:\n    - file.name`,
    );
  }

  return `${output.trim()}\n`;
}

function buildFallbackBaseContent(sourceText: string): string {
  const sourceHint = buildSourceLabel(sourceText);
  return [
    "filters:",
    "  and: []",
    "properties:",
    '  file.name:',
    '    displayName: "Name"',
    '  file.folder:',
    '    displayName: "Folder"',
    "views:",
    '  - type: table',
    `    name: "${escapeYamlDoubleQuoted(sourceHint)}"`,
    "    order:",
    "      - file.name",
    "      - file.folder",
  ].join("\n");
}

function buildDefaultBaseViewBlock(): string {
  return [
    "views:",
    ...buildDefaultBaseViewItem().split("\n"),
  ].join("\n");
}

function buildDefaultBaseViewItem(): string {
  return [
    "- type: table",
    '  name: "Overview"',
    "  order:",
    "    - file.name",
  ].join("\n");
}

function escapeYamlDoubleQuoted(value: string): string {
  return value.replace(/\\/g, "\\\\").replace(/"/g, '\\"');
}

function normalizeCanvasContent(content: string, sourceText: string): string {
  let parsed: unknown;
  try {
    parsed = JSON.parse(content);
  } catch {
    throw new Error(t("AI returned invalid Canvas JSON."));
  }

  if (!parsed || typeof parsed !== "object") {
    throw new Error(t("AI returned invalid Canvas JSON."));
  }

  const rawDoc = parsed as Record<string, unknown>;
  const idRegistry = new Set<string>();
  const inputNodes = Array.isArray(rawDoc.nodes) ? rawDoc.nodes : [];
  const inputEdges = Array.isArray(rawDoc.edges) ? rawDoc.edges : [];

  let nodes = inputNodes
    .map((item, index) => normalizeCanvasNode(item, idRegistry, sourceText, index))
    .filter((item): item is CanvasNodeRecord => item !== null);

  if (nodes.length === 0) {
    nodes = [buildFallbackCanvasNode(idRegistry, sourceText)];
  }

  let edges = inputEdges
    .map((item) => normalizeCanvasEdge(item, idRegistry, new Set(nodes.map((node) => node.id))))
    .filter((item): item is CanvasEdgeRecord => item !== null);

  if (edges.length === 0 && nodes.filter((node) => node.type !== "group").length > 2) {
    edges = buildFallbackCanvasEdges(nodes, idRegistry);
  }

  const normalizedDoc = autoLayoutCanvas({ nodes, edges }, sourceText, idRegistry);
  return `${JSON.stringify(normalizedDoc, null, 2)}\n`;
}

function normalizeCanvasNode(
  input: unknown,
  idRegistry: Set<string>,
  sourceText: string,
  index: number,
): CanvasNodeRecord | null {
  if (!input || typeof input !== "object") {
    return null;
  }

  const raw = input as Record<string, unknown>;
  const type = CANVAS_NODE_TYPES.has(raw.type as CanvasNodeType) ? (raw.type as CanvasNodeType) : "text";
  const id = normalizeHexId(raw.id, idRegistry);
  const color = typeof raw.color === "string" && raw.color.trim() ? raw.color.trim() : undefined;

  if (type === "group") {
    return {
      id,
      type,
      x: toNumber(raw.x, index * 60 - 40),
      y: toNumber(raw.y, -60),
      width: clampNumber(raw.width, 680, 240, 2800),
      height: clampNumber(raw.height, 420, 160, 2200),
      label: typeof raw.label === "string" ? raw.label.trim() : buildSourceLabel(sourceText),
      color,
      background: typeof raw.background === "string" ? raw.background : undefined,
      backgroundStyle: typeof raw.backgroundStyle === "string" ? raw.backgroundStyle : undefined,
    };
  }

  if (type === "file" && typeof raw.file === "string" && raw.file.trim()) {
    return {
      id,
      type,
      x: toNumber(raw.x, 0),
      y: toNumber(raw.y, 0),
      width: clampNumber(raw.width, 360, 260, 560),
      height: clampNumber(raw.height, 240, 160, 420),
      file: raw.file.trim(),
      color,
    };
  }

  if (type === "link" && typeof raw.url === "string" && raw.url.trim()) {
    return {
      id,
      type,
      x: toNumber(raw.x, 0),
      y: toNumber(raw.y, 0),
      width: clampNumber(raw.width, 320, 240, 520),
      height: clampNumber(raw.height, 180, 120, 320),
      url: raw.url.trim(),
      color,
    };
  }

  const text = buildCanvasNodeText(raw, sourceText, index);
  const size = estimateTextNodeSize(text);

  return {
    id,
    type: "text",
    x: toNumber(raw.x, 0),
    y: toNumber(raw.y, 0),
    width: clampNumber(raw.width, size.width, 220, 620),
    height: clampNumber(raw.height, size.height, 90, 420),
    text,
    color,
  };
}

function normalizeCanvasEdge(
  input: unknown,
  idRegistry: Set<string>,
  nodeIds: Set<string>,
): CanvasEdgeRecord | null {
  if (!input || typeof input !== "object") {
    return null;
  }

  const raw = input as Record<string, unknown>;
  const fromNode = typeof raw.fromNode === "string" ? raw.fromNode.trim() : "";
  const toNode = typeof raw.toNode === "string" ? raw.toNode.trim() : "";

  if (!nodeIds.has(fromNode) || !nodeIds.has(toNode) || fromNode === toNode) {
    return null;
  }

  return {
    id: normalizeHexId(raw.id, idRegistry),
    fromNode,
    toNode,
    fromSide: normalizeAllowedValue(raw.fromSide, CANVAS_SIDES),
    toSide: normalizeAllowedValue(raw.toSide, CANVAS_SIDES),
    fromEnd: normalizeAllowedValue(raw.fromEnd, CANVAS_ENDS),
    toEnd: normalizeAllowedValue(raw.toEnd, CANVAS_ENDS) ?? "arrow",
    color: typeof raw.color === "string" && raw.color.trim() ? raw.color.trim() : undefined,
    label: typeof raw.label === "string" && raw.label.trim() ? raw.label.trim() : undefined,
  };
}

function autoLayoutCanvas(
  doc: CanvasDocumentRecord,
  sourceText: string,
  idRegistry: Set<string>,
): CanvasDocumentRecord {
  const regularNodes = doc.nodes.filter((node) => node.type !== "group");
  const groupNodes = doc.nodes.filter((node) => node.type === "group");

  const adjacency = new Map<string, Set<string>>();
  const degree = new Map<string, number>();
  for (const node of regularNodes) {
    adjacency.set(node.id, new Set());
    degree.set(node.id, 0);
  }

  for (const edge of doc.edges) {
    if (!adjacency.has(edge.fromNode) || !adjacency.has(edge.toNode)) {
      continue;
    }
    adjacency.get(edge.fromNode)?.add(edge.toNode);
    adjacency.get(edge.toNode)?.add(edge.fromNode);
    degree.set(edge.fromNode, (degree.get(edge.fromNode) ?? 0) + 1);
    degree.set(edge.toNode, (degree.get(edge.toNode) ?? 0) + 1);
  }

  const root = chooseCanvasRoot(regularNodes, degree, sourceText);
  const layers = buildCanvasLayers(regularNodes, adjacency, root?.id);
  const xGap = 420;
  const yGap = 220;

  layers.forEach((layer, layerIndex) => {
    const totalHeight = layer.reduce((sum, node) => sum + node.height, 0) + Math.max(0, layer.length - 1) * 42;
    let cursorY = -Math.round(totalHeight / 2);
    layer.forEach((node) => {
      node.x = layerIndex * xGap;
      node.y = cursorY;
      cursorY += node.height + 42;
    });
  });

  if (regularNodes.length === 1) {
    regularNodes[0].x = 0;
    regularNodes[0].y = 0;
  }

  const normalizedGroups = normalizeCanvasGroups(groupNodes, regularNodes, idRegistry, sourceText);
  return {
    nodes: [...normalizedGroups, ...regularNodes],
    edges: doc.edges,
  };
}

function chooseCanvasRoot(
  nodes: CanvasNodeRecord[],
  degree: Map<string, number>,
  sourceText: string,
): CanvasNodeRecord | null {
  if (nodes.length === 0) {
    return null;
  }

  const headingLikeNode = nodes.find((node) => (node.text || "").trim().startsWith("# "));
  if (headingLikeNode) {
    return headingLikeNode;
  }

  const titleHint = buildSourceLabel(sourceText).toLowerCase();
  const matchingNode = nodes.find((node) => (node.text || "").toLowerCase().includes(titleHint));
  if (matchingNode) {
    return matchingNode;
  }

  return [...nodes].sort((left, right) => {
    const degreeDiff = (degree.get(right.id) ?? 0) - (degree.get(left.id) ?? 0);
    if (degreeDiff !== 0) {
      return degreeDiff;
    }
    return (right.text || "").length - (left.text || "").length;
  })[0];
}

function buildCanvasLayers(
  nodes: CanvasNodeRecord[],
  adjacency: Map<string, Set<string>>,
  rootId?: string,
): CanvasNodeRecord[][] {
  if (nodes.length === 0) {
    return [];
  }

  const nodeById = new Map(nodes.map((node) => [node.id, node]));
  const visited = new Set<string>();
  const orderedRoots = rootId ? [rootId, ...nodes.map((node) => node.id).filter((id) => id !== rootId)] : nodes.map((node) => node.id);
  const layers: CanvasNodeRecord[][] = [];

  for (const candidateId of orderedRoots) {
    if (visited.has(candidateId) || !nodeById.has(candidateId)) {
      continue;
    }

    const queue: Array<{ id: string; depth: number }> = [{ id: candidateId, depth: layers.length === 0 ? 0 : layers.length }];
    visited.add(candidateId);

    while (queue.length > 0) {
      const current = queue.shift();
      if (!layers[current.depth]) {
        layers[current.depth] = [];
      }
      layers[current.depth].push(nodeById.get(current.id));

      const neighbors = [...(adjacency.get(current.id) ?? [])]
        .filter((neighborId) => !visited.has(neighborId))
        .sort((left, right) => (nodeById.get(right)?.text || "").length - (nodeById.get(left)?.text || "").length);

      neighbors.forEach((neighborId) => {
        visited.add(neighborId);
        queue.push({ id: neighborId, depth: current.depth + 1 });
      });
    }
  }

  return layers.filter((layer) => layer && layer.length > 0);
}

function normalizeCanvasGroups(
  groups: CanvasNodeRecord[],
  regularNodes: CanvasNodeRecord[],
  idRegistry: Set<string>,
  sourceText: string,
): CanvasNodeRecord[] {
  if (regularNodes.length === 0) {
    return groups;
  }

  const bounds = getCanvasBounds(regularNodes);
  if (groups.length === 0) {
    return [
      {
        id: normalizeHexId(undefined, idRegistry),
        type: "group",
        x: bounds.x - 70,
        y: bounds.y - 70,
        width: bounds.width + 140,
        height: bounds.height + 140,
        label: buildSourceLabel(sourceText),
        color: "4",
      },
    ];
  }

  const [firstGroup, ...restGroups] = groups;
  firstGroup.x = bounds.x - 70;
  firstGroup.y = bounds.y - 70;
  firstGroup.width = bounds.width + 140;
  firstGroup.height = bounds.height + 140;
  firstGroup.label = firstGroup.label || buildSourceLabel(sourceText);

  restGroups.forEach((group, index) => {
    group.x = bounds.x - 70 + (index + 1) * 24;
    group.y = bounds.y - 70 + (index + 1) * 24;
    group.width = Math.max(240, bounds.width + 90 - (index + 1) * 18);
    group.height = Math.max(180, bounds.height + 90 - (index + 1) * 18);
  });

  return groups;
}

function getCanvasBounds(nodes: CanvasNodeRecord[]): { x: number; y: number; width: number; height: number } {
  const minX = Math.min(...nodes.map((node) => node.x));
  const minY = Math.min(...nodes.map((node) => node.y));
  const maxX = Math.max(...nodes.map((node) => node.x + node.width));
  const maxY = Math.max(...nodes.map((node) => node.y + node.height));
  return {
    x: minX,
    y: minY,
    width: maxX - minX,
    height: maxY - minY,
  };
}

function buildFallbackCanvasEdges(nodes: CanvasNodeRecord[], idRegistry: Set<string>): CanvasEdgeRecord[] {
  const regularNodes = nodes.filter((node) => node.type !== "group");
  if (regularNodes.length < 2) {
    return [];
  }

  const [root, ...others] = regularNodes;
  return others.map((node) => ({
    id: normalizeHexId(undefined, idRegistry),
    fromNode: root.id,
    toNode: node.id,
    toEnd: "arrow",
  }));
}

function buildFallbackCanvasNode(idRegistry: Set<string>, sourceText: string): CanvasNodeRecord {
  const text = buildFallbackCanvasNodeText(sourceText);
  const size = estimateTextNodeSize(text);
  return {
    id: normalizeHexId(undefined, idRegistry),
    type: "text",
    x: 0,
    y: 0,
    width: size.width,
    height: size.height,
    text,
  };
}

function buildCanvasNodeText(raw: Record<string, unknown>, sourceText: string, index: number): string {
  const candidates = [
    raw.text,
    raw.label,
    raw.title,
    raw.name,
    raw.file,
    raw.url,
  ];

  for (const candidate of candidates) {
    if (typeof candidate === "string" && candidate.trim()) {
      return candidate.trim().replace(/\\n/g, "\n");
    }
  }

  const lines = sourceText.replace(/\r\n?/g, "\n").split("\n").map((line) => line.trim()).filter(Boolean);
  if (lines[index]) {
    return lines[index];
  }

  return buildFallbackCanvasNodeText(sourceText);
}

function buildFallbackCanvasNodeText(sourceText: string): string {
  const lines = sourceText
    .replace(/\r\n?/g, "\n")
    .split("\n")
    .map((line) => line.trim())
    .filter(Boolean)
    .slice(0, 6);

  if (lines.length === 0) {
    return "# Canvas\n\n- Key point";
  }

  const [first, ...rest] = lines;
  const bullets = rest.slice(0, 4).map((line) => `- ${line.replace(/^[-*+]\s+/, "")}`);
  return [`# ${truncateText(first, 48)}`, bullets.length ? "" : null, ...bullets].filter((item): item is string => item !== null).join("\n");
}

function buildSourceLabel(sourceText: string): string {
  const firstLine = sourceText.replace(/\r\n?/g, "\n").split("\n").map((line) => line.trim()).find(Boolean);
  return truncateText(firstLine || t("Untitled"), 42);
}

function estimateTextNodeSize(text: string): { width: number; height: number } {
  const lines = text.split("\n");
  const maxLineLength = lines.reduce((max, line) => Math.max(max, line.length), 0);
  const width = Math.min(520, Math.max(260, 180 + maxLineLength * 6));
  const height = Math.min(320, Math.max(110, 70 + lines.length * 28));
  return { width, height };
}

function truncateText(value: string, maxLength: number): string {
  const normalized = value.trim();
  if (normalized.length <= maxLength) {
    return normalized;
  }

  return `${normalized.slice(0, Math.max(0, maxLength - 1)).trimEnd()}…`;
}

function indentBlock(value: string, spaces: number): string {
  const indent = " ".repeat(spaces);
  return value.split("\n").map((line) => `${indent}${line}`).join("\n");
}

function normalizeAllowedValue(value: unknown, allowed: Set<string>): string | undefined {
  if (typeof value !== "string") {
    return undefined;
  }

  const normalized = value.trim();
  return allowed.has(normalized) ? normalized : undefined;
}

function normalizeHexId(value: unknown, registry: Set<string>): string {
  if (typeof value === "string") {
    const normalized = value.trim().toLowerCase();
    if (/^[0-9a-f]{16}$/.test(normalized) && !registry.has(normalized)) {
      registry.add(normalized);
      return normalized;
    }
  }

  let nextId: string;
  do {
    nextId = generateHexId();
  } while (registry.has(nextId));

  registry.add(nextId);
  return nextId;
}

function generateHexId(): string {
  const values = new Uint8Array(8);
  if (typeof crypto !== "undefined" && typeof crypto.getRandomValues === "function") {
    crypto.getRandomValues(values);
  } else {
    for (let index = 0; index < values.length; index += 1) {
      values[index] = Math.floor(Math.random() * 256);
    }
  }

  return Array.from(values, (value) => value.toString(16).padStart(2, "0")).join("");
}

function toNumber(value: unknown, fallback: number): number {
  return typeof value === "number" && Number.isFinite(value) ? value : fallback;
}

function clampNumber(value: unknown, fallback: number, min: number, max: number): number {
  const numeric = toNumber(value, fallback);
  return Math.max(min, Math.min(max, Math.round(numeric)));
}

import { Notice } from "obsidian";
import { t } from "src/translations/helper";

const NOTICE_THROTTLE_MS = 6000;
const noticeHistory = new Map<string, number>();

export class AIUserNoticeError extends Error {
  noticeDuration: number;

  constructor(message: string, noticeDuration = 8000) {
    super(message);
    this.name = "AIUserNoticeError";
    this.noticeDuration = noticeDuration;
  }
}

export function getRequestErrorStatus(error: unknown): number | null {
  const directStatus = (error as { status?: unknown } | null)?.status;
  if (typeof directStatus === "number") {
    return directStatus;
  }

  const responseStatus = (error as { response?: { status?: unknown } } | null)?.response?.status;
  if (typeof responseStatus === "number") {
    return responseStatus;
  }

  // Fallback: Obsidian's requestUrl throws "Request failed, status XXX" when
  // throw is not explicitly set to false. Parse the status from the message so
  // auth/quota detection still works for those errors.
  const message = (error as { message?: unknown } | null)?.message;
  if (typeof message === "string") {
    const match = message.match(/status\s+(\d{3})/i);
    if (match) {
      return Number(match[1]);
    }
  }

  return null;
}

export function getAIErrorMessage(error: unknown): string {
  if (error instanceof Error && error.message.trim()) {
    return error.message.trim();
  }

  if (typeof error === "string" && error.trim()) {
    return error.trim();
  }

  const response = (error as { response?: { json?: any; text?: unknown } } | null)?.response;
  // response.json is a getter that may throw SyntaxError on non-JSON bodies.
  let parsedJson: any;
  try {
    parsedJson = response?.json;
  } catch {
    parsedJson = null;
  }
  const responseMessage = parsedJson?.error?.message || parsedJson?.message || response?.text;
  if (typeof responseMessage === "string" && responseMessage.trim()) {
    return responseMessage.trim();
  }

  return t("Unknown connection error.");
}

export function showAIErrorNotice(error: unknown): boolean {
  if (!(error instanceof AIUserNoticeError)) {
    return false;
  }

  const now = Date.now();
  const lastShownAt = noticeHistory.get(error.message) ?? 0;
  if (now - lastShownAt < NOTICE_THROTTLE_MS) {
    return true;
  }

  noticeHistory.set(error.message, now);
  new Notice(error.message, error.noticeDuration);
  return true;
}

import { Prec, StateEffect, StateField, type Extension } from "@codemirror/state";
import { Decoration, EditorView, ViewPlugin, type Command, type ViewUpdate, WidgetType, keymap } from "@codemirror/view";
import { t } from "src/translations/helper";
import { buildLocalCompletionContext } from "../editorContext";
import { showAIErrorNotice } from "../errorHandling";
import type { CompletionConfig, IAIService } from "../types";

interface CompletionState {
  pos: number;
  text: string;
  status: "loading" | "ready";
}

const setCompletionEffect = StateEffect.define<CompletionState | null>();
const triggerCompletionEffect = StateEffect.define<void>();

const completionField = StateField.define<CompletionState | null>({
  create: () => null,
  update(value, tr) {
    for (const effect of tr.effects) {
      if (effect.is(setCompletionEffect)) return effect.value;
    }
    if (tr.docChanged) return null;
    if (value && tr.state.selection.main.head !== value.pos) return null;
    return value;
  },
});

class GhostTextWidget extends WidgetType {
  text: string;
  showHint: boolean;

  constructor(text: string, showHint: boolean) {
    super();
    this.text = text;
    this.showHint = showHint;
  }

  eq(other: GhostTextWidget): boolean {
    return this.text === other.text && this.showHint === other.showHint;
  }

  toDOM(): HTMLElement {
    const wrapper = createSpan();
    wrapper.className = "cm-ai-ghost-text";
    wrapper.setAttribute("aria-label", t("AI suggestion"));

    const lines = this.text.split("\n");
    const firstLine = createSpan();
    firstLine.className = "cm-ai-ghost-first-line";
    firstLine.textContent = lines[0];
    wrapper.appendChild(firstLine);

    if (this.showHint) {
      const hint = createSpan();
      hint.className = "cm-ai-ghost-hint";
      hint.textContent = t("Press Tab to accept");
      wrapper.appendChild(hint);
    }

    if (lines.length > 1) {
      const rest = createDiv();
      rest.className = "cm-ai-ghost-rest";
      rest.textContent = lines.slice(1).join("\n");
      wrapper.appendChild(rest);
    }

    return wrapper;
  }

  updateDOM(dom: HTMLElement): boolean {
    const lines = this.text.split("\n");
    const firstLine = dom.querySelector(".cm-ai-ghost-first-line");
    const hint = dom.querySelector<HTMLElement>(".cm-ai-ghost-hint");
    const rest = dom.querySelector<HTMLElement>(".cm-ai-ghost-rest");

    if (firstLine) {
      firstLine.textContent = lines[0];
    }

    if (this.showHint) {
      if (hint) {
        hint.textContent = t("Press Tab to accept");
        hint.setCssStyles({ display: "inline-flex" });
      } else {
        const newHint = createSpan();
        newHint.className = "cm-ai-ghost-hint";
        newHint.textContent = t("Press Tab to accept");
        if (firstLine?.nextSibling) {
          dom.insertBefore(newHint, firstLine.nextSibling);
        } else {
          dom.appendChild(newHint);
        }
      }
    } else if (hint) {
      hint.setCssStyles({ display: "none" });
    }

    if (lines.length > 1) {
      if (rest) {
        rest.textContent = lines.slice(1).join("\n");
        rest.setCssStyles({ display: "block" });
      } else {
        const newRest = createDiv();
        newRest.className = "cm-ai-ghost-rest";
        newRest.textContent = lines.slice(1).join("\n");
        dom.appendChild(newRest);
      }
    } else if (rest) {
      rest.setCssStyles({ display: "none" });
    }

    return true;
  }

  ignoreEvent(): boolean {
    return true;
  }
}

class LoadingWidget extends WidgetType {
  eq(): boolean {
    return true;
  }

  toDOM(): HTMLElement {
    const wrapper = createSpan();
    wrapper.className = "cm-ai-loading cm-ai-loading-pill";
    wrapper.setAttribute("aria-label", t("AI is generating"));

    const visual = createSpan();
    visual.className = "cm-ai-loading-visual";

    const glow = createSpan();
    glow.className = "cm-ai-loading-glow";

    const spinner = createSpan();
    spinner.className = "cm-ai-loading-spinner";

    const label = createSpan();
    label.className = "cm-ai-loading-label";
    label.textContent = t("AI thinking");

    const sheen = createSpan();
    sheen.className = "cm-ai-loading-sheen";
    sheen.setAttribute("aria-hidden", "true");

    visual.appendChild(glow);
    visual.appendChild(spinner);
    wrapper.appendChild(visual);
    wrapper.appendChild(label);
    wrapper.appendChild(sheen);
    return wrapper;
  }

  ignoreEvent(): boolean {
    return true;
  }
}

function createCompletionDecorations(shouldShowHint?: () => boolean) {
  return EditorView.decorations.compute([completionField], (state) => {
    const completion = state.field(completionField);
    if (!completion) {
      return Decoration.none;
    }

    if (completion.status === "loading") {
      return Decoration.set([
        Decoration.widget({
          widget: new LoadingWidget(),
          side: 1,
        }).range(completion.pos),
      ]);
    }

    if (!completion.text) {
      return Decoration.none;
    }

    return Decoration.set([
      Decoration.widget({
        widget: new GhostTextWidget(completion.text, shouldShowHint?.() ?? false),
        side: 1,
      }).range(completion.pos),
    ]);
  });
}

function acceptCompletionInternal(view: EditorView, onAccepted?: () => void): boolean {
  const completion = view.state.field(completionField);
  if (!completion?.text) {
    return false;
  }

  view.dispatch({
    changes: { from: completion.pos, insert: completion.text },
    selection: { anchor: completion.pos + completion.text.length },
    effects: setCompletionEffect.of(null),
  });
  onAccepted?.();
  return true;
}

const dismissCompletion: Command = (view) => {
  if (!view.state.field(completionField)) {
    return false;
  }
  view.dispatch({ effects: setCompletionEffect.of(null) });
  return true;
};

const requestCompletion: Command = (view) => {
  view.dispatch({ effects: triggerCompletionEffect.of(undefined) });
  return true;
};

const completionKeymap = keymap.of([
  { key: "Escape", run: dismissCompletion },
]);

export function inlineCompletion(
  getService: () => IAIService | null,
  getConfig?: () => CompletionConfig,
  shouldShowHint?: () => boolean,
  markHintLearned?: () => void,
): Extension {
  const completionDecorations = createCompletionDecorations(shouldShowHint);
  const tabKeymap = Prec.highest(
    keymap.of([
      { key: "Tab", run: (view) => acceptCompletionInternal(view, markHintLearned) },
    ]),
  );
  const plugin = ViewPlugin.fromClass(
    class {
      private abortController: AbortController | null = null;
      private autoTriggerTimer: number | null = null;
      private view: EditorView;
      private ownerDocument: Document;

      constructor(view: EditorView) {
        this.view = view;
        this.ownerDocument = view.dom.ownerDocument;
        this.ownerDocument.addEventListener("keydown", this.handleDocumentKeydown, true);
      }

      private handleDocumentKeydown = (event: KeyboardEvent): void => {
        if (
          event.defaultPrevented ||
          event.key !== "Tab" ||
          event.shiftKey ||
          event.altKey ||
          event.ctrlKey ||
          event.metaKey ||
          this.view.hasFocus ||
          !this.view.dom.isConnected
        ) {
          return;
        }

        const completion = this.view.state.field(completionField);
        if (!completion?.text || completion.status !== "ready") {
          return;
        }

        const activeElement = this.ownerDocument.activeElement;
        if (activeElement && !this.view.dom.contains(activeElement) && this.isTextInputElement(activeElement)) {
          return;
        }

        event.preventDefault();
        event.stopPropagation();
        acceptCompletionInternal(this.view, markHintLearned);
        this.view.focus();
      };

      private isTextInputElement(element: Element): boolean {
        return !!element.closest("input, textarea, select, [contenteditable='true'], [contenteditable='']");
      }

      update(update: ViewUpdate): void {
        for (const tr of update.transactions) {
          for (const effect of tr.effects) {
            if (effect.is(triggerCompletionEffect)) {
              this.scheduleCompletionStart();
            }
            if (effect.is(setCompletionEffect) && effect.value === null) {
              this.abortController?.abort();
            }
          }
        }

        const config = getConfig?.() ?? { trigger: "manual", delay: 500 };
        if (config.trigger === "auto" && update.docChanged) {
          const inserted = update.state.doc.length >= update.startState.doc.length;
          if (inserted) {
            const pos = update.state.selection.main.head;
            const line = update.state.doc.lineAt(pos);
            const linePrefix = update.state.sliceDoc(line.from, pos);
            if (linePrefix.trim().length >= 2) {
              this.scheduleAutoTrigger(config.delay ?? 500);
            }
          }
        }
      }

      private scheduleAutoTrigger(delay: number): void {
        if (this.autoTriggerTimer) {
          window.clearTimeout(this.autoTriggerTimer);
        }
        this.autoTriggerTimer = window.setTimeout(() => {
          void this.startCompletion();
        }, delay);
      }

      private scheduleCompletionStart(): void {
        void Promise.resolve().then(() => {
          void this.startCompletion();
        });
      }

      private async startCompletion(): Promise<void> {
        this.abortController?.abort();
        this.abortController = new AbortController();
        const signal = this.abortController.signal;

        const service = getService();
        if (!service) {
          return;
        }

        const pos = this.view.state.selection.main.head;
        const { prefix, suffix, context } = buildLocalCompletionContext(this.view, pos);
        let text = "";

        this.view.dispatch({
          effects: setCompletionEffect.of({ pos, text: "", status: "loading" }),
        });

        try {
          for await (const chunk of service.complete({ prefix, suffix, context }, signal)) {
            if (signal.aborted) return;
            text += chunk;
            if (this.view.state.selection.main.head !== pos) {
              this.abortController.abort();
              return;
            }
            this.view.dispatch({ effects: setCompletionEffect.of({ pos, text, status: "ready" }) });
          }

          if (!text) {
            this.view.dispatch({ effects: setCompletionEffect.of(null) });
          }
        } catch (error) {
          if (error instanceof DOMException && error.name === "AbortError") {
            return;
          }
          if (!showAIErrorNotice(error)) {
            console.error("[AI Completion] Error:", error);
          }
          this.view.dispatch({ effects: setCompletionEffect.of(null) });
        }
      }

      destroy(): void {
        this.ownerDocument.removeEventListener("keydown", this.handleDocumentKeydown, true);
        this.abortController?.abort();
        if (this.autoTriggerTimer) {
          window.clearTimeout(this.autoTriggerTimer);
        }
      }
    },
  );

  return [completionField, completionDecorations, tabKeymap, completionKeymap, plugin];
}

export { completionField, setCompletionEffect, triggerCompletionEffect };

import { Prec, StateEffect, StateField, type Extension } from "@codemirror/state";
import { Notice, Platform } from "obsidian";
import { EditorView, ViewPlugin, type Tooltip, type TooltipView, type ViewUpdate, keymap, showTooltip } from "@codemirror/view";
import { t } from "src/translations/helper";
import { normalizeGeneratedFrontmatter } from "../artifactNormalizer";
import { resolveRewriteContext } from "../editorContext";
import { showAIErrorNotice } from "../errorHandling";
import { type IAIService, type RewriteArtifactKind, type RewriteConfig, type RewriteInstruction } from "../types";

interface RewriteStartParams {
  from: number;
  to: number;
  originalText: string;
  instruction: RewriteInstruction;
  customPrompt?: string;
  context?: string;
  artifactKind?: RewriteArtifactKind;
  preferredFrontmatterKeys?: Record<string, string>;
}

interface RewriteOperation {
  phase: "streaming" | "done";
  params: RewriteStartParams;
  result: string;
}

interface RewriteFieldValue {
  operation: RewriteOperation | null;
  resultTooltip: Tooltip | null;
}

const startRewriteEffect = StateEffect.define<RewriteStartParams>();
const updateRewriteResultEffect = StateEffect.define<string>();
const finishRewriteEffect = StateEffect.define<void>();
const cancelRewriteEffect = StateEffect.define<void>();

interface RewritePanelShortcut {
  display: string;
  primaryKey: string;
  fallbackKeys?: readonly string[];
}

function createPlatformMnemonicShortcut(letter: string): RewritePanelShortcut {
  const upper = letter.toUpperCase();
  return Platform.isMacOS
    ? {
      display: formatShortcutLabel(["Ctrl", upper]),
      primaryKey: `Ctrl-${letter.toLowerCase()}`,
    }
    : {
      display: formatShortcutLabel(["Alt", upper]),
      primaryKey: `Alt-${letter.toLowerCase()}`,
    };
}

const REWRITE_PANEL_SHORTCUTS = {
  close: {
    ...createPlatformMnemonicShortcut("d"),
    fallbackKeys: ["Escape"],
  },
  replace: {
    ...createPlatformMnemonicShortcut("r"),
    fallbackKeys: ["Mod-Enter"],
  },
  insertBelow: {
    ...createPlatformMnemonicShortcut("i"),
    fallbackKeys: ["Mod-Shift-Enter"],
  },
  copy: createPlatformMnemonicShortcut("c"),
  retry: createPlatformMnemonicShortcut("t"),
} as const satisfies Record<string, RewritePanelShortcut>;

function dispatchRewrite(view: EditorView, instruction: RewriteInstruction, customPrompt?: string): void {
  const { from, to } = view.state.selection.main;
  if (from === to) return;
  const rewriteContext = resolveRewriteContext(view, from, to);
  view.dispatch({
    effects: startRewriteEffect.of({
      from: rewriteContext.from,
      to: rewriteContext.to,
      originalText: rewriteContext.selectedText,
      instruction,
      customPrompt,
      context: rewriteContext.context,
    }),
  });
}

function formatShortcutLabel(parts: Array<"Mod" | "Shift" | "Alt" | "Ctrl" | string>): string {
  const displayParts = parts.map((part) => {
    if (part === "Mod") {
      return Platform.isMacOS ? "⌘" : "Ctrl";
    }
    if (part === "Shift") {
      return Platform.isMacOS ? "⇧" : "Shift";
    }
    if (part === "Alt") {
      return Platform.isMacOS ? "⌥" : "Alt";
    }
    if (part === "Ctrl") {
      return Platform.isMacOS ? "⌃" : "Ctrl";
    }
    return part;
  });

  return displayParts.join("+");
}

function getRewriteOperation(
  view: EditorView,
  rewriteField: StateField<RewriteFieldValue>,
  requireDone = false,
): RewriteOperation | null {
  const state = view.state.field(rewriteField, false);
  const operation = state?.operation ?? null;
  if (!operation) {
    return null;
  }

  if (requireDone && operation.phase !== "done") {
    return null;
  }

  return operation;
}

function isFileArtifactOperation(operation: RewriteOperation | null): boolean {
  return operation?.params.artifactKind === "base" || operation?.params.artifactKind === "canvas";
}

function isFrontmatterOperation(operation: RewriteOperation | null): boolean {
  return operation?.params.artifactKind === "frontmatter";
}

function normalizeFrontmatterOperationResult(operation: RewriteOperation): string {
  return normalizeGeneratedFrontmatter(
    operation.result,
    operation.params.preferredFrontmatterKeys,
  );
}

function getRewritePreviewText(operation: RewriteOperation): string {
  if (!isFrontmatterOperation(operation) || !operation.result.trim()) {
    return operation.result || "";
  }

  try {
    return normalizeFrontmatterOperationResult(operation);
  } catch {
    return operation.result || "";
  }
}

function getRewriteCopyText(operation: RewriteOperation): string {
  return isFrontmatterOperation(operation)
    ? normalizeFrontmatterOperationResult(operation)
    : operation.result;
}

function dismissRewritePanel(view: EditorView, rewriteField: StateField<RewriteFieldValue>): boolean {
  if (!getRewriteOperation(view, rewriteField)) {
    return false;
  }

  view.dispatch({ effects: cancelRewriteEffect.of(undefined) });
  view.focus();
  return true;
}

async function copyRewriteResultToClipboard(
  view: EditorView,
  rewriteField: StateField<RewriteFieldValue>,
): Promise<boolean> {
  const operation = getRewriteOperation(view, rewriteField, true);
  if (!operation) {
    return false;
  }

  const result = getRewriteCopyText(operation);
  if (!result) {
    return false;
  }

  try {
    await navigator.clipboard.writeText(result);
    return true;
  } catch (error) {
    console.error("[AI Rewrite] Failed to copy result:", error);
    new Notice(error instanceof Error && error.message ? error.message : t("Copy to Clipboard"));
    return false;
  }
}

async function handleGeneratedArtifact(
  view: EditorView,
  rewriteField: StateField<RewriteFieldValue>,
  getConfig: () => {
    createGeneratedArtifact?: RewriteConfig["createGeneratedArtifact"];
  },
  mode: "create" | "embed",
): Promise<boolean> {
  const operation = getRewriteOperation(view, rewriteField, true);
  if (!operation?.params.artifactKind) {
    return false;
  }

  const artifactCreator = getConfig().createGeneratedArtifact;
  if (!artifactCreator) {
    new Notice(t("AI file creation is unavailable."));
    return true;
  }

  try {
    const artifact = await artifactCreator({
      kind: operation.params.artifactKind,
      content: operation.result,
      sourceText: operation.params.originalText,
    });

    view.dispatch({ effects: cancelRewriteEffect.of(undefined) });

    if (mode === "embed") {
      const insertText = operation.params.from === operation.params.to
        ? artifact.embedSyntax
        : `\n\n${artifact.embedSyntax}`;
      const insertFrom = operation.params.to;

      view.dispatch({
        changes: { from: insertFrom, insert: insertText },
        selection: { anchor: insertFrom + insertText.length },
      });
    }

    view.focus();
    return true;
  } catch (error) {
    const message = error instanceof Error && error.message ? error.message : t("Failed to create AI file.");
    new Notice(message);
    console.error("[AI Artifact] Failed to create file:", error);
    return true;
  }
}

function applyFrontmatterResult(
  view: EditorView,
  rewriteField: StateField<RewriteFieldValue>,
): boolean {
  const operation = getRewriteOperation(view, rewriteField, true);
  if (!operation) {
    return false;
  }

  try {
    const normalized = normalizeFrontmatterOperationResult(operation);
    view.dispatch({ effects: cancelRewriteEffect.of(undefined) });
    view.dispatch({
      changes: { from: operation.params.from, to: operation.params.to, insert: normalized },
      selection: { anchor: normalized.length },
    });
    view.focus();
    return true;
  } catch (error) {
    const message = error instanceof Error && error.message ? error.message : t("Failed to apply frontmatter.");
    new Notice(message);
    return true;
  }
}

async function applyRewriteResult(
  view: EditorView,
  rewriteField: StateField<RewriteFieldValue>,
  getConfig: () => {
    createGeneratedArtifact?: RewriteConfig["createGeneratedArtifact"];
  },
  mode: "replace" | "insert-below",
): Promise<boolean> {
  const operation = getRewriteOperation(view, rewriteField, true);
  if (!operation) {
    return false;
  }

  if (isFileArtifactOperation(operation)) {
    return handleGeneratedArtifact(view, rewriteField, getConfig, mode === "replace" ? "create" : "embed");
  }

  if (isFrontmatterOperation(operation)) {
    return applyFrontmatterResult(view, rewriteField);
  }

  if (mode === "replace") {
    const { from, to } = operation.params;
    const result = operation.result;
    view.dispatch({ effects: cancelRewriteEffect.of(undefined) });
    view.dispatch({
      changes: { from, to, insert: result },
      selection: { anchor: from + result.length },
    });
    view.focus();
    return true;
  }

  const { to } = operation.params;
  const result = operation.result;
  view.dispatch({ effects: cancelRewriteEffect.of(undefined) });
  view.dispatch({
    changes: { from: to, insert: `\n\n${result}` },
    selection: { anchor: to + result.length + 2 },
  });
  view.focus();
  return true;
}

function retryRewrite(view: EditorView, rewriteField: StateField<RewriteFieldValue>): boolean {
  const operation = getRewriteOperation(view, rewriteField, true);
  if (!operation) {
    return false;
  }

  view.dispatch({ effects: startRewriteEffect.of(operation.params) });
  return true;
}

function setActionButtonLabel(btn: HTMLButtonElement, label: string, shortcut?: string): void {
  btn.replaceChildren();

  const labelEl = createSpan();
  labelEl.className = "cm-ai-btn-label";
  labelEl.textContent = label;
  btn.appendChild(labelEl);

  if (shortcut) {
    const shortcutEl = createSpan();
    shortcutEl.className = "cm-ai-btn-shortcut";
    shortcutEl.textContent = shortcut;
    btn.appendChild(shortcutEl);
    btn.title = `${label} (${shortcut})`;
  } else {
    btn.removeAttribute("title");
  }
}

function createResultPanelTooltipView(
  view: EditorView,
  rewriteField: StateField<RewriteFieldValue>,
  getConfig: () => {
    createGeneratedArtifact?: RewriteConfig["createGeneratedArtifact"];
  },
): TooltipView {
  const dom = createDiv();
  dom.className = "cm-ai-result-panel";
  dom.dataset.phase = "streaming";
  let copyResetTimer: number | null = null;

  dom.addEventListener("mousedown", (event) => {
    if (!(event.target as HTMLElement).closest(".cm-ai-result-content")) {
      event.preventDefault();
    }
  });

  const headerRow = createDiv();
  headerRow.className = "cm-ai-result-header-row";

  const header = createDiv();
  header.className = "cm-ai-result-header";
  header.textContent = t("AI is writing...");

  const closeBtn = createEl("button");
  closeBtn.type = "button";
  closeBtn.className = "cm-ai-result-close";
  closeBtn.textContent = "×";
  closeBtn.setAttribute("aria-label", t("Close"));
  closeBtn.title = `${t("Close")} (${REWRITE_PANEL_SHORTCUTS.close.display} / Esc)`;
  closeBtn.addEventListener("click", () => {
    resetCopyButtonLabel();
    dismissRewritePanel(view, rewriteField);
  });

  headerRow.append(header, closeBtn);
  dom.appendChild(headerRow);

  const content = createDiv();
  content.className = "cm-ai-result-content";
  dom.appendChild(content);

  const actionsBar = createDiv();
  actionsBar.className = "cm-ai-result-actions";
  actionsBar.setCssStyles({ display: "none" });

  function resetCopyButtonLabel(): void {
    if (copyResetTimer !== null) {
      window.clearTimeout(copyResetTimer);
      copyResetTimer = null;
    }
    setActionButtonLabel(copyBtn, t("Copy to Clipboard"), REWRITE_PANEL_SHORTCUTS.copy.display);
  }

  const replaceBtn = createActionButton(
    t("Replace"),
    "cm-ai-btn-primary",
    () => {
      void applyRewriteResult(view, rewriteField, getConfig, "replace");
    },
    REWRITE_PANEL_SHORTCUTS.replace.display,
  );

  const insertBtn = createActionButton(
    t("Insert below"),
    "cm-ai-btn-secondary",
    () => {
      void applyRewriteResult(view, rewriteField, getConfig, "insert-below");
    },
    REWRITE_PANEL_SHORTCUTS.insertBelow.display,
  );

  const copyBtn = createActionButton(
    t("Copy to Clipboard"),
    "cm-ai-btn-secondary",
    () => {
      void copyRewriteResultToClipboard(view, rewriteField).then((copied) => {
        if (!copied) {
          return;
        }
        if (copyResetTimer !== null) {
          window.clearTimeout(copyResetTimer);
        }
        setActionButtonLabel(copyBtn, t("Copied!"), REWRITE_PANEL_SHORTCUTS.copy.display);
        copyResetTimer = window.setTimeout(() => {
          copyResetTimer = null;
          setActionButtonLabel(copyBtn, t("Copy to Clipboard"), REWRITE_PANEL_SHORTCUTS.copy.display);
        }, 1500);
      });
    },
    REWRITE_PANEL_SHORTCUTS.copy.display,
  );

  const retryBtn = createActionButton(t("Try again"), "cm-ai-btn-secondary", () => {
    resetCopyButtonLabel();
    retryRewrite(view, rewriteField);
  }, REWRITE_PANEL_SHORTCUTS.retry.display);

  actionsBar.append(replaceBtn, insertBtn, copyBtn, retryBtn);
  dom.appendChild(actionsBar);

  return {
    dom,
    update(update: ViewUpdate) {
      const state = update.state.field(rewriteField);
      if (!state.operation) {
        dom.setCssStyles({ display: "none" });
        dom.dataset.phase = "idle";
        return;
      }

      dom.setCssStyles({ display: "" });
      dom.dataset.phase = state.operation.phase;
      content.textContent = getRewritePreviewText(state.operation);
      if (isFileArtifactOperation(state.operation)) {
        header.textContent = t("AI file suggestion");
        setActionButtonLabel(replaceBtn, t("Create"), REWRITE_PANEL_SHORTCUTS.replace.display);
        setActionButtonLabel(insertBtn, t("Create & Embed"), REWRITE_PANEL_SHORTCUTS.insertBelow.display);
        insertBtn.setCssStyles({ display: "" });
      } else if (isFrontmatterOperation(state.operation)) {
        header.textContent = t("AI frontmatter suggestion");
        setActionButtonLabel(
          replaceBtn,
          state.operation.params.from === state.operation.params.to
            ? t("Insert frontmatter")
            : t("Replace frontmatter"),
          REWRITE_PANEL_SHORTCUTS.replace.display,
        );
        insertBtn.setCssStyles({ display: "none" });
      } else {
        setActionButtonLabel(
          replaceBtn,
          state.operation.params.from === state.operation.params.to
            ? t("Insert at cursor")
            : t("Replace"),
          REWRITE_PANEL_SHORTCUTS.replace.display,
        );
        setActionButtonLabel(insertBtn, t("Insert below"), REWRITE_PANEL_SHORTCUTS.insertBelow.display);
        insertBtn.setCssStyles({ display: "" });
      }

      if (state.operation.phase === "done") {
        if (state.operation.params.artifactKind !== "base" && state.operation.params.artifactKind !== "canvas") {
          if (state.operation.params.artifactKind !== "frontmatter") {
            header.textContent = t("AI suggestion");
          }
        }
        copyBtn.setCssStyles({ display: "" });
        actionsBar.setCssStyles({ display: "flex" });
      } else {
        resetCopyButtonLabel();
        header.textContent = t("AI is writing...");
        actionsBar.setCssStyles({ display: "none" });
      }
    },
    destroy() {
      if (copyResetTimer !== null) {
        window.clearTimeout(copyResetTimer);
      }
    },
  };
}

function createActionButton(
  label: string,
  className: string,
  onClick: () => void,
  shortcut?: string,
): HTMLButtonElement {
  const btn = createEl("button");
  btn.className = `cm-ai-btn ${className}`;
  setActionButtonLabel(btn, label, shortcut);
  btn.addEventListener("click", onClick);
  return btn;
}

export function selectionRewrite(
  getService: () => IAIService | null,
  getConfig?: () => RewriteConfig,
): Extension {
    const resolveConfig = () => {
    const config = getConfig?.() ?? {};
    return {
      createGeneratedArtifact: config.createGeneratedArtifact,
    };
  };

  const rewriteField = StateField.define<RewriteFieldValue>({
    create: () => ({
      operation: null,
      resultTooltip: null,
    }),
    update(prev, tr) {      let operation = prev.operation;

      for (const effect of tr.effects) {
        if (effect.is(startRewriteEffect)) {
          operation = { phase: "streaming", params: effect.value, result: "" };
        }
        if (effect.is(updateRewriteResultEffect) && operation) {
          operation = { ...operation, result: effect.value };
        }
        if (effect.is(finishRewriteEffect) && operation) {
          operation = { ...operation, phase: "done" };
        }
        if (effect.is(cancelRewriteEffect)) {
          operation = null;
        }
      }

      if (tr.docChanged && operation) {
        operation = {
          ...operation,
          params: {
            ...operation.params,
            from: tr.changes.mapPos(operation.params.from),
            to: tr.changes.mapPos(operation.params.to),
          },
        };
      }

      let resultTooltip: Tooltip | null = null;

      if (operation) {
        if (prev.resultTooltip && prev.resultTooltip.pos === operation.params.from) {
          resultTooltip = prev.resultTooltip;
        } else {
          resultTooltip = {
            pos: operation.params.from,
            above: false,
            create: (view) => createResultPanelTooltipView(view, rewriteField, resolveConfig),
          };
        }
      }

      return {
        operation,
        resultTooltip,
      };
    },
    provide: (field) => showTooltip.from(field, (value) => value.resultTooltip ?? null),
  });

  const rewritePlugin = ViewPlugin.fromClass(
    class {
      private abortController: AbortController | null = null;
      private view: EditorView;

      constructor(view: EditorView) {
        this.view = view;
      }

      update(update: ViewUpdate): void {
        for (const tr of update.transactions) {
          for (const effect of tr.effects) {
            if (effect.is(startRewriteEffect)) {
              void this.startStreaming(effect.value);
            }
            if (effect.is(cancelRewriteEffect)) {
              this.abortController?.abort();
            }
          }
        }
      }

      private async startStreaming(params: RewriteStartParams): Promise<void> {
        this.abortController?.abort();
        this.abortController = new AbortController();
        const signal = this.abortController.signal;

        const service = getService();
        if (!service) {
          return;
        }

        let result = "";
        try {
          for await (const chunk of service.rewrite({
            selectedText: params.originalText,
            instruction: params.instruction,
            customPrompt: params.customPrompt,
            context: params.context,
            artifactKind: params.artifactKind,
          }, signal)) {
            if (signal.aborted) return;
            result += chunk;
            this.view.dispatch({ effects: updateRewriteResultEffect.of(result) });
          }
          this.view.dispatch({ effects: finishRewriteEffect.of(undefined) });
        } catch (error) {
          if (error instanceof DOMException && error.name === "AbortError") {
            return;
          }
          if (!showAIErrorNotice(error)) {
            console.error("[AI Rewrite] Error:", error);
          }
          this.view.dispatch({ effects: cancelRewriteEffect.of(undefined) });
        }
      }

      destroy(): void {
        this.abortController?.abort();
      }
    },
  );

  const rewriteKeymap = Prec.highest(
    keymap.of([
      {
        key: REWRITE_PANEL_SHORTCUTS.close.primaryKey,
        run: (view) => dismissRewritePanel(view, rewriteField),
      },
      {
        key: "Escape",
        run: (view) => dismissRewritePanel(view, rewriteField),
      },
      {
        key: REWRITE_PANEL_SHORTCUTS.replace.primaryKey,
        run: (view) => {
          if (!getRewriteOperation(view, rewriteField, true)) {
            return false;
          }
          void applyRewriteResult(view, rewriteField, resolveConfig, "replace");
          return true;
        },
      },
      {
        key: "Mod-Enter",
        run: (view) => {
          if (!getRewriteOperation(view, rewriteField, true)) {
            return false;
          }
          void applyRewriteResult(view, rewriteField, resolveConfig, "replace");
          return true;
        },
      },
      {
        key: REWRITE_PANEL_SHORTCUTS.insertBelow.primaryKey,
        run: (view) => {
          if (!getRewriteOperation(view, rewriteField, true)) {
            return false;
          }
          void applyRewriteResult(view, rewriteField, resolveConfig, "insert-below");
          return true;
        },
      },
      {
        key: "Mod-Shift-Enter",
        run: (view) => {
          if (!getRewriteOperation(view, rewriteField, true)) {
            return false;
          }
          void applyRewriteResult(view, rewriteField, resolveConfig, "insert-below");
          return true;
        },
      },
      {
        key: REWRITE_PANEL_SHORTCUTS.copy.primaryKey,
        run: (view) => {
          if (!getRewriteOperation(view, rewriteField, true)) {
            return false;
          }
          void copyRewriteResultToClipboard(view, rewriteField).then((copied) => {
            if (copied) {
              new Notice(t("Copied!"));
            }
          });
          return true;
        },
      },
      {
        key: "Mod-Shift-C",
        run: (view) => {
          if (!getRewriteOperation(view, rewriteField, true)) {
            return false;
          }
          void copyRewriteResultToClipboard(view, rewriteField).then((copied) => {
            if (copied) {
              new Notice(t("Copied!"));
            }
          });
          return true;
        },
      },
      {
        key: REWRITE_PANEL_SHORTCUTS.retry.primaryKey,
        run: (view) => retryRewrite(view, rewriteField),
      },
      {
        key: "Mod-Shift-R",
        run: (view) => retryRewrite(view, rewriteField),
      },
      {
        key: "Ctrl-Shift-Space",
        run: (view) => {
          const { from, to } = view.state.selection.main;
          if (from === to) return false;
          dispatchRewrite(view, "improve");
          return true;
        },
      },
    ]),
  );

  return [rewriteField, rewritePlugin, rewriteKeymap];
}

