    .setValue(toDisplayText(this.prefix)) // 显示时转换特殊字符为占位符
    .onChange(value => {
      this.prefix = toStoredText(value); // 存储时转换占位符为特殊字符

      // 获取前缀的镜像文字作为后缀
      const mirrorText = this.getMirrorText(value);

      // 只有在找到有效的镜像文字时才更新后缀
      if (mirrorText) {
        this.suffix = toStoredText(mirrorText);
        // 更新后缀输入框的值
