      );

    // 创建图标选择设置
    const iconSetting = new Setting(contentEl)
      .setName(t('Icon'))
      .setDesc(t('Command icon (click to select)'));

    // 添加图标预览
    this.iconDisplay = iconSetting.controlEl.createDiv('editingToolbarSettingsIcon');
    if (this.icon) {
      try {
        setIcon(this.iconDisplay, this.icon);
      } catch (e) {
        this.iconDisplay.setText(this.icon);
      }
    }



    // 添加选择图标按钮
    iconSetting.addButton(button => button
      .setButtonText(t('Choose Icon'))
      .onClick(() => {
        const command = {
          id: this.commandId,
          name: this.commandName,
          icon: this.icon
        }

        new ChooseFromIconList(
          this.plugin,
          command,
          false,
          (selectedIcon) => {
            this.icon = selectedIcon;
            // 更新图标预览
            this.iconDisplay.empty();
            if (this.icon) {
              try {
                setIcon(this.iconDisplay, this.icon);
              } catch (e) {
                this.iconDisplay.setText(this.icon);
              }
            }
            // 更新输入框
            const iconInput = iconSetting.controlEl.querySelector('input');
            if (iconInput) {
              iconInput.value = this.icon;
            }
          }
        ).open();
      })
    );



    // 添加保存和取消按钮
    new Setting(contentEl)
      .addButton(button => button
        .setButtonText(t('Save'))
        .setCta()
        .onClick(() => {
          // 验证必填字段
          if (!this.commandId || !this.commandName) {
            new Notice(t('Command ID and command name cannot be empty'));
            return;
          }

          // 验证ID格式
          if (this.commandId.includes(' ')) {
            new Notice(t('Command ID cannot contain spaces'));
            return;
          }
          const commandId = this.commandIndex === null ? `custom-${this.commandId}` : this.commandId;
          // 检查ID是否已存在（编辑时除外）
          if (this.commandIndex === null) {

            const existingIndex = this.plugin.settings.customCommands.findIndex(
              cmd => cmd.id === commandId
            );
            if (existingIndex >= 0) {
              new Notice(t("The command") + this.commandId + t("already exists"), 8000);
              return;
            }
          }

          // 创建命令对象
          const command = {
            id: commandId,
            name: this.commandName,
            prefix: this.prefix,
            suffix: this.suffix,
            char: this.char,
            line: this.line,
            islinehead: this.islinehead,
            icon: this.icon
          };

          // 如果是编辑现有命令且图标发生变化
          if (this.commandIndex !== null) {
            const oldCommand = this.plugin.settings.customCommands[this.commandIndex];
            const oldIcon = oldCommand.icon;

            if (oldIcon !== this.icon) {
              // 更新所有配置中的相关命令图标
              const customCommandId = `editing-toolbar:${commandId}`;

              // 更新 menuCommands
              this.updateCommandIcon(this.plugin.settings.menuCommands, customCommandId);

              // 如果启用了多配置，更新其他配置
              if (this.plugin.settings.enableMultipleConfig) {
                this.updateCommandIcon(this.plugin.settings.followingCommands, customCommandId);
                this.updateCommandIcon(this.plugin.settings.topCommands, customCommandId);
                this.updateCommandIcon(this.plugin.settings.fixedCommands, customCommandId);

                if (this.plugin.settings.isLoadOnMobile) {
                  this.updateCommandIcon(this.plugin.settings.mobileCommands, customCommandId);
                }
              }
            }

            // 更新自定义命令
            this.plugin.settings.customCommands[this.commandIndex] = command;
          } else {
            // 添加新命令
            this.plugin.settings.customCommands.push(command);
          }

          // 保存设置并关闭模态框
          void this.plugin.saveSettings().then(() => {
            this.close();
            window.setTimeout(() => {
              dispatchEvent(new Event("editingToolbar-NewCommand"));
              this.plugin.reloadCustomCommands();
            }, 100);
          });
        })
      )
      .addButton(button => button
        .setButtonText(t('Cancel'))
        .onClick(() => this.close())
      );

    // 设置光标聚焦逻辑
    window.setTimeout(() => {
      if (this.commandIndex)
        this.commandIdInput.inputEl.focus();
      else
        this.commandNameInput.inputEl.focus();
    }, 10);
  }

  // 添加更新命令图标的辅助方法
  private updateCommandIcon(commands: any[], commandId: string) {
    if (!commands) return;

    commands.forEach(cmd => {
      if (cmd.id === commandId) {
        cmd.icon = this.icon;
      }
      // 检查子菜单
      if (cmd.SubmenuCommands) {
        this.updateCommandIcon(cmd.SubmenuCommands, commandId);
      }
    });
  }

  onClose() {
    const { contentEl } = this;
    contentEl.empty();
  }

  // 添加获取镜像文字的辅助方法
  private getMirrorText(text: string): string {
    // 常见的Markdown成对标记
    const commonPairs: { [key: string]: string } = {
      '**': '**',    // 粗体
      '*': '*',      // 斜体
      '__': '__',    // 粗体
      '_': '_',      // 斜体
      '~~': '~~',    // 删除线
      '`': '`',      // 行内代码
      '```': '```',  // 代码块
      '$': '$',      // 行内LaTeX
      '$$': '$$',    // LaTeX块
      '(': ')',      // 括号
      '[': ']',      // 方括号
      '{': '}',      // 花括号
      '<': '>',       // 尖括号
      '==': '==',
      '*==': '==*',
      '**==': '==**',
      '***==': '==***',

    };

    // 如果文本为空，返回空字符串
    if (!text) return '';

    // 检查是否是常见的Markdown标记
    if (text in commonPairs) {
      return commonPairs[text];
    }

    // 处理HTML标签
    const htmlTagMatch = text.match(/^<(\w+)([^>]*)>$/);
    if (htmlTagMatch) {
      return `</${htmlTagMatch[1]}>`;
    }

    // 如果没有找到对应的镜像，返回空字符串
    return '';
  }
}

import { App, Modal, Setting, Notice, setIcon, ToggleComponent } from "obsidian";
import editingToolbarPlugin from "src/plugin/main";
import { t } from 'src/translations/helper';

interface DeployOption {
  id: string;
  name: string;
  enabled: boolean;
  toggle?: ToggleComponent;
}

export class DeployCommandModal extends Modal {
    private deployOptions: DeployOption[] = [];
    private command: any;
    private plugin: editingToolbarPlugin;


    constructor(app: App, plugin: editingToolbarPlugin, command: any) {
      super(app);
      this.plugin = plugin;
      this.command = command;
      this.deployOptions = [
        { id: 'following', name: t('Following Style'), enabled: true },
        { id: 'top', name: t('Top Style'), enabled: true },
        { id: 'fixed', name: t('Fixed Style'), enabled: true },
      ];
      if (this.plugin.settings.isLoadOnMobile) {
        this.deployOptions.push({ id: 'mobile', name: t('Mobile Style'), enabled: true });
      }
    }

    onOpen() {
      const { contentEl } = this;
      contentEl.empty();

      contentEl.createEl('h3', { text: t('Deploy command to configurations') });

      const allContainer = contentEl.createDiv('deploy-option');


      const optionsContainer = contentEl.createDiv('deploy-options');
      this.deployOptions.forEach(option => {
        const setting = new Setting(optionsContainer)
          .setName(option.name)
          .addToggle(toggle => {
            return toggle
              .setValue(option.enabled)
              .onChange(value => {
                option.enabled = value;
              });
          });
        setting.settingEl.addClass('deploy-option');
      });

      const buttonContainer = contentEl.createDiv('deploy-buttons');
      new Setting(buttonContainer)
        .addButton(button => button
          .setButtonText(t('Deploy'))
          .setCta()
          .onClick(() => {
            this.deployCommand();
            this.close();
          }))
        .addButton(button => button
          .setButtonText(t('Cancel'))
          .onClick(() => {
            this.close();
          }));
    }



    private deployCommand() {
      // 创建工具栏命令对象
      const toolbarCommand = {
        id: `editing-toolbar:${this.command.id}`,
        name: this.command.name,
        icon: this.command.icon || 'obsidian-new'
      };

      // 检查默认配置中是否已存在该命令
      const existsInDefault = this.plugin.settings.menuCommands.some(
        cmd => cmd.id === toolbarCommand.id
      );

      // 如果默认配置中不存在，则添加
      if (!existsInDefault) {
        this.plugin.settings.menuCommands.push({...toolbarCommand});
      }

      let deployedCount = 0;

      // 部署到选中的配置
      this.deployOptions.forEach(option => {
        if (option.enabled) {
          let targetCommands: any[] | undefined;

          switch (option.id) {
            case 'mobile':
              targetCommands = this.plugin.settings.mobileCommands;
              break;
            case 'following':
              targetCommands = this.plugin.settings.followingCommands;
              break;
            case 'top':
              targetCommands = this.plugin.settings.topCommands;
              break;
            case 'fixed':
              targetCommands = this.plugin.settings.fixedCommands;
              break;
          }

          if (targetCommands && !targetCommands.some(cmd => cmd.id === toolbarCommand.id)) {
            targetCommands.push({...toolbarCommand});
            deployedCount++;
          }
        }
      });

      // 保存设置
      void this.plugin.saveSettings().then(() => {
        let message: string;

        if (deployedCount > 0) {
          const deployedConfigs = this.deployOptions
            .filter(opt => opt.enabled)
            .map(opt => opt.name)
            .join(', ');

          message = t('Command deployed to: ') + deployedConfigs;

        } else {
          message = t('Command already exists in selected configurations');
        }

        new Notice(message);
        // 触发工具栏更新
        dispatchEvent(new Event("editingToolbar-NewCommand"));
        this.plugin.reloadCustomCommands();
      });
    }
}

