                });
              };

              const addSubmenu = (
                title: string,
                icon: string,
                actions: Array<{
                  title: string;
                  icon: string;
                  hotkey?: string;
                  commandIdForLabel?: string;
                  action: () => Promise<boolean | void> | boolean | void;
