        this.prepareCalloutOptions();
        // 如果有选中的文本,则作为初始内容
        const editor = this.plugin.commandsManager.getActiveEditor();
        if (editor) {
            const selectedText = editor.getSelection();
            if (selectedText) {
                this.content = selectedText;
            }
        }
        if (!this.allCalloutOptions.find(opt => opt.type === this.type)) {
            this.type = this.allCalloutOptions.length > 0 ? this.allCalloutOptions[0].type : "note";
        }
    }
    private prepareCalloutOptions() {
        // 1. Add built-in types
        this.builtInCalloutTypes.forEach(bt => {
            this.allCalloutOptions.push({
                type: bt.type,
                label: bt.label,
                icon: bt.icon, // IconName
                color: bt.color,
                isAdmonition: false
            });
            // Add aliases for built-in types
            bt.aliases.forEach(alias => {
                this.allCalloutOptions.push({
                    type: alias,
                    label: `${bt.label} (${alias})`,
                    icon: bt.icon,
                    color: bt.color,
                    isAdmonition: false
                });
            });
        });
        // 2. Add types from Admonition plugin
        if (this.plugin.admonitionDefinitions) {
            const admonitionTypes = Object.values(this.plugin.admonitionDefinitions);
            if (admonitionTypes.length > 0) {
                admonitionTypes.forEach(ad => {
                    // Avoid duplicates if a built-in type has the same name
                    if (!this.allCalloutOptions.some(opt => opt.type === ad.type)) {
                        this.allCalloutOptions.push({
                            type: ad.type,
                            label: ad.title || ad.type.charAt(0).toUpperCase() + ad.type.slice(1), // Use admonition title or formatted type
                            icon: ad.icon, // AdmonitionIconDefinition
                            color: `rgb(${ad.color})`, // Admonition color is usually "R,G,B"
                            isAdmonition: true,
                            sourcePlugin: "Admonition"
                        });
                    }
                });
            }
        }

    }

    onOpen() {
        void this.display();
    }

    private async display() {
        const { contentEl } = this;
        contentEl.empty();

        // 添加键盘事件监听器到整个模态框
        contentEl.addEventListener('keydown', (event) => {
            // 检测 Ctrl+Enter 或 Command+Enter
            if (event.key === 'Enter' && (event.ctrlKey || event.metaKey)) {
                event.preventDefault();
                if (this.insertButton) {
                    this.insertButton.click();
                }
            }
        });

        const typeContainer = contentEl.createDiv("callout-type-container");
        // Ensure iconContainerEl is created fresh each time display is called
        this.iconContainerEl = typeContainer.createDiv("callout-icon-container");
        new Setting(typeContainer)
            .setName(t("Callout Type"))
            .addDropdown((dropdown: DropdownComponent) => {
                // Populate built-in types first
                const builtIns = this.allCalloutOptions.filter(opt => !opt.isAdmonition);

                // Add admonition types, with a separator if there are both kinds
                const admonitions = this.allCalloutOptions.filter(opt => opt.isAdmonition);
                if (builtIns.length > 0 && admonitions.length > 0) {
                    // Add a visual separator. DropdownComponent doesn't directly support <optgroup> or disabled options as separators.
                    // A common workaround is an option with a distinct value and visual cue.
                    dropdown.addOption("---separator---", "---- Admonitions ----");
                    const separatorOption = dropdown.selectEl.options[dropdown.selectEl.options.length - 1];
                    if (separatorOption) {
                        separatorOption.disabled = true;
                    }
                }
                admonitions.forEach(opt => {
                    dropdown.addOption(opt.type, `${opt.label} (Admonition)`);
                });
                dropdown.addOption("---separator---", "---- Default ----");
                builtIns.forEach(opt => {
                    dropdown.addOption(opt.type, opt.label);
                });
                // Ensure the current `this.type` is valid and selected
                if (!this.allCalloutOptions.some(opt => opt.type === this.type)) {
                    this.type = this.allCalloutOptions.length > 0 ? this.allCalloutOptions[0].type : "note";
                }
                dropdown.setValue(this.type);
                dropdown.onChange((value) => {
                    if (value === "---separator---") {
                        // If the separator is somehow selected, revert to the previous valid type
                        dropdown.setValue(this.type);
                        return;
                    }
                    this.type = value;
                    this.updateIconAndColor(this.iconContainerEl, value); // Pass the iconContainerEl
                });
            });
        this.updateIconAndColor(this.iconContainerEl, this.type); // Initial icon update

        // 标题输入
        const titleSetting = new Setting(contentEl)
            .setName(t("Title"))
            .setDesc(t("Optional, leave blank for default title"))
            .addText((text) => {
                text.setPlaceholder(t("Input title"))
                    .setValue(this.title)
                    .onChange((value) => {
                        this.title = value;
                    });
            });

        // 折叠选项
        new Setting(contentEl)
            .setName(t("Collapse State"))
            .addDropdown((dropdown) => {
                dropdown
                    .addOption("none", t("Default"))
                    .addOption("open", t("Open"))
                    .addOption("closed", t("Closed"))
                    .setValue(this.collapse)
                    .onChange((value: "none" | "open" | "closed") => {
                        this.collapse = value;
                    });
            });

        // 内容输入
        const contentSetting = new Setting(contentEl)
            .setName(t("Content"))
            .addTextArea((text) => {
                text.setPlaceholder(t("Input content"))
                    .setValue(this.content)
                    .onChange((value) => {
                        this.content = value;
                    });
                text.inputEl.rows = 5;
                text.inputEl.cols = 40;
                this.contentTextArea = text.inputEl;
            });

        // 添加快捷键提示
        const shortcutHint = contentEl.createDiv("shortcut-hint");
        shortcutHint.setText(`${Platform.isMacOS ? "⌘" : "Ctrl"} + Enter ${t("to insert")}`);
        shortcutHint.setCssStyles({ textAlign: "right" });
        shortcutHint.setCssStyles({ fontSize: "0.8em" });
        shortcutHint.setCssStyles({ opacity: "0.7" });
        shortcutHint.setCssStyles({ marginTop: "5px" });

        // 按钮
        new Setting(contentEl)
            .addButton((btn) => {
                btn
                    .setButtonText(t("Insert"))
                    .setCta()
                    .onClick(() => {
                        this.insertCallout();
                        this.close();
                    });
                this.insertButton = btn.buttonEl;
                return btn;
            })
            .addButton((btn) => {
                btn.setButtonText(t("Cancel"))
                    .setTooltip(t("Cancel"))
                    .onClick(() => this.close());
                return btn;
            });

        // 自动聚焦到内容文本框
        window.setTimeout(() => {
            if (this.contentTextArea) {
                this.contentTextArea.focus();
            }
        }, 10);
    }
    private updateIconAndColor(iconContainer: HTMLElement, typeKey: string) {
        if (!iconContainer) return; // Guard against null iconContainer
        const typeInfo = this.allCalloutOptions.find(t => t.type === typeKey);
        iconContainer.empty(); // Clear previous icon
        if (typeInfo) {
            if (typeInfo.isAdmonition) {
                const adIcon = typeInfo.icon as AdmonitionIconDefinition;
                if (adIcon.type === 'custom' && adIcon.svg) {
                    // Admonition custom SVG icon — parse via DOMParser to avoid unsanitized innerHTML
                    const svgDoc = new DOMParser().parseFromString(adIcon.svg, 'image/svg+xml');
                    iconContainer.appendChild(svgDoc.documentElement);
                    const svgEl = iconContainer.querySelector('svg');
                    if (svgEl) {
                        svgEl.style.fill = typeInfo.color; // Set fill color for custom SVG
                        svgEl.style.width = "var(--icon-size)"; // Use Obsidian's icon size variable
                        svgEl.style.height = "var(--icon-size)";
                    }
                } else if ( adIcon.name.startsWith('lucide-')) {
                    // Admonition using a Lucide icon
                    setIcon(iconContainer, adIcon.name);
                    iconContainer.style.setProperty("--callout-color", typeInfo.color);
                } else if (adIcon.type === 'default') { // Admonition's own default icon handling
                    setIcon(iconContainer, adIcon.name); // May not always be a valid IconName
                    iconContainer.style.setProperty("--callout-color", typeInfo.color);
                } else {
                    // Other Admonition icon types not explicitly handled, use a placeholder
                    setIcon(iconContainer, "lucide-box");
                    iconContainer.style.setProperty("--callout-color", typeInfo.color);
                }
            } else {
                // Built-in callout type
                setIcon(iconContainer, typeInfo.icon as string);
                iconContainer.style.setProperty("--callout-color", typeInfo.color);
            }
        } else {
            // Fallback if typeInfo is not found (should not happen if dropdown is correct)
            setIcon(iconContainer, "lucide-alert-circle"); // Default error icon
            iconContainer.style.removeProperty("--callout-color");
        }
    }

    // private updateIconAndColor(iconContainer: HTMLElement, type: string) {
    //     // 查找类型定义，包括检查别名
    //     const typeInfo = this.calloutTypes.find(t =>
    //         t.type === type || t.aliases.includes(type)
    //     );

    //     if (typeInfo) {
    //         iconContainer.empty();
    //         setIcon(iconContainer, typeInfo.icon);
    //         // 设置图标颜色
    //         iconContainer.style.setProperty("--callout-color", typeInfo.color);
    //     }
    // }

    private insertCallout() {
        const editor = this.plugin.commandsManager.getActiveEditor();
        if (!editor) return;

        // 构建 callout 文本
        let calloutText = `> [!${this.type}]`;
        // 添加折叠状态
        if (this.collapse !== "none") {
            calloutText += `${this.collapse === "open" ? "+" : "-"}`;
        }
        // 添加标题
        if (this.title) {
            calloutText += ` ${this.title}`;
        }

        // 添加内容
        calloutText += `\n> ${this.content.replace(/\n/g, '\n> ')}`;

        // 获取当前光标位置
        const cursor = editor.getCursor();
        const line = editor.getLine(cursor.line);
        const isLineStart = cursor.ch === 0;

        let newCursorPos: { line: number, ch: number };

        if (editor.getSelection()) {
            // 如果有选中文本，直接替换
            if (!isLineStart && line.trim().length > 0) {
                calloutText = '\n' + calloutText;
            }
            const selectionStart = editor.getCursor('from');
            editor.replaceSelection(calloutText);

            // 计算新的光标位置（callout 下方）
            const calloutLines = calloutText.split('\n').length;
            newCursorPos = {
                line: selectionStart.line + calloutLines,
                ch: 0
            };
        } else {
            // 如果光标不在行首且当前行不为空，需要在下一行插入
            if (!isLineStart && line.trim().length > 0) {
                calloutText = '\n' + calloutText;
            }

            // 在光标位置插入
            editor.replaceRange(calloutText, cursor);

            // 计算新的光标位置（callout 下方）
            const calloutLines = calloutText.split('\n').length;
            newCursorPos = {
                line: cursor.line + calloutLines,
                ch: 0
            };
        }

        // 在下一个事件循环中设置光标位置，确保编辑器已更新
        window.setTimeout(() => {
            // 在 callout 下方插入一个空行
            editor.replaceRange('\n', newCursorPos);
            // 将光标移动到空行
            editor.setCursor({
                line: newCursorPos.line + 1,
                ch: 0
            });
            // 确保编辑器获得焦点
            editor.focus();
        }, 0);
    }
}

import { App, Modal,Editor,EditorPosition, Setting, TextComponent, ToggleComponent, Platform, setIcon, Notice, requestUrl, MarkdownView } from "obsidian";
import editingToolbarPlugin from "src/plugin/main";
import { t } from "src/translations/helper";

interface ClipboardItems {
    [key: string]: string;
}

   // 定义目标类型
interface LinkTarget {
    isImage: boolean;
    text: string;
    url: string;
    title: string;
    from: EditorPosition;
    to: EditorPosition;
}

class UrlTitleFetcher {
    private static htmlTitlePattern = /<title>([^<]*)<\/title>/im;
    private static wxTitlePattern = /<meta property="og:title" content="([^<]*)" \/>/im;

    // 检查是否为有效 URL
    private static isValidUrl(url: string): boolean {
        try {
            new URL(url);
            return true;
        } catch (err) {
            return false;
        }
    }

    private static parseTitle(url: string, body: string): string {
        const patterns = [
            url.includes('mp.weixin.qq.com') ? this.wxTitlePattern : null,
            this.htmlTitlePattern,
            /<title [^>]*>(.*?)<\/title>/i,
            /<meta name="title" content="([^<]*)" \/>/im
        ].filter(Boolean);

        for (const pattern of patterns) {
            const match = body.match(pattern);
            if (match && typeof match[1] === 'string') {
                return match[1].trim();
            }
        }

        throw new Error('Unable to parse the title tag');
    }

    // 获取默认标题
    public static getFallbackTitle(url: string): string {
        const pathMatch = url.match(/[^/\\]+$/);
        if (pathMatch) {
            return pathMatch[0]
                .replace(/\.[^/.]+$/, '')
                .replace(/[-_]/g, ' ')
                .trim();
        }
        return url;
    }

    // 异步获取远程标题
    public static async fetchRemoteTitle(url: string): Promise<string> {
        // 如果不是有效的 URL 或不是 http/https 开头，返回默认标题
        if (!this.isValidUrl(url) || !url.match(/^https?:\/\//)) {
            return this.getFallbackTitle(url);
        }

        try {
            const response = await requestUrl({
                url,
                method: 'GET',
                headers: {
                    'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/91.0.4472.124 Safari/537.36'
                },
                throw: true // 抛出异常以便捕获非 200 状态
            });

            if (response.status !== 200) {
                throw new Error(`Status code ${response.status}`);
            }

            const html = response.text;
            const title = this.parseTitle(url, html);

            // 如果标题为空或过长，返回默认标题
            if (!title || title.length > 100) {
                return this.getFallbackTitle(url);
            }

            return title;
        } catch (error) {
            console.error(`Failed to fetch title for ${url}:`, error);

            return this.getFallbackTitle(url);
        }
    }
}



export class InsertLinkModal extends Modal {
    private linkText: string = "";
    private linkUrl: string = "";
    private linkAlias: string = "";
    private isEmbed: boolean = false;
    private insertNewLine: boolean = false;
    private imageWidth: string = "";
    private imageHeight: string = "";
    private prefixText: string = "";
    private suffixText: string = "";
    private selectedText: string = "";
    private linkTextInput: TextComponent;
    private linkUrlInput: TextComponent;
    private linkAliasInput: TextComponent;
    private embedToggle: ToggleComponent;
    private urlErrorMsg: HTMLElement;
    private previewSetting: Setting;
    // URL 验证正则表达式
    private insertButton: HTMLElement;

    constructor(private plugin: editingToolbarPlugin) {
        super(plugin.app);

        const editor = this.plugin.commandsManager.getActiveEditor();
        if (editor) {
            const selectedText = editor.getSelection() || "";
            if (selectedText) {
                this.handleSelectedText(editor, selectedText);
            } else {
                this.handleCursorPosition(editor);
            }
        } else {
            void this.parseClipboard();
        }

        this.updateHeader();
    }

    // 处理选中文本
    private handleSelectedText(editor: Editor, selectedText: string) {
        const target = this.tryExpandSelection(editor, selectedText);
        if (target) {
            // 扩展选择并处理完整链接或图片
            const expandedText = this.formatTargetText(target);
            editor.setSelection(target.from, target.to);
            this.selectedText = expandedText;
            this.parseSelectedText(expandedText);
        } else {
            // 未找到完整链接，按原始选中文本处理
            this.selectedText = selectedText;
            this.parseSelectedText(selectedText);
        }
    }

    // 处理光标位置
    private handleCursorPosition(editor: Editor) {
        const cursor = editor.getCursor();
        const target = this.findLinkAtCursor(editor, cursor);
        if (target) {
            const formattedText = this.formatTargetText(target);
            editor.setSelection(target.from, target.to);
            this.selectedText = formattedText;
            this.parseSelectedText(formattedText);
        } else {
            void this.parseClipboard();
        }
    }

    // 尝试扩展选择范围，查找完整链接或图片
    private tryExpandSelection(editor: Editor, selectedText: string): LinkTarget | null {
        const cursorFrom = editor.getCursor('from');
        const line = editor.getLine(cursorFrom.line);
        const selectionStart = cursorFrom.ch;
        const selectionEnd = editor.getCursor('to').ch;

        return this.matchLinkInLine(line, selectionStart, selectionEnd, cursorFrom.line);
    }

    // 在光标位置查找链接或图片
    private findLinkAtCursor(editor: Editor, cursor: EditorPosition): LinkTarget | null {
        const line = editor.getLine(cursor.line);
        const cursorPosInLine = cursor.ch;

        return this.matchLinkInLine(line, cursorPosInLine, cursorPosInLine, cursor.line);
    }

   // 匹配行内的链接或图片，优先匹配 Markdown 格式，再匹配普通 URL
private matchLinkInLine(line: string, startPos: number, endPos: number, lineNumber: number): LinkTarget | null {
    // 优先匹配 Markdown 格式的链接或图片
    const markdownRegex = /(!)?\[([^\]]+)\]\(([^\s)]+)(?:\s+["']([^"']*)["'])?\)/g;
    let match;

    while ((match = markdownRegex.exec(line)) !== null) {
        const isImage = !!match[1];
        const linkStart = match.index;
        const linkEnd = match.index + match[0].length;
        const text = match[2];
        const url = match[3];
        const quotedTitle = match[4] || '';

        if (startPos <= linkEnd && endPos >= linkStart) {
            return {
                isImage,
                text,
                url,
                title: quotedTitle,
                from: { line: lineNumber, ch: linkStart },
                to: { line: lineNumber, ch: linkEnd }
            };
        }
    }

    // 如果 Markdown 格式未匹配到，尝试匹配普通 URL

   // 匹配非 Markdown 格式的 URL
   const urlRegex = /(?:^|\s)([a-zA-Z][a-zA-Z\d+\-.]*:\/\/\S+|\S+\.[a-zA-Z]{2,}(?:\/\S*)?)/g;

   while ((match = urlRegex.exec(line)) !== null) {
       const url = match[1]; // 获取完整 URL
       const linkStart = match.index + (match[0].startsWith(' ') ? 1 : 0); // 调整起始位置
       const linkEnd = linkStart + url.length;

       // 检查是否与选择范围重叠，并排除已经被 Markdown 匹配的 URL
       if (startPos <= linkEnd && endPos >= linkStart) {
           return {
               isImage: /\.(jpg|jpeg|png|gif|webp|bmp)$/i.test(url), // 根据文件扩展名判断是否为图片
               text: url,      // 使用 URL 作为默认文本
               url,
               title: '',
               from: { line: lineNumber, ch: linkStart },
               to: { line: lineNumber, ch: linkEnd }
           };
       }
   }

   return null;
}

    // 格式化目标文本
    private formatTargetText(target: LinkTarget): string {
        if (target.isImage) {
            return `![${target.text}](${target.url}${target.title ? ` "${target.title}"` : ''})`;
        }
        return target.title
            ? `[${target.text}](${target.url} "${target.title}")`
            : `[${target.text}](${target.url})`;
    }



    // 解析选中的文本
    private parseSelectedText(text: string) {
        // 解析图片链接
        const imglinkMatch = text.match(/!\[.*?\]\(.*?\)/);
        if (imglinkMatch) {
            const prefixText = text.substring(0, imglinkMatch.index); // 获取链接前的文本
            const suffixText = text.substring(imglinkMatch.index + imglinkMatch[0].length); // 获取链接后的文本
            const imageMatch = this.parseMarkdownImageLink(text);
            if (imageMatch) {
                this.linkText = imageMatch.title;
                this.linkUrl = imageMatch.url;
                this.linkAlias = imageMatch.quotedTitle || '';
                this.imageWidth = imageMatch.width || '';
                this.imageHeight = imageMatch.height || '';
                this.isEmbed = true;
                this.prefixText = prefixText;
                this.suffixText = suffixText;
                return;
            }
        }

        const linkMatch = text.match(/\[([^\]]+)\]\(([a-zA-Z]+:\/\/[^\s)]+)(?:\s+["']([^"']*)["'])?\)/);
        if (linkMatch) {
            const linkPart = linkMatch[0];
            const prefixText = text.substring(0, linkMatch.index); // 获取链接前的文本
            const suffixText = text.substring(linkMatch.index + linkPart.length); // 获取链接后的文本
            // 解析链接部分
            const parsedLink = this.parseMarkdownLink(linkPart);

            if (parsedLink) {
                this.linkText = parsedLink.text;
                this.linkUrl = parsedLink.url;
                this.linkAlias = parsedLink.title || ''; // 使用 text 作为默认别名
                this.isEmbed = false; // 默认非嵌入模式
            }

            // 保存前缀和后缀文本
            this.prefixText = prefixText;
            this.suffixText = suffixText;
        } else {
            // 如果没有找到链接格式，将整个文本作为链接文本
            const parsed = this.parseMixedContent(text);
            if (parsed) {
                this.linkText = parsed.title;
                this.linkUrl = parsed.url;
            }
        }
    }

    // 解析混合内容（标题和URL）
    private parseMixedContent(content: string): { title: string; url: string } | null {
        // 尝试匹配常见的浏览器复制格式

        // 格式1: 标题 https://url
        const titleUrlPattern = /^(.*?)\s*((?:https?:\/\/|www\.)\S+)$/i;

        // 格式2: [标题](url)
        const markdownPattern = /^\[(.*?)\]\((.*?)\)$/;

        // 格式3: <a href="url">标题</a>
        const htmlPattern = /<a[^>]+href=["']([^"']+)["'][^>]*>([^<]+)<\/a>/i;

        let match;

        // 尝试匹配 Markdown 格式
        if ((match = content.match(markdownPattern))) {
            return {
                title: match[1].trim(),
                url: match[2].trim()
            };
        }

        // 尝试匹配 HTML 格式
        if ((match = content.match(htmlPattern))) {
            return {
                title: match[2].trim(),
                url: match[1].trim()
            };
        }

        // 尝试匹配标题+URL格式
        if ((match = content.match(titleUrlPattern)) && match[1].trim()) {
            return {
                title: match[1].trim(),
                url: match[2].trim()
            };
        }

        // 检查是否只是一个URL
        if (this.isValidUrl(content.trim())) {
            return {
                title: this.extractTitleFromUrl(content.trim()),
                url: content.trim()
            };
        }

        return {
            title: content.trim(),
            url: ""
        };
    }

    // 从 URL 提取标题
    private extractTitleFromUrl(url: string): string {
        // 处理特殊协议
        const specialProtocolMatch = url.match(/^([a-zA-Z]+):\/\/(.+)$/);
        if (specialProtocolMatch) {
            const [, protocol, path] = specialProtocolMatch;
            // 如果是特殊协议，尝试提取最后一个路径段
            const segments = path.split(/[/\\]/);
            const lastSegment = segments[segments.length - 1];
            if (lastSegment) {
                return decodeURIComponent(lastSegment)
                    .trim();
            }
            // 如果无法提取有效的标题，返回协议名称
            return protocol.toUpperCase();
        }

        // 处理内部链接
        const wikiLinkMatch = url.match(/^\[\[(.*?)\]\]$/);
        if (wikiLinkMatch) {
            return wikiLinkMatch[1];
        }

        // 处理相对路径
        const pathMatch = url.match(/[^/\\]+$/);
        if (pathMatch) {
            return pathMatch[0]
                .replace(/\.[^/.]+$/, '')
                .replace(/[-_]/g, ' ')
                .trim();
        }

        return url;
    }

    // 更宽松的 URL 验证规则
    private isValidUrl(url: string): boolean {
        if (!url || url.includes('\n') || /\s/.test(url)) {
            return false;
        }

        // 支持的特殊协议列表
        const specialProtocols = [
            'obsidian://',
            'zotero://',
            'evernote://',
            'notion://',
            'bear://',
            'things://',
            'drafts://',
            'x-devonthink-item://',
            'file://',
            'ftp://',
            'ftps://',
            'http://',
            'https://',
            'tel:',
            'mailto:',
        ];

        // 检查特殊协议
        if (specialProtocols.some(protocol => url.startsWith(protocol))) {
            return true;
        }

        // 检查是否是内部链接格式
        if (url.match(/^\[\[.*?\]\]$/)) {
            return true;
        }

        // 检查是否是相对路径或本地文件路径
        if (url.match(/^[./\\]/) || // 以 ./ 或 ../ 开头
            url.match(/^[a-zA-Z]:\\/) || // Windows 路径
            url.match(/^\/[^/]/) ||// Unix 路径
            url.match(/^[a-zA-Z]+:\/\//)  // 标准 URL 格式
        ) {
            return true;
        }


        try {

            new URL(url);
            return true;
        } catch (e) {
            // 如果 URL 构造失败，检查是否符合基本格式
            // 允许几乎任何不包含空格的字符串作为 URL
            return false;
        }
    }

    // 解析 Markdown 图片链接格式
    private parseMarkdownImageLink(markdown: string): {
        title: string;
        url: string;
        width?: string;
        height?: string;
        quotedTitle?: string;
    } | null {
        // 匹配完整的图片链接格式，包括尺寸参数和可选标题
        // 格式1: ![title|widthxheight](url "optional title")
        // 格式2: ![title|width](url "optional title")
        // 格式3: ![title](url "optional title")
        const imageRegex = /!\[(.*?)(?:\|(\d+)(?:x(\d+))?)?\]\(\s*([^\s)]+)(?:\s+["']([^"']*)["'])?\s*\)/; const match = markdown.match(imageRegex);

        if (match) {
            const[, title , width, height, url, quotedTitle] = match;
            // 设置为嵌入模式
            this.isEmbed = true;
            // 如果 embedToggle 已经创建，更新其状态
            if (this.embedToggle) {
                this.embedToggle.setValue(true);
                // 显示图片尺寸设置
                const imageSizeEl = this.contentEl.querySelector('.image-size-setting');
                if (imageSizeEl) {
                    (imageSizeEl as HTMLElement).setCssStyles({ display: 'block' });
                }
            }

            return {
                title: title.trim(),
                url: url.trim(),
                width: width,
                height: height,
                quotedTitle: quotedTitle?.trim()
            };
        }
        return null;
    }

    private parseMarkdownLink(markdown: string): {
        text: string;
        url: string;
        title?: string;
    } | null {
        // 匹配 Markdown 链接格式，包括可选的 title
        const linkRegex = /\[([^\]]+)\]\(([a-zA-Z]+:\/\/[^\s)]+)(?:\s+["']([^"']*)["'])?\)/;
        const match = markdown.match(linkRegex);

        if (match) {
            const [, text, url, title] = match;
            return {
                text: text.trim(),
                url: url.trim(),
                title: title?.trim() // 可选的 title
            };
        }
        return null;
    }

    // 解析剪贴板内容
    private async parseClipboard() {
        try {
            const clipboardItems = await this.readClipboard();

            // 首先尝试解析为 Markdown 图片格式
            const plainText = clipboardItems['text/plain'];
            if (plainText) {
                const imageMatch = this.parseMarkdownImageLink(plainText);

                if (imageMatch) {
                    this.linkText = imageMatch.title;
                    this.linkUrl = imageMatch.url;
                    this.linkAlias = imageMatch.quotedTitle || '';
                    if (imageMatch.width || imageMatch.height) {
                        this.isEmbed = true; // 自动开启嵌入模式
                        this.imageWidth = imageMatch.width || '';
                        this.imageHeight = imageMatch.height || '';
                    }
                    this.updateUI();
                    return;
                }

                // 然后尝试解析为普通链接格式
                const linkMatch = this.parseMarkdownLink(plainText);
                if (linkMatch) {
                    this.linkText = linkMatch.text;
                    this.linkUrl = linkMatch.url;
                    this.linkAlias = linkMatch.title || '';
                    this.isEmbed = false;
                    this.updateUI();
                    return;
                }
            }

            // 其他格式的解析保持不变
            if (clipboardItems['text/html']) {
                // 解析 HTML 格式
                const parsed = this.parseHtmlContent(clipboardItems['text/html']);
                if (parsed) {
                    this.linkText = this.linkText || parsed.title;
                    this.linkUrl = parsed.url;
                }
            } else if (clipboardItems['text/markdown']) {
                // 解析 Markdown 格式
                const parsed = this.parseMarkdownContent(clipboardItems['text/markdown']);
                if (parsed) {
                    this.linkText = this.linkText || parsed.title;
                    this.linkUrl = parsed.url;
                }
            } else if (clipboardItems['text/plain']) {
                // 解析纯文本格式
                const parsed = this.parseMixedContent(clipboardItems['text/plain']);
                if (parsed) {
                    this.linkText = this.linkText || parsed.title;
                    this.linkUrl = parsed.url;
                }
            }

            this.updateUI();

        } catch (e) {
            console.error("Failed to read clipboard:", e);
        }
    }

    // 读取剪贴板多种格式
    private async readClipboard(): Promise<ClipboardItems> {
        const items: ClipboardItems = {};

        try {
            // 尝试读取剪贴板项目
            const clipboardItems = await navigator.clipboard.read();

            for (const clipboardItem of clipboardItems) {
                // 获取所有可用的类型
                const types = clipboardItem.types;

                for (const type of types) {
                    if (type === 'text/html' || type === 'text/plain' || type === 'text/markdown') {
                        const blob = await clipboardItem.getType(type);
                        items[type] = await blob.text();
                    }
                }
            }
        } catch (e) {
            // 如果无法访问剪贴板 API，回退到基本文本读取
            try {
                const text = await navigator.clipboard.readText();
                items['text/plain'] = text;
            } catch (e) {
                console.error("Failed to read clipboard:", e);
            }
        }

        return items;
    }

    // 解析 HTML 内容
    private parseHtmlContent(html: string): { title: string; url: string } | null {
        const parser = new DOMParser();
        const doc = parser.parseFromString(html, 'text/html');

        // 尝试找到链接元素
        const linkElement = doc.querySelector('a');
        if (linkElement) {
            return {
                title: linkElement.textContent?.trim() || '',
                url: linkElement.href
            };
        }

        // 如果没有找到链接元素，尝试解析文本内容
        const text = doc.body.textContent || '';
        return this.parseMixedContent(text);
    }

    // 解析 Markdown 内容
    private parseMarkdownContent(markdown: string): { title: string; url: string } | null {
        // 匹配 Markdown 链接格式 [title](url)
        const markdownLinkRegex = /\[([^\]]+)\]\(([^)]+)\)/;
        const match = markdown.match(markdownLinkRegex);

        if (match) {
            return {
                title: match[1].trim(),
                url: match[2].trim()
            };
        }

        // 如果不是 Markdown 链接格式，尝试解析普通文本
        return this.parseMixedContent(markdown);
    }

