export function getPickrSettings(opts: {
  isView: boolean;
  el: HTMLElement;
  containerEl: HTMLElement;
  swatches: string[];
  opacity: boolean | undefined;
  defaultColor: string;
}): Pickr.Options {
  const { el, containerEl, swatches, opacity, defaultColor } = opts;

  return {
    el,
    container: containerEl,
    theme: 'nano',
    swatches,
    lockOpacity: !opacity,
    default: defaultColor,
    position: 'left-middle',
    components: {
      preview: true,
      hue: true,
      opacity: !!opacity,
      interaction: {
        hex: true,
        rgba: false,
        hsla: false,
        input: true,
        cancel: true,
        save: true,
      },
    },
  };
}
export function getComandindex(item: any, arr: any[]): number {
  if (!arr || !Array.isArray(arr)) {
    return -1;
  }
  const idx = arr.findIndex((el) => el?.id === item);
  return idx;
}

export function moveItemBetweenLists<T>(
  source: T[],
  target: T[],
  item: T,
  targetIndex: number
): boolean {
  const sourceIndex = source.indexOf(item);
  if (sourceIndex < 0) return false;

  let insertIndex = Math.max(0, Math.min(targetIndex, target.length));
  if (source === target && sourceIndex < insertIndex) {
    insertIndex -= 1;
  }
  if (source === target && sourceIndex === insertIndex) return false;

  source.splice(sourceIndex, 1);
  target.splice(insertIndex, 0, item);
  return true;
}

