  private aestheticStyleMap: { [key: string]: string } = {
    default: "editingToolbarDefaultAesthetic",
    tiny: "editingToolbarTinyAesthetic",
    glass: "editingToolbarGlassAesthetic",
    custom: "editingToolbarCustomAesthetic",
    top: "top",
    following: "editingToolbarFlex",
    fixed: "fixed",
  };
  private applyAestheticStyle(element: HTMLElement, aestheticStyle: string, positionStyle: string) {
    // 移除所有美观风格类
    Object.values(this.aestheticStyleMap).forEach(className => {
      element.removeClass(className);
    });
    // 添加当前选择的美观风格类
    const selectedAestheticClass = this.aestheticStyleMap[aestheticStyle] || this.aestheticStyleMap.default;
    element.addClass(selectedAestheticClass);
    // 添加位置样式类
    const positionClass = this.aestheticStyleMap[positionStyle] || this.aestheticStyleMap.top; // 默认使用 top 样式
    element.addClass(positionClass);
  }
  // 辅助函数：根据类型获取命令数组
  private getCommandsArrayByType(type: string) {
    switch (type) {
      case 'following':
        return this.plugin.settings.followingCommands;
      case 'top':
        return this.plugin.settings.topCommands;
      case 'fixed':
        return this.plugin.settings.fixedCommands;
      case 'mobile':
        return this.plugin.settings.mobileCommands;
      default:
        return this.plugin.settings.menuCommands;
    }
  }
}

// Code from https://github.com/valentine195/obsidian-admonition/blob/master/src/lang/helpers.ts

import { moment } from 'obsidian';

import ar from './locale/ar';
import cz from './locale/cz';
import da from './locale/da';
import de from './locale/de';
import en from './locale/en';
import enGB from './locale/en-gb';
import es from './locale/es';
import fr from './locale/fr';
import hi from './locale/hi';
import id from './locale/id';
import it from './locale/it';
import ja from './locale/ja';
import ko from './locale/ko';
import nl from './locale/nl';
import no from './locale/no';
import pl from './locale/pl';
import pt from './locale/pt';
import ptBR from './locale/pt-br';
import ro from './locale/ro';
import ru from './locale/ru';
import tr from './locale/tr';
import zhCN from './locale/zh-cn';
import zhTW from './locale/zh-tw';

const localeMap: { [k: string]: Partial<typeof en> } = {
  ar,
  cs: cz,
  da,
  de,
  en,
  'en-gb': enGB,
  es,
  fr,
  hi,
  id,
  it,
  ja,
  ko,
  nl,
  nn: no,
  pl,
  pt,
  'pt-br': ptBR,
  ro,
  ru,
  tr,
  'zh-cn': zhCN,
  'zh-tw': zhTW,
};

const locale = localeMap[moment.locale()];

export function t(str: keyof typeof en | string): string {
  if (typeof str !== 'string' || str.length === 0) {
    return '';
  }

  return (
    (locale && locale[str as keyof typeof en]) ||
    en[str as keyof typeof en] ||
    str
  );
}

import { App, MarkdownView, requireApiVersion } from "obsidian";
let activeDocument: Document;
export function workplacefullscreenMode(app: App) {
    requireApiVersion("0.15.0") ? activeDocument = activeWindow.document : activeDocument = window.document;
    const currentleaf = activeDocument;


    if (app.workspace.leftSplit.collapsed && app.workspace.rightSplit.collapsed) {
        app.commands.executeCommandById("app:toggle-right-sidebar");
        app.commands.executeCommandById("app:toggle-left-sidebar");
        app.workspace.leftRibbon.show()

        if (currentleaf.body.classList.contains('auto-hide-header')) {

            currentleaf.body.classList.remove('auto-hide-header');
        }
    }
    else {

        if (!currentleaf.body.classList.contains('auto-hide-header')) {


            currentleaf.body.classList.add('auto-hide-header');
        }
        app.workspace.leftRibbon.hide()
        if (!app.workspace.leftSplit.collapsed) {
            app.commands.executeCommandById("app:toggle-left-sidebar");

        }
        if (!app.workspace.rightSplit.collapsed) {
            app.commands.executeCommandById("app:toggle-right-sidebar");
        }
    }


}


//full screen mode
export function fullscreenMode(app: App) {


    const DOC_EL = document.documentElement;
    let TYPE_REQUEST_FULL_SCREEN = 'requestFullscreen';
    let TYPE_EXIT_FULL_SCREEN = 'exitFullscreen';
    let TYPE_FULL_SCREEN_ELEMENT = 'fullscreenElement';
    let TYPE_ON_FULL_SCREEN_CHANGE = 'onfullscreenchange';
    if ("webkitRequestFullScreen" in DOC_EL) {
        TYPE_REQUEST_FULL_SCREEN = 'webkitRequestFullScreen';
        TYPE_EXIT_FULL_SCREEN = 'webkitExitFullscreen';
        TYPE_FULL_SCREEN_ELEMENT = 'webkitFullscreenElement';
        TYPE_ON_FULL_SCREEN_CHANGE = 'onwebkitfullscreenchange';
    }
    else if ("msRequestFullscreen" in DOC_EL) {
        TYPE_REQUEST_FULL_SCREEN = 'msRequestFullscreen';
        TYPE_EXIT_FULL_SCREEN = 'msExitFullscreen';
        TYPE_FULL_SCREEN_ELEMENT = 'msFullscreenElement';
        TYPE_ON_FULL_SCREEN_CHANGE = 'MSFullscreenChange';
    }
    else if ("mozRequestFullScreen" in DOC_EL) {
        TYPE_REQUEST_FULL_SCREEN = 'mozRequestFullScreen';
        TYPE_EXIT_FULL_SCREEN = 'mozCancelFullScreen';
        TYPE_FULL_SCREEN_ELEMENT = 'mozFullScreenElement';
        TYPE_ON_FULL_SCREEN_CHANGE = 'onmozfullscreenchange';
    }
    else if (!("requestFullscreen" in DOC_EL)) {
        // throw "\u5F53\u524D\u6D4F\u89C8\u5668\u4E0D\u652F\u6301Fullscreen API !";
    }
    const leaf = app.workspace.getActiveViewOfType(MarkdownView)
    if (!leaf)
        return;
    const el = leaf.containerEl;
    const modroot = document.body?.querySelector<HTMLElement>(".mod-vertical.mod-root .workspace-tab-container")
    const fullscreenMutationObserver: MutationObserver = new MutationObserver(function (mutationRecords) {
        mutationRecords.forEach(function (mutationRecord) {
            mutationRecord.addedNodes.forEach(function (node) {
                if (isFull(modroot)) {
                    try {

                        document.body.removeChild(node);
                        el.appendChild(node);
                    } catch (error) {
                      // 忽略节点移动失败（节点可能已被其他插件处理）
                    }

                } else {
                    return;
                }
            });
        });

    });
    modroot.addEventListener("fullscreenchange", function () {
        if (!isFull(modroot)) {
            fullscreenMutationObserver.disconnect();
        }
    });
    if (isFull(modroot)) {
        fullscreenMutationObserver.disconnect();

        exitFull()

    } else {

        beFull(modroot)
        fullscreenMutationObserver.observe(document.body, { childList: true });

    }

    // 添加类型定义
    interface HTMLElementWithFullscreen extends HTMLElement {
      [key: string]: any;
    }

    interface DocumentWithFullscreen extends Document {
      [key: string]: any;
    }

    // 修改相关代码
    function getCurrentElement(el: HTMLElement): HTMLElementWithFullscreen {
      return el;
    }

    function beFull(el: HTMLElement) {

        return getCurrentElement(el)[TYPE_REQUEST_FULL_SCREEN]();
    }
    exports.beFull = beFull;
    function exitFull() {
        return (document as DocumentWithFullscreen)[TYPE_EXIT_FULL_SCREEN](); // 类型收窄必需：动态全屏 API 键名

    }
    function isFull(el: any) {
        return getCurrentElement(el) === (document as DocumentWithFullscreen)[TYPE_FULL_SCREEN_ELEMENT];
    }
    function toggleFull(el: any) {
        if (isFull(el)) {
            exitFull();
            return false;
        }
        else {
            beFull(el);
            return true;
        }
    }
}

import { Editor, Notice } from "obsidian";
import { t } from "src/translations/helper";

export class TextEnhancement {
  /**
   * 获取无语法文本 - 去除 Markdown 语法后复制到剪贴板
   */
  static getPlainText(editor: Editor): void {
    const selection = editor.getSelection();
    if (!selection) {
      new Notice(t("Please select text first"));
      return;
    }

    const mdPattern =
      /(^#+\s|(^|\s+)#|^>|^\- \[( |x)\]|^\+ |<[^<>]+>|^1\. |^\-+$|^\*+$|==|\*+|~~|```|!*\[\[|\]\])/gm;
    const plainText = selection
      .replace(/\[([^\[\]]*)\]\([^\(\)]+\)/gim, "$1")
      .replace(mdPattern, "$2")
      .replace(/^[ ]+|[ ]+$/gm, "")
      .replace(/(\r\n|\n)+/gm, "\n");

    void navigator.clipboard.writeText(plainText);
    new Notice(t("Plain text copied to clipboard"));
  }

  /**
   * 批量插入空行 - 在每行之间插入空行
   */
  static insertBlankLines(editor: Editor): void {
    const text = editor.getValue();
    if (!text) return;

    const result = text.replace(/([^\n])\n([^\n])/g, "$1\n\n$2");
    editor.setValue(result);
  }

  /**
   * 批量去除空行 - 删除所有空白行
   */

  static processWhitespace(
    editor: Editor,
    options: {
      trim?: boolean; // 去除行首尾空格
      compress?: boolean; // 多个空格压缩为一个
      all?: boolean; // 删除所有空格（含全角）
      tabs?: boolean; // 删除/处理制表符
      removeEmptyLines?: boolean; // 删除所有空行（不留痕迹）
      compactEmptyLines?: boolean; // 压缩空行（连续多个空行合并为一个）
    } = {}
  ): void {
    const selection = editor.getSelection();
    if (!selection) {
      new Notice(t("Please select text first"));
      return;
    }

    let result = selection;

    // 1. 处理空格和制表符
    if (options.all) {
      result = result.replace(/[ \u3000\t]+/g, "");
    } else {
      if (options.tabs) result = result.replace(/\t/g, "");
      if (options.compress) result = result.replace(/[ \u3000]+/g, " ");
    }

    // 2. 按行处理逻辑
    let lines = result.split(/\r?\n/);

    if (options.trim) {
      lines = lines.map((line) => line.trim());
    }

    // 3. 处理空行逻辑
    if (options.removeEmptyLines) {
      // 彻底删除所有空行
      lines = lines.filter((line) => line.length > 0);
    } else if (options.compactEmptyLines) {
      // 压缩连续空行：将多个连续的空字符串合并为一个
      const newLines: string[] = [];
      for (let i = 0; i < lines.length; i++) {
        if (lines[i].length === 0 && i > 0 && lines[i - 1].length === 0) {
          continue;
        }
        newLines.push(lines[i]);
      }
      lines = newLines;
    }

    result = lines.join("\n");

    // 4. 特殊情况：如果开启了 removeEmptyLines，可能还需要处理首尾残留的换行
    if (options.removeEmptyLines) {
      result = result.trim();
    }

    editor.replaceSelection(result);
    new Notice(t("Whitespace cleaning completed"));
  }
  /**
   * 拆分多行 - 将选中文本按指定分隔符拆分成多行
   */
  static splitLines(editor: Editor): void {
    const selection = editor.getSelection();
    if (!selection) {
      new Notice(t("Please select text first"));
      return;
    }

    // 1. 尝试识别特殊模式（如数字列表）
    const listPattern = this.detectPattern(selection);

    let result: string[];

    if (listPattern) {
      // 如果识别到了数字列表模式 (1. 2. 3. 或 ① ②)
      result = selection
        .split(listPattern)
        .map((item) => item.trim())
        .filter((item) => item.length > 0);
      new Notice(t("List pattern detected, auto-split"));
    } else {
      // 2. 否则退回到之前的智能字符统计
      const sep = this.detectSeparator(selection);
      if (!sep) {
        new Notice(t("No obvious separator or list pattern detected"));
        return;
      }
      result = this.smartSplit(selection, sep);
      new Notice(`${t("Merged with")} '${sep}' ${t("Merge completed")}`);
    }

    editor.replaceSelection(result.join("\n"));
  }

  /**
   * 专门检测列表型模式
   */
  private static detectPattern(text: string): RegExp | null {
    // 模式 A: 阿拉伯数字列表 "1. ", "2. " (必须后面跟着点和空格，防止误伤小数)
    const numberedList = /\s?\d+[\.、]\s?/g;

    // 模式 B: 箭头或符号分隔 "→", "=>", ">"
    const arrowSymbol = /\s?[→=>]\s?/g;

    // 校验：如果匹配到的次数 > 1，说明这是一种规律模式
    if ((text.match(numberedList) || []).length > 1) return numberedList;
    if ((text.match(arrowSymbol) || []).length > 1) return arrowSymbol;

    return null;
  }
  /**
   * 智能拆分
   */
  private static smartSplit(text: string, separator: string): string[] {
    const parts: string[] = [];
    let current = "";
    let inQuote: string | null = null; // 记录当前在哪个闭合符内

    // 定义成对的闭合符号
    const pairs: Record<string, string> = {
      '"': '"',
      "'": "'",
      "“": "”",
      "‘": "’",
      "(": ")",
      "（": "）",
      "《": "》",
      "[": "]",
      "[[": "]]",
    };

    for (let i = 0; i < text.length; i++) {
      const char = text[i];

      if (!inQuote) {
        // 如果不在闭合区间内
        if (pairs[char]) {
          // 进入了闭合区间
          inQuote = pairs[char];
          current += char;
        } else if (char === separator) {
          // 遇到了真正的分隔符
          parts.push(current.trim());
          current = "";
        } else {
          current += char;
        }
      } else {
        // 如果在闭合区间内
        current += char;
        if (char === inQuote) {
          // 闭合区间结束
          inQuote = null;
        }
      }
    }

    if (current) parts.push(current.trim());

    // 过滤掉因为末尾分隔符产生的空项
    return parts.filter((p) => p.length > 0);
  }

  /**
   * 自动识别分隔符（依然保留）
   */
  private static detectSeparator(text: string): string | null {
    const candidates = ["、", "，", ",", ";", "；", "|", "·"];
    let maxCount = 0;
    let bestSeparator = null;

    candidates.forEach((sep) => {
      // 这里的统计也需要排除闭合区间内的符号，但简单统计通常也够用
      const count = text.split(sep).length - 1;
      if (count > maxCount) {
        maxCount = count;
        bestSeparator = sep;
      }
    });

    return bestSeparator;
  }
  /**
   * 智能粘贴 - 粘贴时自动处理格式
   */
  static async smartPaste(editor: Editor): Promise<void> {
    try {
      const text = await navigator.clipboard.readText();
      if (!text) return;

      // 移除多余空行
      let processed = text.replace(/(\r\n|\n){3,}/g, "\n\n");
      // 移除行尾空格
      processed = processed.replace(/[ \t]+$/gm, "");

      editor.replaceSelection(processed);
    } catch (err) {
      new Notice(t("Paste failed"));
    }
  }

  /**
   * 智能全角半角转换 - 自动感知语境并规范化排版
   */
  static smartTypography(editor: Editor): void {
    const selection = editor.getSelection();
    if (!selection || selection.trim().length === 0) {
      new Notice(t("Please select text first"));
      return;
    }

    // 1. 语境识别逻辑
    const cjkRegex = /[\u4e00-\u9fa5]/g;
    const cjkCount = (selection.match(cjkRegex) || []).length;
    // 中文字符占比超过 10% 判定为中文语境（转全角），否则为英文语境（转半角）
    const isChineseContext = cjkCount / selection.length > 0.1;

    let result = selection;

    // 2. 占位保护（避开代码、网址、链接、公式）
    const placeholders: string[] = [];
    const protectedPatterns = [
      /`[^`]+`/g,
      /\$[^$]+\$/g,
      /https?:\/\/[^\s)]+/g,
      /!\[.*?\]\(.*?\)/g,
      /\[.*?\]\(.*?\)/g,
    ];

    protectedPatterns.forEach((reg) => {
      result = result.replace(reg, (match) => {
        placeholders.push(match);
        return `__PROTECTED_${placeholders.length - 1}__`;
      });
    });

    // 3. 执行核心转换
    if (isChineseContext) {
      // --- 目标：规范化为【全角】标点 ---
      result = result
        .replace(/,/g, "，")
        .replace(/\.(?!\d)/g, "。")
        .replace(/;/g, "；")
        .replace(/:/g, "：")
        .replace(/\?/g, "？")
        .replace(/!/g, "！")
        .replace(/\(/g, "（")
        .replace(/\)/g, "）")
        .replace(/"([^"]*)"/g, "\u201c$1\u201d")
        // 额外福利：自动优化中英间距
        .replace(/([\u4e00-\u9fa5])([a-zA-Z0-9])/g, "$1 $2")
        .replace(/([a-zA-Z0-9])([\u4e00-\u9fa5])/g, "$1 $2");

      new Notice(t("Detected Chinese context: converted to full-width symbols"));
    } else {
      // --- 目标：规范化为【半角】标点 ---
      result = result
        .replace(/，/g, ", ")
        .replace(/。/g, ". ")
        .replace(/；/g, "; ")
        .replace(/：/g, ": ")
        .replace(/？/g, "? ")
        .replace(/！/g, "! ")
        .replace(/（/g, "(")
        .replace(/）/g, ")")
        .replace(/[""]/g, '"')
        .replace(/ {2,}/g, " "); // 压缩多余空格

      new Notice(t("Detected code/English context: converted to half-width symbols"));
    }

    // 4. 还原保护内容
    placeholders.forEach((val, index) => {
      result = result.replace(`__PROTECTED_${index}__`, val);
    });

    editor.replaceSelection(result);
  }
  /**
   * 去重 - 删除重复的行
   */
  static dedupe(
    editor: Editor,
    options: {
      includeEmpty?: boolean;
      trimBeforeCompare?: boolean; // 比较前忽略首尾空格
      sort?: boolean; // 去重后是否排序
    } = {}
  ): void {
    // 1. 仅处理选中文本，更安全
    const selection = editor.getSelection();
    if (!selection) {
      new Notice(t("Please select text to dedupe first"));
      return;
    }

    const lines = selection.split(/\r?\n/);
    const seen = new Set<string>();
    const result: string[] = [];

    for (const line of lines) {
      const content = options.trimBeforeCompare ? line.trim() : line;

      // 处理空行
      if (content === "") {
        if (options.includeEmpty) {
          if (!seen.has("")) {
            seen.add("");
            result.push(line);
          }
        } else {
          // 不包含空行去重时，保留原样空行（起到分隔作用）
          result.push(line);
        }
        continue;
      }

      // 非空行去重
      if (!seen.has(content)) {
        seen.add(content);
        result.push(line); // 放入原行（保留原始缩进）
      }
    }

    // 2. 排序逻辑
    if (options.sort) {
      result.sort((a, b) => a.localeCompare(b, "zh-CN", { numeric: true }));
    }

    editor.replaceSelection(result.join("\n"));
    new Notice(`${t("Deduplication completed, remaining")} ${result.length} ${t("lines")}`);
  }

  /**
   * 添加前后缀 - 为每行添加前缀和后缀
   */
  static addWrap(
    editor: Editor,
    prefix: string = "",
    suffix: string = "",
    excludeEmpty: boolean = true
  ): void {
    const selection = editor.getSelection();
    const useSelection = selection && selection.trim() !== "";
    const text = useSelection ? selection : editor.getValue();

    if (!text) return;

    const lines = text.split("\n");
    const result = lines
      .map((line) => {
        if (excludeEmpty && line.trim().length === 0) {
          return line;
        }
        return `${prefix}${line}${suffix}`;
      })
      .join("\n");

    if (useSelection) {
      editor.replaceSelection(result);
    } else {
      editor.setValue(result);
    }
    new Notice(t("Prefix/suffix added"));
  }

  /**
   * 添加序号
   */
  static numberList(
    editor: Editor,
    startNumber: number = 1,
    stepNumber: number = 1,
    separator: string = ". ",
    prefix: string = ""
  ): void {
    // 1. 只获取选中的文本
    const selection = editor.getSelection();
    if (!selection) {
      new Notice(t("Please select text to number first"));
      return;
    }

    const lines = selection.split("\n");
    let currentNum = startNumber;

    const result = lines
      .map((line) => {
        // 跳过纯空行
        if (line.trim() === "") return line;

        // 2. 智能清理：移除行首现有的数字序号模式 (如 "1. ", "2) ", "3、")
        // 正则解释：匹配开头可选的空格 + 数字 + [点/右括号/顿号] + 可选空格
        const cleanLine = line.replace(/^\s*\d+[\.\)）、]?\s*/, "");

        // 3. 组合新序号
        const numberedLine = `${prefix}${currentNum}${separator}${cleanLine}`;
        currentNum += stepNumber;
        return numberedLine;
      })
      .join("\n");

    // 4. 只替换选中的部分，不触动文档其他内容
    editor.replaceSelection(result);
    new Notice(`${t("Numbering completed: starting from")} ${startNumber}`);
  }

  /**
   * 提取两个字符串之间的内容
   */
  static extractBetween(
    editor: Editor,
    startStr: string,
    endStr: string
  ): void {
    if (!startStr && !endStr) {
      new Notice(t("Please specify start or end string"));
      return;
    }

    const text = editor.getValue();
    if (!text) return;

    try {
      // 转义正则特殊字符
      const escapeRegExp = (str: string) =>
        str.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");

      const s = escapeRegExp(startStr);
      const e = escapeRegExp(endStr);
      const pattern = new RegExp(`${s}(.*?)${e}`, "g");

      const matches: string[] = [];
      let match;
      while ((match = pattern.exec(text)) !== null) {
        if (match[1] !== undefined) {
          matches.push(match[1]);
        }
      }

      if (matches.length > 0) {
        editor.setValue(matches.join("\n"));
        new Notice(`${t("Extracted")} ${matches.length} ${t("matches")}`);
      } else {
        new Notice(t("No matches found"));
      }
    } catch (e) {
      new Notice(t("Extraction failed"));
    }
  }

  /**
   * 智能合并行 - 自动识别中英环境并处理间距
   */
  /**
   * 智能/自定义合并行
   */
  static mergeLines(
    editor: Editor,
    options: {
      separator?: string;
      preserveParagraphs?: boolean;
      trimLines?: boolean;
    }
  ): void {
    const selection = editor.getSelection();
    if (!selection || selection.trim() === "") {
      new Notice(t("Please select lines to merge first"));
      return;
    }

    const lines = selection.split(/\r?\n/);
    const hasCustomSep = options.separator !== "";
    let result = "";

    for (let i = 0; i < lines.length; i++) {
      const currentLine = options.trimLines ? lines[i].trim() : lines[i];

      // 处理空行
      if (currentLine === "") {
        if (options.preserveParagraphs && !hasCustomSep) {
          result += "\n\n";
        }
        continue;
      }

      if (result !== "" && !result.endsWith("\n")) {
        if (hasCustomSep) {
          // --- 强制模式：使用用户指定的符号 ---
          result += options.separator;
        } else {
          // --- 智能模式：判定中英连接 ---
          const lastChar = result.slice(-1);
          const firstChar = currentLine.charAt(0);
          const isCjkConnection =
            /[\u4e00-\u9fa5]/.test(lastChar) &&
            /[\u4e00-\u9fa5]/.test(firstChar);
          if (!isCjkConnection) result += " ";
        }
      }

      result += currentLine;
    }

    // 清理首尾和重复空格
    result = result.replace(/[ ]{2,}/g, " ").trim();

    editor.replaceSelection(result);
    new Notice(
      hasCustomSep ? `${t("Merged with")} '${options.separator}'` : t("Merge completed")
    );
  }

  /**
   * 列表转表格
   * 逻辑：顶级列表项为“行”，第二子级/缩进项自动合并为右侧单元格的“软换行”内容
   */
  static convertListToTableMultiDim(editor: Editor): void {
    const selection = editor.getSelection();
    if (!selection || selection.trim() === "") return;

    const lines = selection.split(/\r?\n/);
    const listRegex = /^((\s*)(?:[-*+]|\d+\.)\s+)(.*)/;

    // 1. 探测缩进基准与最大深度
    let maxLevel = 0;
    const indents = lines
      .map((l) => l.match(listRegex))
      .filter((m) => m && m[2].length > 0)
      .map((m) => {
        const len = m[2].replace(/\t/g, "    ").length;
        return len;
      });
    const finalTabSize = indents.length > 0 ? Math.min(...indents) : 4;

    // 预扫描：确定选区内的最大层级
    lines.forEach((line) => {
      const m = line.match(listRegex);
      if (m) {
        const level = Math.round(
          m[2].replace(/\t/g, " ".repeat(finalTabSize)).length / finalTabSize
        );
        if (level > maxLevel) maxLevel = level;
      }
    });

    // 2. 状态机解析
    const preText: string[] = [];
    const tableRows: string[][] = [];
    let currentRow: string[] = [];
    let isInsideTable = false;

    for (let i = 0; i < lines.length; i++) {
      const line = lines[i];
      const match = line.match(listRegex);

      if (match) {
        isInsideTable = true;
        const content = match[3].trim();
        const level = Math.round(
          (match[2] || "").replace(/\t/g, " ".repeat(finalTabSize)).length /
            finalTabSize
        );

        // --- 核心策略切换 ---
        if (maxLevel === 1) {
          // 【策略 A：只有两个层级】-> 固定两列，二级项转为软换行
          if (level === 0) {
            if (currentRow.length > 0) tableRows.push([...currentRow]);
            currentRow = [content, ""]; // 初始化 [顶级, 描述]
          } else {
            // 二级项：追加到第二列
            currentRow[1] = currentRow[1]
              ? currentRow[1] + "<br>" + content
              : content;
          }
        } else {
          // 【策略 B：三个或更多层级】-> 保持之前的多维映射逻辑
          if (currentRow[level] !== undefined) {
            tableRows.push([...currentRow]);
            currentRow = currentRow.slice(0, level);
          }
          currentRow[level] = content;
        }
      } else {
        // 处理非列表行 (软换行追加)
        if (!isInsideTable) {
          preText.push(line);
        } else if (line.trim() !== "") {
          const lastIdx = currentRow.length - 1;
          if (lastIdx >= 0) currentRow[lastIdx] += "<br>" + line.trim();
        }
      }
    }
    if (currentRow.length > 0) tableRows.push(currentRow);

    // 3. 渲染
    const finalizedRows =
      maxLevel === 1 ? tableRows : this.applyVisualMerge(tableRows);
    this.renderFinalResult(editor, preText, finalizedRows, [], maxLevel + 1);
  }
  private static applyVisualMerge(tableRows: string[][]): string[][] {
    let lastPushedRow: string[] = [];
    return tableRows.map((row, rowIndex) => {
      if (rowIndex === 0) {
        lastPushedRow = [...row];
        return row;
      }
      const processedRow = row.map((cell, colIndex) => {
        const isPathSame = row
          .slice(0, colIndex)
          .every((c, i) => c === lastPushedRow[i] || c === "");
        if (isPathSame && cell === lastPushedRow[colIndex]) return "";
        return cell;
      });
      lastPushedRow = [...row];
      return processedRow;
    });
  }

  /**
   * 渲染最终输出，包含 Markdown 环境补全
   */
  private static renderFinalResult(
    editor: Editor,
    pre: string[],
    rows: string[][],
    post: string[],
    maxCols: number
  ) {
    const header =
      "| " +
      Array.from({ length: maxCols }, (_, i) =>
        i === 0 ? t("Item") : `${t("Content")} ${i}`
      ).join(" | ") +
      " |\n";
    const sep =
      "| " + Array.from({ length: maxCols }, () => "---").join(" | ") + " |\n";
    const body = rows
      .map((row) => {
        // 确保每一行都有足够的单元格，空位补白
        const fullRow = Array.from({ length: maxCols }, (_, i) =>
          (row[i] || "").replace(/\|/g, "\\|")
        );
        return `| ${fullRow.join(" | ")} |`;
      })
      .join("\n");

    const tableMarkdown = header + sep + body;

    // 组装前置、表格、后置内容
    let finalContent = "";

    if (pre.length > 0) {
      finalContent += pre.join("\n").trimEnd() + "\n\n";
    }

    finalContent += tableMarkdown;

    if (post.length > 0) {
      finalContent += "\n\n" + post.join("\n").trimStart();
    }

    // --- 4. 智能环境修正 (防止与上方已有文字粘连) ---
    const cursor = editor.getCursor("from");
    if (cursor.line > 0 && pre.length === 0) {
      const prevLine = editor.getLine(cursor.line - 1);
      if (prevLine.trim() !== "") {
        finalContent = "\n" + finalContent;
      }
    }

    editor.replaceSelection(finalContent);
    new Notice(t("Super conversion completed: context preserved and layout optimized"));
  }

  /**
   * 表格转列表 - 将 Markdown 表格还原为多级大纲
   * 支持源码模式和实时预览模式
   */
  static convertTableToList(editor: Editor): void {
    let selection = editor.getSelection();

    // 如果选中的内容不包含 |，可能是在实时预览模式下
    // 尝试从光标位置获取完整的表格
    if (!selection || !selection.includes("|")) {
      const cursor = editor.getCursor("from");
      const totalLines = editor.lineCount();

      // 向上查找表格开始
      let startLine = cursor.line;
      while (startLine > 0) {
        const line = editor.getLine(startLine - 1);
        if (line.includes("|")) {
          startLine--;
        } else {
          break;
        }
      }

      // 向下查找表格结束
      let endLine = cursor.line;
      while (endLine < totalLines - 1) {
        const line = editor.getLine(endLine + 1);
        if (line.includes("|")) {
          endLine++;
        } else {
          break;
        }
      }

      // 如果找到了表格，获取完整内容
      if (startLine <= endLine) {
        const tableLines: string[] = [];
        for (let i = startLine; i <= endLine; i++) {
          const line = editor.getLine(i);
          if (line.includes("|")) {
            tableLines.push(line);
          }
        }

        if (tableLines.length > 0) {
          selection = tableLines.join("\n");
          // 选中整个表格
          editor.setSelection(
            { line: startLine, ch: 0 },
            { line: endLine, ch: editor.getLine(endLine).length }
          );
        }
      }
    }

    // 再次检查是否有有效的表格内容
    if (!selection || !selection.includes("|")) {
      new Notice(t("Please select a valid Markdown table"));
      return;
    }

    const lines = selection.split(/\r?\n/);
    const result: string[] = [];

    for (const line of lines) {
      // 跳过表头分割线 (如 | --- | --- |) 和空行
      if (line.match(/^\s*\|?[\s\-:|]+\|?\s*$/) || line.trim() === "") continue;

      // 解析单元格内容，去除首尾管道符并分割
      const cells = line
        .trim()
        .replace(/^\|/, "")
        .replace(/\|$/, "")
        .split("|")
        .map((c) => c.trim());

      // 如果是表头行（通常是第一行），用户可能不需要转为列表，可以根据需求跳过
      // 这里我们简单处理，把每一行非空单元格转为层级
      cells.forEach((cell, index) => {
        if (cell !== "" && cell !== t("Item") && !cell.startsWith(t("Content"))) {
          const indent = "  ".repeat(index); // 每级增加两个空格
          result.push(`${indent}- ${cell}`);
        }
      });
    }

    editor.replaceSelection(result.join("\n"));
    new Notice(t("Table converted to multi-level list"));
  }
}

